  ui_story_5004_50040101_3_dialog_content = "(울렁거리는 파도에 나는 몸이 뒤집어질 뻔했다.)",
  ui_story_5004_50040101_4_dialog_content = "(구름이 짙게 드리워진 검붉은 하늘에선 천둥이 내 고막을 때렸고...)",
  ui_story_5004_50040101_5_dialog_content = "(하늘에선 운석이 끝없이 떨어져 우리를 향해 날아왔다.)",
  ui_story_5004_50040101_6_dialog_content = "(머나먼 바닷속에서는 내 마음속 절망처럼 불길한 검은 성이\n서서히 솟아오르고 있었다.)",
  ui_story_5004_50040101_7_dialog_content = "(바이스와 카렌은 내 앞에 서서 나를 지키려 했지만,\n그저 무의미한 저항으로 느껴질 뿐이었다...)",
  ui_story_5004_50040101_8_dialog_content = "(모든 것은... 이미 되돌릴 수 없게 되었다.)",
  ui_story_5004_50040101_9_dialog_content = "(나는 전혀 알지 못했다... 그때 내 선택이 불러온 재앙이\n이렇게 모든 것을 파괴하게 될 거라는 사실을...)",
  ui_story_5004_50040101_10_dialog_content = "그럼 잘 돌봐주길 바랄게. 난 이만 가 볼 테니까.",
  ui_story_5004_50040101_11_dialog_content = "자, 잠깐만, 갑자기 여자애를 데려와서 나한테 맡기질 않나...\n대체 날 뭐라고 생각하는 거야?",
  ui_story_5004_50040101_12_dialog_content = "심지어 난 얘 이름이 뭔지도 아직 모른다고.",
  ui_story_5004_50040101_13_dialog_content = "......",
  ui_story_5004_50040101_14_dialog_content = "저기...",
  ui_story_5004_50040101_15_dialog_content = "난...",
  ui_story_5004_50040101_16_dialog_content = "<color=#FFB400>베릴</color>이라고 해. 그럼 이제부터 서로 친구인 거야. 알겠지? 그럼 이만...",
  ui_story_5004_50040101_17_dialog_content = "거기 서! 그러니까 뭐가 어떻게 된 건지 제대로 좀 설명해 봐.",
  ui_story_5004_50040101_18_dialog_content = "그래? PlayerName 네가 진리를 그토록 갈구한다면...",
  ui_story_5004_50040101_19_dialog_content = "그만... 진리 얘긴 됐어. 아무튼 그러니까...",
  ui_story_5004_50040101_20_dialog_content = "......",
  ui_story_5004_50040101_21_dialog_content = "베릴 맞지? 얘가 <color=#FFB400>무슨 병에 걸렸다고</color>?",
  ui_story_5004_50040101_22_dialog_content = "몰라.",
  ui_story_5004_50040101_23_dialog_content = "뭐, 뭐야?",
  ui_story_5004_50040101_24_dialog_content = "나도 모르니까 너한테 맡기는 거야.",
  ui_story_5004_50040101_25_dialog_content = "넌 감응 능력을 지닌 아이테르고, 네 주변엔 치유의 루미나틱스를 다루는 데\n능숙한 오로리안이 많이 있어.",
  ui_story_5004_50040101_26_dialog_content = "그래서 빅토리아 님과 난 네가 이 아이를 잘 돌볼 수 있다고 생각했거든.",
  ui_story_5004_50040101_27_dialog_content = "너네 진리의 결사가... 언제부터 자선 단체가 된 건데...?",
  ui_story_5004_50040101_28_dialog_content = "......",
  ui_story_5004_50040101_29_dialog_content = "잠깐만, 파우스트, 잠깐 이리 좀...",
  ui_story_5004_50040101_30_dialog_content = "저기...",
  ui_story_5004_50040101_31_dialog_content = "혹시 쟤...",
  ui_story_5004_50040101_32_option_content = "빅토리아 씨 딸은 아니지?",
  ui_story_5004_50040101_33_dialog_content = "아니, 빅토리아 님은 오직 진리를 추구하는 길에만 흔들림 없이 나아가실 뿐,\n그런 세속적인 욕망은 없는 분이야.",
  ui_story_5004_50040101_34_option_content = "무슨 기괴한 의식의 희생양은 아니지?",
  ui_story_5004_50040101_35_dialog_content = "물론 아니지. 진리를 향한 우리의 탐구를 매도하지 않았으면\n좋겠는데 말이야.",
  ui_story_5004_50040101_36_dialog_content = "게다가 베릴 양은 진리의 결사의 고위 간부라고.",
  ui_story_5004_50040101_37_dialog_content = "으음...",
  ui_story_5004_50040101_38_dialog_content = "응, 아무튼 무슨 수상한 계획이 있는 것만 아니면 됐어...",
  ui_story_5004_50040101_39_dialog_content = "근데 빅토리아 씨가 왜 날 선택했는지는 아직도 이해가 잘 안 돼.",
  ui_story_5004_50040101_40_dialog_content = "빅토리아 님의 뜻은 우리가 이해하려 들 필요가 없을 때가 많지.",
  ui_story_5004_50040101_41_dialog_content = "그분의 뜻을 힘써 관철하고, 그분의 명령을 성실히 수행한다면,\n우린 진리에 다가갈 수 있을 거야.",
  ui_story_5004_50040101_42_dialog_content = "(또 수상한 말로 얼렁뚱땅 넘어가려고 하는 거 보면\n역시 의심스럽단 말이지...)",
  ui_story_5004_50040101_43_dialog_content = "알겠어. 마침 라파엘이 콜로서스에 있으니까, 가서 한번 물어볼게.",
  ui_story_5004_50040101_44_dialog_content = "<color=#e8d9bb>몇 분 후</color>",
  ui_story_5004_50040101_45_dialog_content = "으음~",
  ui_story_5004_50040101_46_dialog_content = "음... 흠흠~",
  ui_story_5004_50040101_47_dialog_content = "어떻습니까, 천사 아가씨.",
  ui_story_5004_50040101_48_dialog_content = "지금 쓸 수 있는 방법으로는... 몸에서 아무런 이상도 발견하지 못했어!",
  ui_story_5004_50040101_49_dialog_content = "베릴이라고 했지?",
  ui_story_5004_50040101_50_dialog_content = "응...",
  ui_story_5004_50040101_51_dialog_content = "흠흠, 그럼 우리 꼬마 친구 베릴, 어디 몸이 불편한 데가 있니?\n의사선생님한테 말해 봐!",
  ui_story_5004_50040101_52_dialog_content = "꼬마... 친구...",
  ui_story_5004_50040101_53_dialog_content = "미안... 난 내 몸의 감각을 느끼는 게 조금 느리거든...",
  ui_story_5004_50040101_54_dialog_content = "근데 요즘 들어서 자꾸 피곤하다는 느낌이 들어...\n그리고 루미나를 다루는 능력도 무척 불안정해졌어...",
  ui_story_5004_50040101_55_dialog_content = "가끔은 온몸에 심한 통증이 느껴지는데...\n마치 개미가 온몸을 무는 것 같은 느낌이야...",
  ui_story_5004_50040101_56_dialog_content = "그렇구나...",
  ui_story_5004_50040101_57_dialog_content = "라파엘도 베릴 같은 증세를 가진 환자는 처음이거든.",
  ui_story_5004_50040101_58_dialog_content = "PlayerName, 넌 어떻게 생각해?",
  ui_story_5004_50040101_59_dialog_content = "(베릴이 계속 인상을 찌푸리고 있어. 뭔가 고민이 있는 것 같네.)",
  ui_story_5004_50040101_60_option_content = "뭔가 고민이 있는 게 아닐까?",
  ui_story_5004_50040101_61_dialog_content = "그럴 수도 있어!",
  ui_story_5004_50040101_62_dialog_content = "카렌 언니도 성주님이랑 말다툼을 벌이고 나면 매번 저런 표정을 짓거든.",
  ui_story_5004_50040101_63_dialog_content = "우리 베릴이랑 완전 똑같다니까.",
  ui_story_5004_50040101_64_option_content = "아니면 내 감응 능력을 한번 써볼까?",
  ui_story_5004_50040101_65_dialog_content = "안 돼! 여자애의 마음을 들여다보는 건 무례한 짓이야!",
  ui_story_5004_50040101_66_dialog_content = "마치 치료를 하겠다고 피부부터 곧바로 절개하는 것처럼 난폭한 짓이라구!",
  ui_story_5004_50040101_67_dialog_content = "아무튼!",
  ui_story_5004_50040101_68_dialog_content = "몸이든 정신이든 환자는 모두 이 라파엘한테 맡겨줘!",
  ui_story_5004_50040101_69_dialog_content = "우리 꼬마 친구, 걱정할 거 없어요~\n내가 주치의가 돼서 계속 곁에 있어 줄 테니까!",
  ui_story_5004_50040101_70_dialog_content = "그리고 꼭 병의 원인을 찾고 「단숨에 치료」해서\n널 다시 건강하게 만들어 줄게!",
  ui_story_5004_50040101_71_dialog_content = "단숨에... 단번에 숨이 넘어간다는 뜻은 아니지...?",
  ui_story_5004_50040101_72_dialog_content = "PlayerName~!",
  ui_story_5004_50040101_X72_dialog_content = "환자 앞에서 그런 농담은 하지 말아줘!",
  ui_story_5004_50040101_73_dialog_content = "고마워...",
  ui_story_5004_50040101_74_dialog_content = "어라, 다들 왜 여기 모여 있는 거야?",
  ui_story_5004_50040101_75_dialog_content = "PlayerName, 안녕. 라파엘도 있었구나.",
  ui_story_5004_50040101_76_dialog_content = "아, 카렌 언니~ 여긴 무슨 일로 온 거야?",
  ui_story_5004_50040101_77_dialog_content = "난 백야성을 대표해서 조종사와 정기적으로 연락하고 있어.\n그리고 바이스와 개인적으로 할 이야기도 있었거든.",
  ui_story_5004_50040101_78_dialog_content = "이쪽은...",
  ui_story_5004_50040101_79_dialog_content = "여긴 파우스트야.",
  ui_story_5004_50040101_80_dialog_content = "반갑습니다. 고귀하신 레이디.",
  ui_story_5004_50040101_81_dialog_content = "당신... <color=#FFB400>진리의 결사</color> 쪽 사람이지?",
  ui_story_5004_50040101_82_dialog_content = "진리의 결사를 알고 계실 줄은 몰랐군요.",
  ui_story_5004_50040101_83_dialog_content = "설마 당신도 진리를 추구하는 분인가요?",
  ui_story_5004_50040101_84_dialog_content = "난 「진리」니 뭐니 하는 것엔 관심 없어. 난 나만의 신념이 있으니까.",
  ui_story_5004_50040101_85_dialog_content = "정말 유감이군요.",
  ui_story_5004_50040101_86_dialog_content = "그래도 다행인 점이라면... 당신이 진리에 대해 평가하기 시작한 순간,\n이는 곧 당신이 진리를 향해 또 한 걸음을 내디뎠다는 뜻이 된답니다.",
  ui_story_5004_50040101_87_dialog_content = "아마 우린 같은 종점에서 재회하게 될 겁니다.",
  ui_story_5004_50040101_88_dialog_content = "말만 번지르르한 사람이네... PlayerName, 이 여자애는 누구지?",
  ui_story_5004_50040101_89_dialog_content = "베릴이라고 해. 파우스트가 나한테 돌봐달라고 부탁했어...\n아마 파우스트의 친구인 모양이야.",
  ui_story_5004_50040101_90_dialog_content = "카렌 언니~ 베릴은 이제 내 환자야.",
  ui_story_5004_50040101_91_dialog_content = "그렇구나... 잘하고 있어, 라파엘.",
  ui_story_5004_50040101_92_dialog_content = "백야의 명예를 더럽히지 않도록 최선을 다해서 환자를 돌봐주길 바랄게.",
  ui_story_5004_50040101_93_dialog_content = "음후훗~ 당연하지!",
  ui_story_5004_50040101_94_dialog_content = "근데 아직 베릴이 어떤 병을 앓고 있는지는 알아내지 못했어...",
  ui_story_5004_50040101_X94_dialog_content = "지금은 그저 심리적 문제가 아닐까 추측하고 있을 뿐이야...\n아니면 스트레스를 너무 많이 받는다든지...",
  ui_story_5004_50040101_95_dialog_content = "라파엘은 심리적인 병도 치료할 수 있는 거야?\n역시 미사일만 쏘는 전투 천사가 아니었던 모양이네!",
  ui_story_5004_50040101_96_dialog_content = "헤헤, 백야성의 천사를 무시하면 안 되지, 바이스~",
  ui_story_5004_50040101_97_dialog_content = "(라파엘이랑 바이스도 사이가 무척 좋아진 것 같네... 정말 잘됐어.)",
  ui_story_5004_50040101_98_dialog_content = "PlayerName? 뭘 바보같이 웃고 있어? 자, 내가 좋은 걸 가져왔어.",
  ui_story_5004_50040101_99_dialog_content = "어쩌면 이게 너한테 도움이 될지도 몰라.",
  ui_story_5004_50040101_100_dialog_content = "자, 너한테 온 편지야.",
  ui_story_5004_50040101_101_dialog_content = "편지? 나한테?",
  ui_story_5004_50040101_102_dialog_content = "방금 에호가 주고는 가버렸어.\n<color=#FFB400>「플라티나 선라이즈 호텔」</color>에서 보낸 거라나 뭐라나.",
  ui_story_5004_50040101_103_dialog_content = "근데 아무리 봐도 보낸 사람이 누구인지 안 쓰여 있었어.",
  ui_story_5004_50040101_104_dialog_content = "한번 뜯어볼래?",
  ui_story_5004_50040101_105_option_content = "조금 수상한데... 일단 열지 말자.",
  ui_story_5004_50040101_106_dialog_content = "그렇게 겁먹을 거 없잖아. 뭐 어때, 괜찮아.",
  ui_story_5004_50040101_107_dialog_content = "그럼 내가 뜯어줄게. 얍!",
  ui_story_5004_50040101_108_dialog_content = "아, 혹시라도 폭발하면 어떡하려고...!",
  ui_story_5004_50040101_109_dialog_content = "안에 든 건 종이 한 장뿐이야. 그냥 평범한 종이 같아.\n겉면은 무늬가 있는 시트지고.",
  ui_story_5004_50040101_110_dialog_content = "아무 일도 없어서 다행이네...",
  ui_story_5004_50040101_111_option_content = "괜찮겠지? 뜯어보자.",
  ui_story_5004_50040101_112_dialog_content = "얼른 뜯어 봐, 얼른. 안에 뭐가 있는지 나도 궁금하단 말이야.",
  ui_story_5004_50040101_113_dialog_content = "음? 그냥 종이 한 장뿐인데?",
  ui_story_5004_50040101_114_dialog_content = "그게 다야?",
  ui_story_5004_50040101_115_dialog_content = "PlayerName, 뭐라고 쓰여 있는데?",
  ui_story_5004_50040101_116_dialog_content = "으음...",
  ui_story_5004_50040101_117_dialog_content = "To. PlayerName",
  ui_story_5004_50040101_118_dialog_content = "귀하의 멋진 여름 휴가를 위해 플라티나 선라이즈 호텔로 초대합니다.",
  ui_story_5004_50040101_X118_dialog_content = "저희가 정성을 다해 준비한 <color=#FFB400>해신제</color> 행사에\n참가해 주시기 바랍니다.",
  ui_story_5004_50040101_119_dialog_content = "그리고 초대장이 있어. 여섯 명까지 일행을 데려와도 된대.",
  ui_story_5004_50040101_120_dialog_content = "뭐야... 게다가 무료로 호텔의 스위트룸과\n모든 오락 시설을 즐길 수 있다고...?!",
  ui_story_5004_50040101_121_dialog_content = "그거 잘됐네! 안 그래도 마침 바다에 놀러 가고 싶었는데!",
  ui_story_5004_50040101_122_dialog_content = "축제라면... 베릴한테도 도움이 될 것 같아!",
  ui_story_5004_50040101_123_dialog_content = "가서 즐겁게 놀고 기분 전환을 하면 분명히 속상한 마음도 달랠 수 있을 거야!",
  ui_story_5004_50040101_124_dialog_content = "PlayerName, 그럼 베릴이랑 다 같이 가자~ 응? 가자~ 가자~",
  ui_story_5004_50040101_125_dialog_content = "잠깐만, 아직 뭐가 어떻게 된 건지도 잘 모르잖아.\n이름도 들어본 적 없는 곳이고...",
  ui_story_5004_50040101_126_dialog_content = "걱정 마, PlayerName. 그 호텔 사실 꽤 유명하거든.",
  ui_story_5004_50040101_127_dialog_content = "맞아. 플라티나 선라이즈 호텔은 최근 몇 년 동안 백야성의 귀족들 사이에서\n꽤 이름이 알려졌어. 나까지도 이름을 들어본 적이 있으니 말이야.",
  ui_story_5004_50040101_128_dialog_content = "그리고 그 호텔의 오너가 경영 능력이 무척 뛰어나다고 들었거든.",
  ui_story_5004_50040101_129_dialog_content = "이 초대장과 「해신제」도 아마 모종의 홍보 활동일 거야.",
  ui_story_5004_50040101_130_dialog_content = "근데 왜 하필 날 초대한 걸까?",
  ui_story_5004_50040101_131_dialog_content = "아마 그것도 일종의 경영 전략이겠지.",
  ui_story_5004_50040101_132_dialog_content = "대부분의 오로리안들은 「아이테르」에 대해 호기심을 느낄 테니 말이야.",
  ui_story_5004_50040101_133_dialog_content = "그럼 아이테르가 방문한 호텔, 아이테르가 머물렀던 방, 아이테르가 사용했던\n식탁 모두 관광 명소가 돼서 호텔 홍보에 이용할 수 있어.",
  ui_story_5004_50040101_134_dialog_content = "그렇게 말하니까 꼭 무슨 희귀 동물이 된 것 같잖아...",
  ui_story_5004_50040101_135_dialog_content = "......",
  ui_story_5004_50040101_136_dialog_content = "......",
  ui_story_5004_50040101_137_dialog_content = "...조금이라도 부정해줄 순 없어?",
  ui_story_5004_50040101_138_dialog_content = "뭐, 백야성의 귀족들도 가는 휴양지라면... 우리한테도 이득 아닐까?",
  ui_story_5004_50040101_139_dialog_content = "딱히 위험할 것 같진 않아.",
  ui_story_5004_50040101_140_dialog_content = "그럼 의견이 모두 일치하는 것 같군요.",
  ui_story_5004_50040101_141_dialog_content = "뭐야, 아직도 안 갔어?",
  ui_story_5004_50040101_142_dialog_content = "아무쪼록 베릴을 잘 부탁할게. 즐거운 휴가 보내고 와. 그럼 난 이만.",
  ui_story_5004_50040101_143_dialog_content = "...파우스트 씨는 정말 바람처럼 왔다가 사라진다니까.",
  ui_story_5004_50040101_144_dialog_content = "좋아! 베릴, 그럼 내가 주치의로서 책임지고 잘 돌봐줄게~!",
  ui_story_5004_50040101_145_dialog_content = "뭔가... 이렇게 간단한 일이 아닐 것 같다는 예감이 드는데 말이지...",
  ui_story_5004_50040101_146_dialog_content = "저길 봐! 벌써 바다가 보여!",
  ui_story_5004_50040101_147_dialog_content = "난 바다를 보는 건 이번이 처음이거든, PlayerName.",
  ui_story_5004_50040101_148_dialog_content = "어라? 바이스 너도?",
  ui_story_5004_50040101_149_dialog_content = "나만 그런 줄 알았는데...",
  ui_story_5004_50040101_150_dialog_content = "너만 그런 게 아냐. 콜로서스 없이는 이렇게 먼 곳까지\n이동하는 건 쉽지 않으니까.",
  ui_story_5004_50040101_151_dialog_content = "바닷바람이 정말 시원해. 저렇게 예쁜 파란색 바다를 보고 있으면\n마음이 후련해지는 것 같아.",
  ui_story_5004_50040101_152_dialog_content = "그럼 베릴의 회복에도 도움이 될 거야!",
  ui_story_5004_50040101_153_dialog_content = "너... 말로는 베릴을 위해서라고 하면서,\n사실은 그냥 네가 바다에 가서 놀고 싶은 거지?",
  ui_story_5004_50040101_154_dialog_content = "뭐, 그것도 틀린 말은 아니긴 해.",
  ui_story_5004_50040101_155_dialog_content = "대부분의 오로리안들은 바다에 갈 기회가 거의 없는걸.",
  ui_story_5004_50040101_156_dialog_content = "넌 계속 콜로서스에서 살아왔으니까, 아마 잘 모를 거야.",
  ui_story_5004_50040101_157_dialog_content = "휴가를 위해 해변에 가는 건 지금의 오로리안들에겐\n<color=#FFB400>용기가 필요한 엄청난 모험</color>이거든!",
  ui_story_5004_50040101_158_dialog_content = "왜 그런 건데...?",
  ui_story_5004_50040101_159_dialog_content = "생각해 봐. 지금 대부분의 해안가에는 암귀들이 떠돌고 있어.",
  ui_story_5004_50040101_160_dialog_content = "태양과 파도를 즐기려면 암귀의 갑작스러운 공격에도\n항상 대처할 준비가 되어 있어야 해.",
  ui_story_5004_50040101_161_dialog_content = "편안함과 위험이 공존하는 이 느낌... 스릴 넘치는 모험 같잖아! 안 그래?",
  ui_story_5004_50040101_162_dialog_content = "그게 모험이라고...? 그냥 위험 같은데...",
  ui_story_5004_50040101_163_dialog_content = "만약 내가 모래사장에 묻혀서 머리만 내놓고 놀고 있을 때\n갑자기 암귀가 나타나면 어떡해?",
  ui_story_5004_50040101_164_dialog_content = "바이스... 설마 나만 놓고 도망가진 않을 거지?!",
  ui_story_5004_50040101_165_dialog_content = "우린 동료잖아. 절대 그런 짓은 안 해!",
  ui_story_5004_50040101_166_dialog_content = "어쨌든 여름은 시원한 바다를 즐기며 영혼을 치유할 수 있는 계절이니까.",
  ui_story_5004_50040101_167_dialog_content = "베릴도 분명히 마음 편히 쉴 수 있을 거야.",
  ui_story_5004_50040101_168_dialog_content = "바다라면... 수영복이 필요한 거지? 근데 우린 <color=#FFB400>수영복</color>이 없잖아.",
  ui_story_5004_50040101_169_dialog_content = "그건 걱정할 거 없어.",
  ui_story_5004_50040101_170_dialog_content = "내가 알기로는 그 호텔에서 유명 디자이너가 만든 수영복을 팔고 있거든.",
  ui_story_5004_50040101_171_dialog_content = "아무래도 주로 상대하는 고객이 백야성의 귀족들이니까.",
  ui_story_5004_50040101_172_dialog_content = "수영복도 판다니, 서비스가 꽤 철저하네.",
  ui_story_5004_50040101_173_dialog_content = "당연하지. 해변의 수영복은 전장의 갑옷이나 다름없어.",
  ui_story_5004_50040101_174_dialog_content = "일루미나의 병사든 백야성의 귀족이든, 해변에선 수영복을 입어야 해.",
  ui_story_5004_50040101_175_dialog_content = "그게 바로 「해변의 에티켓」이니까!",
  ui_story_5004_50040101_176_dialog_content = "그, 그렇구나...",
  ui_story_5004_50040101_177_dialog_content = "(왜 스카이워커가 가르쳐 준 거랑 얘기가 다르지...\n수영복이 그렇게 중요한 건가?)",
  ui_story_5004_50040101_178_dialog_content = "카렌은 왠지... 그 호텔과 수영복에 대해 잘 알고 있는 것 같네.",
  ui_story_5004_50040101_179_dialog_content = "그게 뭐 이상해? 난 백야성의 호위대장이야.",
  ui_story_5004_50040101_180_dialog_content = "귀족들 사이에서 유행하는 화제를 숙지하는 것도 내 직무의 일부야.",
  ui_story_5004_50040101_181_dialog_content = "아무튼, PlayerName, 너도 갑옷을 입고 전장에 나서는\n내 멋진 모습을 기대해도 좋아.",
  ui_story_5004_50040101_182_dialog_content = "(수영복을 입은 카렌이라...)",
  ui_story_5004_50040101_183_dialog_content = "음... 으음.",
  ui_story_5004_50040101_184_dialog_content = "왜 그런 눈으로 보는 거야? PlayerName.",
  ui_story_5004_50040101_185_dialog_content = "내 몸에 뭐 이상한 거라도 있어?",
  ui_story_5004_50040101_186_dialog_content = "아, 아니야! 맞다! 카렌, 그럼 그 호텔에 대해 또 아는 거 있어?",
  ui_story_5004_50040101_187_dialog_content = "그 호텔은 한때 어느 백야성 귀족의 소유였다고 들었어.",
  ui_story_5004_50040101_188_dialog_content = "그러다 경영 상태가 나빠져서 움브라톤의 한 클랜에 매각됐다고 해.",
  ui_story_5004_50040101_189_dialog_content = "하지만 움브라톤 같은 복잡하고 비밀스러운 곳은\n관련 정보의 진위를 판단하기가 어려워.",
  ui_story_5004_50040101_190_dialog_content = "게다가 의도적으로 자신을 숨기는 그런 클랜은 말할 필요도 없겠지.",
  ui_story_5004_50040101_191_dialog_content = "움브라톤의 현지 정보에 밝은 사람이 아니라면,\n외부인들은 자세한 내막을 알기 어려울 거야.",
  ui_story_5004_50040101_192_dialog_content = "그렇구나... 움브라톤은 정말 복잡한 곳이라니까.",
  ui_story_5004_50040101_193_dialog_content = "맞아. 지금의 움브라톤이 안정과 평화를 유지할 수 있는 건, 모두 그...",
  ui_story_5004_50040101_194_dialog_content = "잠깐만~! 지금 굳이 그런 심각한 얘기를 할 필요는 없잖아?",
  ui_story_5004_50040101_195_dialog_content = "우리 이번 목표는 베릴이 휴식을 취해서 건강을 회복하도록 돕는 거니까!",
  ui_story_5004_50040101_196_dialog_content = "난 괜찮아...",
  ui_story_5004_50040101_197_dialog_content = "!!!",
  ui_story_5004_50040101_198_dialog_content = "PlayerName?!",
  ui_story_5004_50040101_199_dialog_content = "스카이워커!",
  ui_story_5004_50040101_200_dialog_content = "PlayerName, 목적지 방향에서 순항 시스템에\n강력한 교란 전파를 보내는 중입니다.",
  ui_story_5004_50040101_201_dialog_content = "이대로 전진한다면 비행 상태가 안정을 잃게 될 수도 있습니다.",
  ui_story_5004_50040101_202_dialog_content = "꺄아악──!",
  ui_story_5004_50040101_203_dialog_content = "베릴? 베릴!",
  ui_story_5004_50040101_204_dialog_content = "괜찮아? 어디 불편한 데라도 있는 거야?",
  ui_story_5004_50040101_205_dialog_content = "스카이워커! 우선 목적지와 거리를 벌리고, 착륙할 위치를 찾아줘!",
  ui_story_5004_50040101_206_dialog_content = "알겠습니다.",
  ui_story_5004_50040101_207_dialog_content = "베릴, 괜찮아?",
  ui_story_5004_50040101_208_dialog_content = "...이건...",
  ui_story_5004_50040101_209_dialog_content = "여긴... 어디지?",
  ui_story_5004_50040101_210_dialog_content = "불의 열기... 타는 듯한 냄새... 그리고 수많은 오로리안의 울부짖는 소리...",
  ui_story_5004_50040101_211_dialog_content = "하지만 아무것도 안 보여...",
  ui_story_5004_50040101_212_dialog_content = "여긴 대체... 어디지?",
  ui_story_5004_50040101_213_dialog_content = "PlayerName!",
  ui_story_5004_50040101_214_dialog_content = "PlayerName──!",
  ui_story_5004_50040101_215_dialog_content = "바이스...?",
  ui_story_5004_50040101_216_dialog_content = "PlayerName, 괜찮아?",
  ui_story_5004_50040101_217_dialog_content = "방금 뭐가 어떻게 된 거야...?",
  ui_story_5004_50040101_218_dialog_content = "방금 네가 베릴을 부축하다가 갑자기 멍하니 멈춰서 있었어.",
  ui_story_5004_50040101_219_dialog_content = "또 뭔가 감응한 거야?",
  ui_story_5004_50040101_220_dialog_content = "응... 근데 너무 흐릿해서 제대로 보질 못했어...\n뭐, 됐어. 지금 상황은?",
  ui_story_5004_50040101_221_dialog_content = "이미 교란 범위를 벗어났습니다. 지금은 착륙 지점을 찾는 중입니다.",
  ui_story_5004_50040101_222_dialog_content = "베릴, 어디 안 다쳤지?",
  ui_story_5004_50040101_223_dialog_content = "응...",
  ui_story_5004_50040101_224_dialog_content = "방금 그건 대체 뭐였지...",
  ui_story_5004_50040201_1_dialog_content = "정말... 왜 꼭 내가 운전해서 너흴 데리고 가야 되는 건데?\n콜로서스를 내가 추락시킨 것도 아니잖아.",
  ui_story_5004_50040201_2_dialog_content = "마침 콜로서스의 바에서 한 곡 연주하려던 참이었는데 말이야.",
  ui_story_5004_50040201_3_dialog_content = "그러니까 정말 그 호텔에 초호화 음향 설비가 있다는 거지?",
  ui_story_5004_50040201_4_dialog_content = "감히 나한테 거짓말을 한 거라면...\n태양의 온도가 어떤 느낌인지 맛보게 해줄 줄 알아!",
  ui_story_5004_50040201_5_dialog_content = "으아악! 지붕 좀 두드리지 마! 그러다 차에서 떨어지겠다고!",
  ui_story_5004_50040201_6_dialog_content = "있을 거라니까! 아마도...?",
  ui_story_5004_50040201_7_dialog_content = "만약 없으면...",
  ui_story_5004_50040201_8_dialog_content = "저번에 네가 해달라던 「붐붐 슈퍼 봄버」 스피커 세트를 콜로서스에 달아줄게!",
  ui_story_5004_50040201_9_dialog_content = "아무튼 운전 좀 살살 해줘! 지붕에 있는 나도 좀 생각해 달라고! 부탁할게!",
  ui_story_5004_50040201_10_dialog_content = "정말 미안해, PlayerName... 괜히 나 때문에...",
  ui_story_5004_50040201_11_dialog_content = "괜찮아. 네 탓이 아냐.",
  ui_story_5004_50040201_12_dialog_content = "그렇다고 이런 「특등석」에 널 앉힐 순 없으니까...",
  ui_story_5004_50040201_13_dialog_content = "몰랐네. PlayerName, 너도 꽤나 신사다운 면이 있잖아?",
  ui_story_5004_50040201_14_dialog_content = "운전할 땐 앞을 봐! 갑자기 핸들에서 손 놓지 말고!",
  ui_story_5004_50040201_15_dialog_content = "겁먹지 말라고. 운전 같은 간단한 일은 레디젤 렌치 사람이라면\n태어날 때부터 할 줄 아는 거니까 말이야.",
  ui_story_5004_50040201_16_dialog_content = "고위 암귀가 나타나더라도 곧장 받아버릴 수 있다고.",
  ui_story_5004_50040201_17_dialog_content = "너흰 운이 좋은 거야. <color=#FFB400>렉커</color> 녀석 <color=#FFB400>차</color>가 마침 콜로서스에서\n수리 중이었으니 망정이지, 아니었으면 걸어서...",
  ui_story_5004_50040201_18_dialog_content = "앞에 조심해!",
  ui_story_5004_50040201_19_dialog_content = "암귀가 나타났어!",
  ui_story_5004_50040201_20_dialog_content = "뭐야?!",
  ui_story_5004_50040201_21_dialog_content = "아, 아파라... 젠장, 어디서 암귀가 나타난 거야...!\n이런 일은 내 운전 인생 이십여 년에...",
  ui_story_5004_50040201_22_dialog_content = "크아아──!",
  ui_story_5004_50040201_23_dialog_content = "으... 머리가 어지러워... 암귀가 차에 치여 날아간 거야?",
  ui_story_5004_50040201_24_dialog_content = "다들 괜찮아...?",
  ui_story_5004_50040201_25_dialog_content = "괜찮아. 경미한 부상일 뿐이야.",
  ui_story_5004_50040201_26_dialog_content = "키이익!",
  ui_story_5004_50040201_27_dialog_content = "...어째서 암귀가 이렇게 많은 거지? 다들 싸울 준비를 해줘!",
  ui_story_5004_50040201_28_dialog_content = "지금은 무기가 없어! 앉을 자리를 만든다고 무기는 전부 트렁크에 넣었단 말이야...!",
  ui_story_5004_50040201_29_dialog_content = "이대로 계속 꾸물대다간 암귀들한테 포위당할 거야!",
  ui_story_5004_50040201_30_dialog_content = "베릴, 베릴, 얼른 일어나 봐!",
  ui_story_5004_50040201_31_dialog_content = "으음...",
  ui_story_5004_50040201_32_dialog_content = "라파엘...?",
  ui_story_5004_50040201_33_dialog_content = "조심해──!",
  ui_story_5004_50040201_34_dialog_content = "...!",
  ui_story_5004_50040201_35_dialog_content = "피의 수정...!",
  ui_story_5004_50040201_36_dialog_content = "크에엑...",
  ui_story_5004_50040201_37_dialog_content = "크오! 크오오!",
  ui_story_5004_50040201_38_dialog_content = "놈들이 차를 뒤집으려고 해!",
  ui_story_5004_50040201_39_dialog_content = "피어나라!",
  ui_story_5004_50040201_40_dialog_content = "크아악...",
  ui_story_5004_50040201_41_dialog_content = "대단해! 순식간에 전부 해치워버렸잖아?!",
  ui_story_5004_50040201_42_dialog_content = "정말 몰랐네. 그렇게 강한 힘을 가지고 있을 줄은.\n아무래도 진리의 결사에 별 볼 일 없는 자들만 있는 건 아닌 모양이야.",
  ui_story_5004_50040201_43_dialog_content = "순식간에 이렇게 많은 수정을 만들어서 암귀들을 물리치는 힘이라면,\n백야성의 천사들이랑 막상막하일 것 같은데?",
  ui_story_5004_50040201_44_dialog_content = "확실히 그렇네.",
  ui_story_5004_50040201_45_dialog_content = "정말 대단해... 아, 고마워! 베릴!",
  ui_story_5004_50040201_46_dialog_content = "하아... 하아...",
  ui_story_5004_50040201_47_dialog_content = "베릴? ...괜찮아?",
  ui_story_5004_50040201_48_dialog_content = "어이, 꼬마 아가씨들, 수다 떨고 있을 때가 아냐.\n이 틈에 얼른 무기부터 챙겨. 암귀들이 더 몰려오고 있으니까!",
  ui_story_5004_50040301_1_dialog_content = "휴우... 어쨌든 거의 다 왔네. 이제 운전은 지긋지긋해졌어.",
  ui_story_5004_50040301_2_dialog_content = "무사히 목적지까지 데려다줘서 고마워...",
  ui_story_5004_50040301_3_dialog_content = "군소리는 됐고, 주차할 곳이나 찾아보자고.",
  ui_story_5004_50040301_4_dialog_content = "어이! 너희가 왜 여기 있어?",
  ui_story_5004_50040301_5_dialog_content = "내 차는 왜 여기 있는데? 뭐야, 범퍼는 또 어쩌다 찌그러진 거야?!",
  ui_story_5004_50040301_6_dialog_content = "PlayerName, 비록 우린 사나이끼리의 우정이 있지만,\n이번 일은 나한테 제대로 해명해 줘야겠어...",
  ui_story_5004_50040301_7_option_content = "사, 사실 레지나가\n드라이브 가고 싶다고 해서...",
  ui_story_5004_50040301_8_dialog_content = "됐거든. 진짜 드라이브를 가고 싶었어도\n레지나가 나서서 운전을 할 리가 없다고.",
  ui_story_5004_50040301_9_dialog_content = "대체 무슨 약점을 잡은 거야?",
  ui_story_5004_50040301_10_dialog_content = "날 뭐로 보는 거야? 내가 약점이 잡혀야지만 움직이는 줄 알아?",
  ui_story_5004_50040301_11_dialog_content = "PlayerName한테 스피커 세트를 받기로 한 거겠지?",
  ui_story_5004_50040301_12_dialog_content = "정확히 맞혀버렸잖아?!",
  ui_story_5004_50040301_13_dialog_content = "뭐야, 내가 바보인 줄 알았어?\n너희가 무슨 거래를 했는지는 척 봐도 알 수 있다고!",
  ui_story_5004_50040301_14_option_content = "차를 다 고쳐서 특별히 가지고 온 거야!",
  ui_story_5004_50040301_15_dialog_content = "뭐? 내가 여기 있다고 말한 적 있었나?",
  ui_story_5004_50040301_16_dialog_content = "당연히 감응 능력으로 알았지!",
  ui_story_5004_50040301_17_dialog_content = "이렇게 멀리서도 알 수 있다고?! 그건 좀 심하잖아!",
  ui_story_5004_50040301_18_dialog_content = "그나저나 차에 찍힌 모양이... 이거 암귀지?",
  ui_story_5004_50040301_19_dialog_content = "그런 것도 알 수 있단 말이야?!",
  ui_story_5004_50040301_20_dialog_content = "어이, 날 과소평가하지 말라고. 이래 봬도 일 년에 적어도\n암귀 수백 마리는 차로 치고 있으니까.",
  ui_story_5004_50040301_21_dialog_content = "이 형태는 이미 내 뇌리에 깊숙이 각인돼 있다고.\n「퓨리팽」이랑 부딪힌 거지?",
  ui_story_5004_50040301_22_dialog_content = "암귀의 종류까지 맞힐 수 있다고?!\n아, 아무튼 미안해. 나중에 다시 고쳐줄게!",
  ui_story_5004_50040301_23_dialog_content = "뭐, 너무 신경 쓸 필요는 없어.\n이번 건으로 내 차의 처치 신기록이 깨진 셈 치자고.",
  ui_story_5004_50040301_24_dialog_content = "나중에 내 <color=#FFB400>엔지니어 친구</color>한테 수리를 부탁하면 돼.",
  ui_story_5004_50040301_25_dialog_content = "그나저나, 다들 여긴 무슨 일이야? 휴가?",
  ui_story_5004_50040301_26_dialog_content = "응! 플라티나 선라이즈 호텔에서 PlayerName한테 초대장을 보냈어!\n숙박이 무료야!",
  ui_story_5004_50040301_27_dialog_content = "뭐? 그거 신기하네. 그 사장이 그렇게 통이 컸나?",
  ui_story_5004_50040301_28_dialog_content = "아마 아이테르인 PlayerName의 희소성을 이용해\n광고를 하려는 속셈이겠지.",
  ui_story_5004_50040301_29_dialog_content = "아하, 그거면 말이 되지...",
  ui_story_5004_50040301_X29_dialog_content = "...뭐야?! 왜 네가 여기 있어!",
  ui_story_5004_50040301_30_dialog_content = "넌... 그때 탈옥한 레디젤 렌치 강도...",
  ui_story_5004_50040301_31_dialog_content = "자, 잠깐만! 우린 이번엔 베릴을 데리고 여행을 온 거지,\n범인 체포하러 온 게 아니야!",
  ui_story_5004_50040301_32_dialog_content = "게다가 여긴 백야성도 아니니까, 굳이 여기서 싸울 필요는 없잖아!",
  ui_story_5004_50040301_33_dialog_content = "...그래.",
  ui_story_5004_50040301_34_dialog_content = "하지만 내가 여기 있는 동안 백야성에 해가 되는 짓을 한다면...",
  ui_story_5004_50040301_35_dialog_content = "반드시 널 잡아서 심판을 받게 하겠어.",
  ui_story_5004_50040301_36_dialog_content = "그건 그렇고, 렉커 넌 왜 여기 있는 건데?\n그리고 그 사장이란 사람에 대해 뭔가 아는 게 있어?",
  ui_story_5004_50040301_37_dialog_content = "그게 말이지... 난 내 친구를 도와주러 왔거든.\n아까 말한 그 엔지니어 친구 말이야.",
  ui_story_5004_50040301_38_dialog_content = "아, 뭐라고 해야 하나... 나도 내 차도 녀석의 도움을 많이 받았거든.\n은혜를 입었으면 갚는 게 레디젤 렌치의 미덕이니까!",
  ui_story_5004_50040301_39_dialog_content = "플라티나 선라이즈 호텔에 가면 바로 만날 수 있을 거야.",
  ui_story_5004_50040301_40_dialog_content = "가면 한눈에 알아볼 수 있어. 무척 눈에 띄거든. 여러 가지 의미로 말이지.",
  ui_story_5004_50040301_41_dialog_content = "아, 하나 더 물어볼 게 있어.",
  ui_story_5004_50040301_42_dialog_content = "스카이워커호가 이쪽으로 비행하던 중에 전파 교란을 당했어.\n혹시 뭔가 짐작 가는 거 있어?",
  ui_story_5004_50040301_43_dialog_content = "그건 잘 모르겠네. 난 콜로서스 운전은 해본 적 없으니까.",
  ui_story_5004_50040301_44_dialog_content = "콜로서스가 아무나 다 가지고 있는 건 줄 알아?",
  ui_story_5004_50040301_45_dialog_content = "근데 콜로서스라면 생물과 기계의 결합체잖아?",
  ui_story_5004_50040301_46_dialog_content = "그럼 스카이워커호가 감기에 걸린 걸 수도 있겠지.",
  ui_story_5004_50040301_47_dialog_content = "<size=30>PlayerName... 이 타이밍엔 농담에 웃어줘야 되는 거 아냐?</size>",
  ui_story_5004_50040301_48_dialog_content = "<size=30>안 돼... 농담인지 진담인지 모르겠단 말이야...</size>",
  ui_story_5004_50040301_49_dialog_content = "사람을 앞에 두고 속닥거리지 말라고.",
  ui_story_5004_50040301_50_dialog_content = "그럼 차는 내가 가져갈 테니까, 너흰 이 길로 쭉 가. 그럼 호텔이 나올 거야.",
  ui_story_5004_50040301_51_dialog_content = "(정말 예뻐... 푸른 파도가 황금빛 해변을 적시고 있어.)",
  ui_story_5004_50040301_52_dialog_content = "(저기 이름 모를 커다란 나무가 바닷바람에 흔들리는 것도 정말 보기 좋은걸.)",
  ui_story_5004_50040301_53_dialog_content = "(해변에는 사람들이 놀고 있네.)",
  ui_story_5004_50040301_54_dialog_content = "(따뜻한 햇살 아래 나른한 모습들... 모든 게 생기가 넘치는 느낌이야.)",
  ui_story_5004_50040301_55_dialog_content = "......",
  ui_story_5004_50040301_56_dialog_content = "여긴... 내가 상상했던 것보다 훨씬 더 멋진 것 같아.",
  ui_story_5004_50040301_57_dialog_content = "PlayerName! 여기가 바다인 거야...?",
  ui_story_5004_50040301_58_dialog_content = "이런 시기에도 이렇게 마음 편히 쉴 수 있는 곳이 있었다니, 정말 놀랐어.",
  ui_story_5004_50040301_59_dialog_content = "정말 예뻐...",
  ui_story_5004_50040301_60_dialog_content = "베릴, 저기 노점에 사람들이 잔뜩 있어! 우리도 얼른 가보자!",
  ui_story_5004_50040301_61_dialog_content = "후훗... 아무래도 여러분 모두 <color=#FFB400>헤븐즈 비치</color>가 무척 마음에 드신 모양이네요~",
  ui_story_5004_50040301_62_dialog_content = "?!",
  ui_story_5004_50040301_63_dialog_content = "놀라실 거 없어요. 전 이 호텔의 VIP 고객 담당 겸 이번 해신제의 진행을\n맡은 <color=#FFB400>보나시외</color>라고 해요.",
  ui_story_5004_50040301_64_dialog_content = "아, 보나시외 씨...",
  ui_story_5004_50040301_65_dialog_content = "어머, 베릴도 왔군요. 그 안경 쓴 성가신 남자는 같이 안 온 건가요?",
  ui_story_5004_50040301_66_dialog_content = "파우스트 씨 말인가요...\n아직 할 일이 있다면서 절 PlayerName한테 부탁하고 갔어요...",
  ui_story_5004_50040301_67_dialog_content = "그랬군요. 그럼 이쪽이 바로 그 PlayerName 씨겠네요.",
  ui_story_5004_50040301_68_dialog_content = "곁에 귀여운 여자애들이 이렇게나 많이 있다니, 정말 여복이 많으시네요~",
  ui_story_5004_50040301_69_dialog_content = "우린 동료일 뿐이야.",
  ui_story_5004_50040301_70_dialog_content = "동료 말인가요... 후훗...",
  ui_story_5004_50040301_71_dialog_content = "근데 자세히 보니, PlayerName 씨는 아이테르라고 했는데,\n머리에 뿔도 없고, 눈도 세 개가 아니네요.",
  ui_story_5004_50040301_72_option_content = "그것참 미안하게 됐어.",
  ui_story_5004_50040301_73_dialog_content = "으음? 역시 참 재미있는 분이시네요.",
  ui_story_5004_50040301_74_option_content = "아이테르와 오로리안은\n겉모습은 크게 다르지 않아.",
  ui_story_5004_50040301_75_dialog_content = "후훗, 진지한 모습이 정말 재미있네요~",
  ui_story_5004_50040301_76_dialog_content = "그냥 농담한 것뿐이에요. 너무 신경 쓰지 마세요.",
  ui_story_5004_50040301_77_dialog_content = "여러분은 호텔의 중요한 귀빈이자, 해신제의 시드 선수랍니다.",
  ui_story_5004_50040301_78_dialog_content = "그럼 저 보나시외가 여러분께 여름 해변의 정취를\n가득 느낄 수 있는 화려하면서도 친절한 서비스를...",
  ui_story_5004_50040301_79_dialog_content = "서비스는 괜찮아. 괜히 미안해지니까 우리가 알아서 할게!",
  ui_story_5004_50040301_80_dialog_content = "그것보다 물어보고 싶은 게 있는데, 그 해신제라는 게 정확히 뭐야?",
  ui_story_5004_50040301_81_dialog_content = "그건 말이죠~ 원래는 한때 이 해변에 살았던 오로리안들이\n남긴 제사 의식이었답니다.",
  ui_story_5004_50040301_82_dialog_content = "「바다는 만물의 근원. 바다는 넓은 마음으로 모든 것을 품고, 만물을 기르지요.」",
  ui_story_5004_50040301_83_dialog_content = "「바다를 지키는 여신은 이곳에 와서 도전에 임하는\n모든 영웅과 함께 춤을 춥니다.」",
  ui_story_5004_50040301_84_dialog_content = "이번 해신제에서 참가자들은 옛 전설 속의 시련을 본따서\n만든 경기에 참가하게 될 거예요.",
  ui_story_5004_50040301_85_dialog_content = "서로 <color=#FFB400>힘</color>과 <color=#FFB400>지혜</color>, 그리고 <color=#FFB400>용기</color>를 겨루어서 승리자를 뽑는 거죠.",
  ui_story_5004_50040301_86_dialog_content = "신은 승자에게 상을 내리고, 풍성한 수확을 거둘 수 있도록\n날씨를 축복할 거예요.",
  ui_story_5004_50040301_87_dialog_content = "그리고 승자는 <color=#FFB400>「해변의 용사」</color>라는 칭호를 얻을 수 있죠.",
  ui_story_5004_50040301_88_dialog_content = "게다가 각종 보상과 깜짝 특별상도 있답니다!",
  ui_story_5004_50040301_89_dialog_content = "여름 해변의 정취를 즐기면서, 소녀들과 다양한 경기에 참가할 수 있는 기회...",
  ui_story_5004_50040301_90_dialog_content = "그걸 설마 거절하진 않겠죠? PlayerName 씨.",
  ui_story_5004_50040301_91_dialog_content = "해변의... 용사...",
  ui_story_5004_50040301_92_dialog_content = "나 혼자서 결정할 순 없을 것 같아. 다 같이 논의해볼게.",
  ui_story_5004_50040301_93_dialog_content = "음~ 괜찮아요. 아무튼 우선 체크인부터 하실 수 있게\n호텔 로비로 안내해 드릴게요.",
  ui_story_5004_50040301_94_dialog_content = "축제는 모레부터 본격적으로 시작될 거예요.\n그럼 오늘이랑 내일은 편안한 휴식 시간을 즐겨 주세요.",
  ui_story_5004_50040301_95_dialog_content = "엄청 화려하네!",
  ui_story_5004_50040301_96_dialog_content = "그러게. 백야성이나 일루미나와는 확실히 다른 건축 양식이야.",
  ui_story_5004_50040301_97_dialog_content = "아마 어떤 옛 문명의 스타일이겠지?",
  ui_story_5004_50040301_98_dialog_content = "여기가 바로 호텔 로비예요~ 그럼 나머지는\n로비 매니저 <color=#FFB400>플뢰르</color> 씨가 안내해줄 거예요~",
  ui_story_5004_50040301_99_dialog_content = "응? 플뢰르 씨? 미안한데 좀 서둘러 주시겠어요~?",
  ui_story_5004_50040301_100_dialog_content = "전 다른 볼일이 있어서 먼저 가볼게요~ 나중에 다시 여러분을 보러 올게요.",
  ui_story_5004_50040301_101_dialog_content = "플뢰르?",
  ui_story_5004_50040301_102_dialog_content = "미, 미안해요!",
  ui_story_5004_50040301_103_dialog_content = "금방 갈게요...!",
  ui_story_5004_50040301_104_dialog_content = "플뢰르!",
  ui_story_5004_50040301_105_dialog_content = "플뢰르 씨~",
  ui_story_5004_50040301_106_dialog_content = "플뢰르 씨, 오늘 밤에 시간 있으세요?",
  ui_story_5004_50040301_107_dialog_content = "플뢰르~! 나랑 같이 헬스장에 가자고.\n내 완벽한 근육을 보여줄 테니까!",
  ui_story_5004_50040301_108_dialog_content = "이건 내가 방금 만든 디저트야. 얼른 먹어 봐. 아~",
  ui_story_5004_50040301_109_dialog_content = "이게... 무슨 상황이야? 이 괴상한 녀석들이랑... 저 플뢰르라는 사람...",
  ui_story_5004_50040301_110_dialog_content = "저 녀석... 몸에서 뭔가 기묘한 분위기가 느껴져.",
  ui_story_5004_50040301_111_dialog_content = "PlayerName, 아무래도 플뢰르가 너보다 더 인기가 많은 모양인데?",
  ui_story_5004_50040301_112_dialog_content = "그런 거로 놀리지 마.",
  ui_story_5004_50040301_113_dialog_content = "다들 정말 미안해. 난 플뢰르라고 해. 너희가 바로 그 콜로서스 팀이지?",
  ui_story_5004_50040301_114_dialog_content = "그리고 PlayerName, 아이테르라면서? 렉커한테 네 이야기 많이 들었어.",
  ui_story_5004_50040301_115_dialog_content = "렉커랑 아는 사이야?",
  ui_story_5004_50040301_116_dialog_content = "응, 사실 난 레디젤 렌치 소속 엔지니어거든.\n렉커하고는 꽤 오랫동안 알던 사이고.",
  ui_story_5004_50040301_117_dialog_content = "아, 그럼 네가 바로 렉커가 말한 엔지니어구나!\n(정말 여러 가지 의미로 눈에 띄네...)",
  ui_story_5004_50040301_118_dialog_content = "맞아. 이번에도 렉커의 부탁을 받고 온 거야.",
  ui_story_5004_50040301_119_dialog_content = "아! 생각났어! 어디서 들은 이름인가 했더니,\n일루미나 메카닉 아카데미의 전설적인 인물 플뢰르 씨였구나!",
  ui_story_5004_50040301_120_dialog_content = "일루미나의 선배들한테서 들은 적 있어.",
  ui_story_5004_50040301_121_dialog_content = "기계를 다루는 능력도 대단하고, 마음씨도 무척 좋은 사람이라고 들었어.\n<size=40>근데 뭔가</size> <size=35>이상하고 안 좋은</size> <size=30><color=#FFB400>소문들도 있다고 들었는데</color>...</size>",
  ui_story_5004_50040301_122_dialog_content = "맞아. 그러던 녀석이 어쩌다 레디젤 렌치에 오게 된 건지는 모르겠지만 말이야.",
  ui_story_5004_50040301_123_dialog_content = "게다가 사메야마 대장을 도와서 트래블러호를 수리해 주기도 해.\n실력은 확실한 녀석이라니까.",
  ui_story_5004_50040301_124_dialog_content = "어이, 너 바쁜 일이 있다고 대장한테 「여름 특별 휴가」 신청한 거 아니었어?",
  ui_story_5004_50040301_125_dialog_content = "근데 왜 여기 와서 무슨 로비 매니저를 하고 있어? ...\n그것도 그런 웃긴 옷차림을 하고서 말이야.",
  ui_story_5004_50040301_126_dialog_content = "백야성 귀족들처럼 우스꽝스러운 넥타이라도 하나 매야 하는 거 아냐?",
  ui_story_5004_50040301_127_dialog_content = "......",
  ui_story_5004_50040301_128_dialog_content = "(어이! 여기도 그 백야성 귀족이 있다고...!)",
  ui_story_5004_50040301_129_dialog_content = "난 보나시외 양의 초대를 받아서 온 거야. 그리고 다른 이유도 있고 말이야.",
  ui_story_5004_50040301_130_dialog_content = "뻔하지. 또 남한테 팔려서 재주도 부리고 돈까지 대신 벌어주고 있겠지.\n네 성격에 딱 맞는 일이잖아?",
  ui_story_5004_50040301_131_dialog_content = "가이드 겸 택시기사 일은 여기까지야. 난 음향 장비를 확인하러 바에 가야겠어.",
  ui_story_5004_50040301_132_dialog_content = "별일 없으면 이제 난 찾지 말아 달라고.",
  ui_story_5004_50040301_133_dialog_content = "조심히 가, 레지나.",
  ui_story_5004_50040301_134_dialog_content = "그럼 여러분, 이쪽이야. 체크인을 도와줄게.",
  ui_story_5004_50040301_135_dialog_content = "다들 방은 어떻게 할 생각이야?",
  ui_story_5004_50040301_136_dialog_content = "저기, 난...",
  ui_story_5004_50040301_137_dialog_content = "난 베릴이랑 한 방을 쓰고 싶어!",
  ui_story_5004_50040301_138_dialog_content = "난 베릴의 주치의니까, 한순간도 곁에서 떨어질 수 없다구!",
  ui_story_5004_50040301_139_dialog_content = "그래도 되지? 응? 괜찮지~?",
  ui_story_5004_50040301_140_dialog_content = "그...그래... 난... 괜찮아...",
  ui_story_5004_50040301_141_dialog_content = "나랑 바이스는 각자 하나씩 배정해 주면 돼.",
  ui_story_5004_50040301_142_option_content = "그럼 난...",
  ui_story_5004_50040301_143_dialog_content = "물론 너도 혼자 자야지. 10여 년 동안 스카이워커호에서\n혼자 잤으면서 밤이 무섭거나 한 건 아니겠지?",
  ui_story_5004_50040301_144_dialog_content = "다, 당연하지! 나도 혼자 자면 돼!",
  ui_story_5004_50040301_145_option_content = "그럼 레지나는?",
  ui_story_5004_50040301_146_dialog_content = "레지나라면 아마 며칠 동안은 그 스피커에 푹 빠져서\n정신을 못 차리지 않을까...",
  ui_story_5004_50040301_147_dialog_content = "아무튼 일단 대신 체크인을 해주자. 내가 나중에 키를 갖다주고 올게.",
  ui_story_5004_50040301_148_dialog_content = "그럼... 방은 총 다섯 개네.",
  ui_story_5004_50040301_149_dialog_content = "티, 팁 주세요...",
  ui_story_5004_50040301_150_dialog_content = "이분들은 호텔의 VIP 손님들이니까, 팁을 요구하면 안 돼요.",
  ui_story_5004_50040301_151_dialog_content = "아...알겠습니다.",
  ui_story_5004_50040301_152_dialog_content = "자, 여기 키 받아.",
  ui_story_5004_50040301_153_dialog_content = "방금 그 직원... 생김새가 뭔가 좀 이상한데...?",
  ui_story_5004_50040301_154_dialog_content = "하하, PlayerName, 그런 말을 하면 안 돼.",
  ui_story_5004_50040301_155_dialog_content = "뿔 같은 건 내 머리에도 있잖아.",
  ui_story_5004_50040301_156_dialog_content = "난 외모가 어떻든 모두가 사이좋게 지내야 한다고 생각해.",
  ui_story_5004_50040301_157_dialog_content = "(확실히 마음씨는 착한 사람이네...)",
  ui_story_5004_50040301_158_dialog_content = "음... 근데 솔직히 말하자면 저 직원들은 하는 짓이 확실히 좀 수상하긴 해.",
  ui_story_5004_50040301_159_dialog_content = "저 사람들은 원하는 급여도 낮고, 무급으로 야근까지 하겠다고 해서\n이곳 사장이 보자마자 마음에 들어 했거든.",
  ui_story_5004_50040301_160_dialog_content = "그래서 단번에 잔뜩 고용했지 뭐야.",
  ui_story_5004_50040301_161_dialog_content = "아까 렉커 말로는 이곳 사장도 좀 이상한 사람이라고 하던데?",
  ui_story_5004_50040301_162_dialog_content = "여기 사장은... 움브라톤의 어느 클랜 보스라고 들었어.",
  ui_story_5004_50040301_163_dialog_content = "경영 수완이 좋고, 돈을 무척 밝히는 사람이야.\n전부터 이 호텔을 운영하면서 나쁜 짓을 했다는 소문이 끊이질 않았어.",
  ui_story_5004_50040301_164_dialog_content = "나도 마음에 들진 않지만, 아직 보나시외 양과의 계약이 있어서\n당분간은 이곳 일을 도와줄 수밖에 없어.",
  ui_story_5004_50040301_165_dialog_content = "맞다. 그리고 다들 조심하는 게 좋아. 이 호텔과 해변에는\n불필요한 지출을 유도하는 함정이 많으니까.",
  ui_story_5004_50040301_166_dialog_content = "악덕 사장이라 이건가. 알겠어, 조심할게.",
  ui_story_5004_50040301_167_dialog_content = "그럼 방으로 안내해 줄게. 이쪽으로 와.",
  ui_story_5004_50040401_168_dialog_content = "자, PlayerName, 여기야.",
  ui_story_5004_50040401_169_dialog_content = "이게 내 방이야?",
  ui_story_5004_50040401_170_dialog_content = "마음에 들길 바랄게.",
  ui_story_5004_50040401_171_dialog_content = "참, 사실 콜로서스의 주인을 만나게 되면 기계공학에 대해서\n몇 가지 문제를 좀 같이 논의하고 싶었거든.",
  ui_story_5004_50040401_172_dialog_content = "일단 오늘은 피곤할 테니까, 다음에 기회가 되면 이야기해 보자.",
  ui_story_5004_50040401_173_dialog_content = "그럼 편히 쉬어. 궁금한 게 있으면 저쪽에 있는\n<color=#FFB400>통신기</color>로 언제든지 프런트에 문의하면 돼.",
  ui_story_5004_50040401_174_dialog_content = "알겠어, 고마워.",
  ui_story_5004_50040401_175_dialog_content = "......",
  ui_story_5004_50040401_176_dialog_content = "방은 깨끗하고 깔끔해. 침대도 무척 푹신할 것 같아.\n커튼을 열면 밤바다의 풍경이 바로 보여...",
  ui_story_5004_50040401_177_dialog_content = "여긴 질서정연한 일루미나나 우아하고 화려한 백야성과는 다르지만,\n어디에나 생기와 활력이 가득한 느낌이야.",
  ui_story_5004_50040401_178_dialog_content = "후아아...",
  ui_story_5004_50040401_179_dialog_content = "역시나 생각했던 것처럼 편안하네...",
  ui_story_5004_50040401_180_dialog_content = "갑자기 초대장을 받고 해변에 와서... 이렇게 푹신한 침대에 누워 있으니까...\n뭔가 실감이 안 나는 것 같네...",
  ui_story_5004_50040401_181_dialog_content = "그리고 그 해신제... 참가해야 하나 말아야 하나...\n아무리 생각해도 뭔가 좀 수상하단 말이지...",
  ui_story_5004_50040401_182_dialog_content = "그나저나 다들 뭘 하고 있으려나...",
  ui_story_5004_50040401_183_dialog_content = "<color=#e8d9bb>삐비비비──</color>",
  ui_story_5004_50040401_184_dialog_content = "까, 깜짝이야! 무슨 소리야? 아, 플뢰르가 아까 말한 통신기가 이건가?",
  ui_story_5004_50040401_185_dialog_content = "여보세요...?",
  ui_story_5004_50040401_186_dialog_content = "어이!",
  ui_story_5004_50040401_187_dialog_content = "전단지에 쓴 내용...\n「7일 안에 모든 잠재력을 발휘해 더 강한 자신을 만들 수 있습니다」... 그게 진짜야?!",
  ui_story_5004_50040401_188_dialog_content = "뭐야? 렉커잖아? 지금 무슨 소릴 하는 거야?",
  ui_story_5004_50040401_189_dialog_content = "...엥? PlayerName? 뭐야, 번호를 잘못 누른 모양이네.",
  ui_story_5004_50040401_190_dialog_content = "일단 바쁘니까 다음에 말해줄게!",
  ui_story_5004_50040401_191_dialog_content = "<color=#e8d9bb>뚜, 뚜, 뚜──</color>",
  ui_story_5004_50040401_192_dialog_content = "뭐야, 끊어버린 거야? 렉커 녀석 또 무슨 사기라도 당하는 건 아니겠지...",
  ui_story_5004_50040401_193_dialog_content = "이 통신기... 방 번호를 누르면 곧바로 연결되는 거겠지?",
  ui_story_5004_50040401_194_dialog_content = "어디 해볼까!",
  ui_story_5004_50040401_195_option_content = "(바이스에게 건다)",
  ui_story_5004_50040401_196_dialog_content = "앗...! PlayerName 너야?",
  ui_story_5004_50040401_197_dialog_content = "호텔에 이런 편리한 통신기가 있을 줄은 몰랐는걸.",
  ui_story_5004_50040401_198_dialog_content = "방해한 건 아니지? 그냥 쉬다 보니까 바이스는 뭘 하고 있을지 궁금했거든.",
  ui_story_5004_50040401_199_dialog_content = "아무것도 안 하고 그냥 침대에 누워 있어. 여기 침대가 정말 편한 것 같아.",
  ui_story_5004_50040401_200_dialog_content = "저기, 바이스. 해신제 말인데, 어떻게 생각해? 참가할 거야?",
  ui_story_5004_50040401_201_dialog_content = "물론이지! 너도 플뢰르가 말한 거 들었잖아?",
  ui_story_5004_50040401_202_dialog_content = "호텔 숙박은 무료지만, 식사나 수영복, 다른 활동은 전부 유료라고.",
  ui_story_5004_50040401_203_dialog_content = "그냥 돈만 쓰다 보면 우린 적자를 면할 수 없을 거야...",
  ui_story_5004_50040401_204_dialog_content = "그, 근데 난 운동 경기 같은 건 영 자신이 없는데...",
  ui_story_5004_50040401_205_dialog_content = "걱정하지 마. 나도 있고, 우리 모두 노력할 거니까.",
  ui_story_5004_50040401_206_dialog_content = "그리고 잊지 마, PlayerName.\n네 지휘 능력은 그 누구도 따라올 수 없는 강점이야!",
  ui_story_5004_50040401_207_dialog_content = "응... 듣고 보니 네 말도 맞는 것 같네...",
  ui_story_5004_50040401_208_dialog_content = "그럼 만약 상품이 나이티움이 아니면 어떡해?",
  ui_story_5004_50040401_209_dialog_content = "괜찮아. 뭘 받든 샤엘 씨한테 팔아달라 하면 되니까.",
  ui_story_5004_50040401_210_dialog_content = "PlayerName, 너무 걱정하지 말고 푹 쉬어.\n우린 반드시 해낼 수 있을 거야!",
  ui_story_5004_50040401_211_dialog_content = "바이스 네가 그렇게 말한다면야... 그럼 같이 힘내보자!",
  ui_story_5004_50040401_212_option_content = "(카렌에게 건다)",
  ui_story_5004_50040401_213_dialog_content = "PlayerName? 무슨 일이야?",
  ui_story_5004_50040401_214_dialog_content = "아, 혹시 내가 방해했어? 그냥 카렌이 뭐 하나 궁금해서.",
  ui_story_5004_50040401_215_dialog_content = "일일 계획에 맞춰서 이제 곧 자려던 참이었어.",
  ui_story_5004_50040401_216_dialog_content = "역시 카렌은 자기 자신한테도 무척 엄격하다니까.",
  ui_story_5004_50040401_217_dialog_content = "참, 해신제 말인데, 카렌 넌 어떻게 생각해?",
  ui_story_5004_50040401_218_dialog_content = "우린 반드시 승리할 거야.",
  ui_story_5004_50040401_219_dialog_content = "응? 그게 무슨 소리야? 우린 아직 참가하겠다고 결정도 안 했잖아.",
  ui_story_5004_50040401_220_dialog_content = "왜 안 하는데? 우린 이곳에 초대받았고,\n이건 운명이 우릴 위해 준비한 도전이야.",
  ui_story_5004_50040401_221_dialog_content = "진정한 전사는 그 어떤 도전도 두려워하지 않아.",
  ui_story_5004_50040401_222_dialog_content = "PlayerName, 네가 조금 혼란스럽거나 불안할 수도 있다는 건 알아.",
  ui_story_5004_50040401_223_dialog_content = "하지만 네게도 어려움을 이겨내고 나아갈 힘이 있어. 그걸 잊지 마.",
  ui_story_5004_50040401_224_dialog_content = "넌 모든 오로리안에게 특별한 존재야. 나한테도 마찬가지고.",
  ui_story_5004_50040401_225_dialog_content = "아... 지금 날 응원해 주는 거야?",
  ui_story_5004_50040401_226_dialog_content = "당연하지. 전투를 앞둔 병사라면 격려가 필요하니까.",
  ui_story_5004_50040401_227_dialog_content = "역시 백야성의 호위대장답네. 응, 덕분에 힘이 좀 나는 것 같아.",
  ui_story_5004_50040401_228_dialog_content = "그럼 잘 됐네. 이제 푹 쉬어.",
  ui_story_5004_50040401_229_dialog_content = "응, 그럼 해신제 참가를 결정했으니까, 잘 쉬어 둬야지!",
  ui_story_5004_50040401_230_dialog_content = "그나저나, 여긴 다 1인용 침대인가?",
  ui_story_5004_50040401_230X1_dialog_content = "<color=#e8d9bb>쿵──!</color>",
  ui_story_5004_50040401_230X2_dialog_content = "어이쿠!",
  ui_story_5004_50040401_230X3_dialog_content = "앗, 미안해! 괜찮아?",
  ui_story_5004_50040401_230X4_dialog_content = "근데 왜 접시를 들고 계속 문 앞에 서 있던 거야? 위험하잖아!",
  ui_story_5004_50040401_230X5_dialog_content = "후우... 라파엘... 너무 빨라...",
  ui_story_5004_50040401_230X6_dialog_content = "이, 이 방의 손님께서 간식이 필요하다고 하셔서... 가지고 왔습니다.",
  ui_story_5004_50040401_230X7_dialog_content = "다른 일이 없으시다면 그만 가보겠습니다. 주방 일이 아직 바빠서...",
  ui_story_5004_50040401_230X8_dialog_content = "밖이 왜 이리 시끄러운 거야...",
  ui_story_5004_50040401_230X9_dialog_content = "<color=#e8d9bb>똑똑똑.</color>",
  ui_story_5004_50040401_231_dialog_content = "그럼 베릴이랑 라파엘은...",
  ui_story_5004_50040401_232_dialog_content = "PlayerName~ 놀러 와 봤어.\n어떻게 우리 몰래 간식을 먹을 수가 있어?",
  ui_story_5004_50040401_233_dialog_content = "응? 라파엘, 간식 같은 건 없었는데...",
  ui_story_5004_50040401_234_dialog_content = "아, 안녕...",
  ui_story_5004_50040401_235_dialog_content = "베릴도 왔구나.",
  ui_story_5004_50040401_236_dialog_content = "베릴, PlayerName한테 할 말 있다면서~? 얼른 말해~",
  ui_story_5004_50040401_237_dialog_content = "아... 그게... 아무래도 너무 제멋대로인 것 같아서...",
  ui_story_5004_50040401_238_dialog_content = "응? 말하기 부끄러운 거야? 그럼 라파엘이 베릴 대신 말해줄까?",
  ui_story_5004_50040401_239_dialog_content = "응...",
  ui_story_5004_50040401_240_dialog_content = "알겠어~ 흠흠~",
  ui_story_5004_50040401_241_dialog_content = "사실 베릴은 해신제에 무척 참가하고 싶대.",
  ui_story_5004_50040401_242_dialog_content = "그렇구나.",
  ui_story_5004_50040401_243_dialog_content = "근데 문제는 해신제에 참가할 수가 없어.",
  ui_story_5004_50040401_244_dialog_content = "...응?",
  ui_story_5004_50040401_245_dialog_content = "에이, PlayerName, 넌 이해력을 좀 더 기를 필요가 있어!",
  ui_story_5004_50040401_246_dialog_content = "저기... 라파엘, PlayerName 잘못이 아니잖아...\n그러니까 탓하지 말아줘... 이건 내 문제니까...",
  ui_story_5004_50040401_247_dialog_content = "PlayerName, 보나시외가 말한 보상 기억해?",
  ui_story_5004_50040401_248_dialog_content = "아, 그럼 혹시 베릴 너도 돈이 필요한 거야? 사실 나도...",
  ui_story_5004_50040401_249_dialog_content = "아니거든──! 「해변의 용사」 칭호를 말하는 거라구!",
  ui_story_5004_50040401_250_dialog_content = "......",
  ui_story_5004_50040401_251_dialog_content = "뭐야, 그 표정은? 소녀의 천진난만하고\n순수한 동심에 무슨 불만이라도 있어?!",
  ui_story_5004_50040401_252_dialog_content = "내가 그럴 리가 없잖아! 그냥 혼자 생각 좀 해봤을 뿐이라고!",
  ui_story_5004_50040401_253_dialog_content = "베릴... 진심이야?",
  ui_story_5004_50040401_254_dialog_content = "응...!",
  ui_story_5004_50040401_255_dialog_content = "참가하는 건 괜찮아... 다들 마침 그럴 생각이었거든.",
  ui_story_5004_50040401_256_dialog_content = "저, 정말?!",
  ui_story_5004_50040401_257_dialog_content = "다행이야...",
  ui_story_5004_50040401_258_dialog_content = "근데 참가할 수 없다는 건 또 무슨 뜻인데?",
  ui_story_5004_50040401_259_dialog_content = "베릴은 말이지...",
  ui_story_5004_50040401_260_dialog_content = "라파엘... 내가 직접 얘기할게. 고마워...",
  ui_story_5004_50040401_261_dialog_content = "후우우...",
  ui_story_5004_50040401_262_dialog_content = "오늘 너도 내 능력을 봤을 거야...",
  ui_story_5004_50040401_263_dialog_content = "응, 무척 강한 힘이었어.",
  ui_story_5004_50040401_264_dialog_content = "하지만 그 힘은 통제를 벗어나기 쉬워서 무척 위험해...",
  ui_story_5004_50040401_265_dialog_content = "내가 방출하는 힘이 강할수록, 내 감정과 몸에 미치는 영향도\n점점 더 커져버려...",
  ui_story_5004_50040401_266_dialog_content = "오늘 내가 너흴 도우면서 암귀를 너무 많이 상대해서...\n며칠 동안은 격렬하게 움직이긴 힘들 것 같아...",
  ui_story_5004_50040401_267_dialog_content = "그런 거구나. 알겠어. 네가 모두를 도와줬으니까,\n다른 사람들도 분명히 널 도와줄 거라 생각해!",
  ui_story_5004_50040401_268_dialog_content = "나도 다른 사람들한테 말해둘게.\n베릴이 교체 선수로 게임에 참가할 수 있도록 말이야.",
  ui_story_5004_50040401_269_dialog_content = "정말 출전할지 말지는 네가 컨디션을 보고 결정하면 돼.",
  ui_story_5004_50040401_270_dialog_content = "그럼 되지?",
  ui_story_5004_50040401_271_dialog_content = "응!",
  ui_story_5004_50040401_272_dialog_content = "그리고 하나 물어보고 싶은 게 있어. 방금 네가 힘이 강해지면 감정과 몸이\n영향을 받는다고 했잖아. 그게 구체적으로 어떤 영향인데?",
  ui_story_5004_50040401_273_dialog_content = "...무척 슬프고 절망적인 기분이 들게 돼.\n그리고 힘이 더욱 강해져서...통제할 수 없게 돼버려.",
  ui_story_5004_50040401_274_dialog_content = "그거 왠지 악순환 같은데...",
  ui_story_5004_50040401_275_dialog_content = "맞아...",
  ui_story_5004_50040401_276_dialog_content = "그럼... 언젠가는 베릴도 슬픔과 절망에서 벗어나서,\n자신의 힘을 다룰 용기를 낼 수 있을 거라 생각해.",
  ui_story_5004_50040401_277_dialog_content = "그때가 되면 네 힘이 어떻게 변할지도 기대되는걸.",
  ui_story_5004_50040501_1_dialog_content = "......",
  ui_story_5004_50040501_2_dialog_content = "......",
  ui_story_5004_50040501_3_dialog_content = "...역시 콜로서스 밖에서 자는 건 아직 익숙하지가 않네.",
  ui_story_5004_50040501_4_option_content = "(일어날 준비를 한다)",
  ui_story_5004_50040501_5_dialog_content = "<color=#e8d9bb>똑똑똑.</color>",
  ui_story_5004_50040501_6_dialog_content = "PlayerName, 일어났어?",
  ui_story_5004_50040501_7_option_content = "(침대에서 일어난다)",
  ui_story_5004_50040501_8_dialog_content = "잠깐만... 문 열어줄게.",
  ui_story_5004_50040501_9_dialog_content = "<color=#e8d9bb>딸깍.</color>",
  ui_story_5004_50040501_10_dialog_content = "좋은 아침~ PlayerName, 얼른 준비해.",
  ui_story_5004_50040501_11_dialog_content = "카렌이랑 다들 식당에서 기다리고 있어.",
  ui_story_5004_50040501_12_dialog_content = "안녕, PlayerName. 왠지 좀 피곤해 보이네.",
  ui_story_5004_50040501_13_dialog_content = "응, 아직 콜로서스 말고 다른 곳에서 자는 게 익숙하지가 않아서...",
  ui_story_5004_50040501_14_dialog_content = "뭐, 그래도 괜찮아. 이런 특별한 체험을 할 수 있는 것도 무척 기쁘니까.",
  ui_story_5004_50040501_15_dialog_content = "바이스랑 카렌을 만난 뒤로, 난 전에는 생각지도 못했던\n일들을 많이 경험할 수 있었어.",
  ui_story_5004_50040501_16_dialog_content = "뭐야, 갑자기 그렇게 진지한 말을 하고. 성숙해진 느낌인데?",
  ui_story_5004_50040501_17_dialog_content = "설마 여기 바닷바람에 뭔가 「마력」이 있는 걸까?",
  ui_story_5004_50040501_18_dialog_content = "아하하... 그냥 잠을 제대로 못 자서 그런 걸지도 몰라.",
  ui_story_5004_50040501_19_dialog_content = "라파엘이랑 베릴은 어땠어?",
  ui_story_5004_50040501_20_option_content = "잘 잤어?",
  ui_story_5004_50040501_21_dialog_content = "응... 침대가 좀 좁긴 했지만...",
  ui_story_5004_50040501_22_dialog_content = "(역시나 1인용 침대였구나.)",
  ui_story_5004_50040501_23_dialog_content = "PlayerName, 그거 알아? 베릴은 잘 때 뭘 안고 자는 걸\n좋아하는 타입이야~",
  ui_story_5004_50040501_24_dialog_content = "베, 베개를 안고 자는 게 이상한 건 아니잖아...!",
  ui_story_5004_50040501_25_option_content = "혹시 2인용 침대였어?",
  ui_story_5004_50040501_26_dialog_content = "아니, 그래서 좀... 좁았어...",
  ui_story_5004_50040501_27_dialog_content = "1인용 침대에 베릴이랑 라파엘, 그리고 커~다란 베개까지 있었거든.",
  ui_story_5004_50040501_28_dialog_content = "응, 내 베개...",
  ui_story_5004_50040501_29_dialog_content = "베릴이 잘 때 뭔가 안고 자는 타입인 줄은 몰랐어.",
  ui_story_5004_50040501_30_dialog_content = "베개를 안고 자는 게 이상한 건 아니잖아...!",
  ui_story_5004_50040501_31_dialog_content = "맞아. 절반 정도는 베개를 안고 잔 건 맞긴 한데, 그러다...",
  ui_story_5004_50040501_32_dialog_content = "마, 말하면 안 돼──!",
  ui_story_5004_50040501_33_dialog_content = "좋은 아침, 다들 잘 쉬었어?",
  ui_story_5004_50040501_34_dialog_content = "응, 안녕, 플뢰르.",
  ui_story_5004_50040501_35_dialog_content = "잘 쉬었어. 객실도 깔끔하고 침대도 편했어.",
  ui_story_5004_50040501_36_dialog_content = "아직 적응이 조금 덜 된 것 같아서 그렇지...",
  ui_story_5004_50040501_37_dialog_content = "하하, 다른 손님들도 많이들 그래. 지금 같은 시대엔\n이렇게 멀리 여행을 오는 일 자체가 흔치 않은 일이잖아.",
  ui_story_5004_50040501_38_dialog_content = "바깥은 사방에 암귀가 돌아다니니까, 평소에 살고 있는 지역만\n안전하게 느껴질 수밖에 없어.",
  ui_story_5004_50040501_39_dialog_content = "그것도 그렇네. 참, 어제 카렌한테 들었는데, 호텔에 <color=#FFB400>수영복 가게</color>가 있다면서?",
  ui_story_5004_50040501_40_dialog_content = "어디 있는지 좀 알 수 있을까?",
  ui_story_5004_50040501_41_dialog_content = "응, <color=#FFB400>레스토랑에서 북동쪽으로 가면 돼</color>.",
  ui_story_5004_50040501_42_dialog_content = "오케이, 그럼 밥 먹고 출발해 볼까──!",
  ui_story_5004_50040501_43_dialog_content = "좋아──!",
  ui_story_5004_50040601_44_dialog_content = "여자애들은 옷 고르는데 원래 이렇게 오래 걸리는 거야?",
  ui_story_5004_50040601_45_dialog_content = "<color=#FFB400>모래사장</color>에서 기다리고 있으라더니, 벌써 한 시간은 더 지난 것 같잖아...",
  ui_story_5004_50040601_46_dialog_content = "햇살이 좀 세긴 한데, 그래도 이렇게 여유롭게\n일광욕을 즐기는 것도 나쁘진 않네...",
  ui_story_5004_50040601_47_dialog_content = "바이스, 카렌... 그리고 일행들... 모두 오랜 친구들처럼...\n이렇게 암귀의 습격이나 음모 같은 걱정 없이...",
  ui_story_5004_50040601_48_dialog_content = "함께 평화롭게 햇살과 바닷바람을 즐길 수 있다니...\n정말 편안한 기분이야...",
  ui_story_5004_50040601_49_dialog_content = "......",
  ui_story_5004_50040601_50_dialog_content = "모래가 참 따뜻하네. 뭔가 좀 그려볼까?",
  ui_story_5004_50040601_51_dialog_content = "PlayerName, 뭘 그린 거야? 문어?",
  ui_story_5004_50040601_52_dialog_content = "아, 아냐! 이건 고양이라고...",
  ui_story_5004_50040601_53_dialog_content = "아, 그럼 이 구부러진 촉수 같은 게 수염을 그린 거였어?!",
  ui_story_5004_50040601_54_dialog_content = "그럼 내가 수염을 더 예쁘게 만들어줄게.",
  ui_story_5004_50040601_55_dialog_content = "아앗! 발로 그리면 안 돼! 팔보다 두꺼운 수염이 어디 있어!\n바이스! 너 진짜──",
  ui_story_5004_50040601_56_dialog_content = "......",
  ui_story_5004_50040601_57_dialog_content = "응?",
  ui_story_5004_50040601_58_dialog_content = "...그, 그런대로 괜찮네.",
  ui_story_5004_50040601_59_dialog_content = "뭐가 괜찮은데?",
  ui_story_5004_50040601_60_dialog_content = "PlayerName, 너 좀 이상해.",
  ui_story_5004_50040601_61_dialog_content = "뭐, 됐어~ 즐길 수 있을 때 즐기는 게 중요하니까.",
  ui_story_5004_50040601_62_dialog_content = "역시 바다엔 수영복이라니까. 그래야 제대로 된 여름 휴가 아니겠어?",
  ui_story_5004_50040601_63_dialog_content = "하지만 네 수영복은 내가 보기엔 「해변의 갑옷」이라고 부를 수 없어!",
  ui_story_5004_50040601_64_dialog_content = "PlayerName! 잘 봐, 거대한 파도를 두려워하지 않는 기사가\n뭔지 가르쳐줄 테니까!",
  ui_story_5004_50040601_65_dialog_content = "(각자 이유는 다르지만, 카렌도 무척 신이 난 것 같네...)",
  ui_story_5004_50040601_66_dialog_content = "(게다가 나한테 수영복 차림을 봐달라고 하다니... 너무 들뜬 거 아냐?)",
  ui_story_5004_50040601_67_dialog_content = "PlayerName, 어때?",
  ui_story_5004_50040601_68_dialog_content = "뭐, 뭐가 어떤데?",
  ui_story_5004_50040601_69_dialog_content = "당연히 수영복 얘기지. 어느 쪽이 이 해변을\n정복할 수 있는 진정한 용사 같은데?",
  ui_story_5004_50040601_70_option_content = "바이스의 수영복은...\n무척 활기차고 귀여워 보여.",
  ui_story_5004_50040601_72_dialog_content = "PlayerName 넌 저런 스타일을 좋아했던 거구나?",
  ui_story_5004_50040601_73_dialog_content = "뭐, 확실히 바이스는 아카데미 때도 넘치는 활력으로 유명했으니까.",
  ui_story_5004_50040601_74_dialog_content = "체력 훈련 목표량을 두 배로 늘린다든지,\n밤을 새워서 수업을 복습한다든지 말이야.",
  ui_story_5004_50040601_75_dialog_content = "당연하지. 에너지나 노력이라면 누구한테도 지지 않아!",
  ui_story_5004_50040601_76_option_content = "카렌의 수영복은...\n기품 있고 우아해 보여.",
  ui_story_5004_50040601_78_dialog_content = "나도 그렇게 생각해!",
  ui_story_5004_50040601_79_dialog_content = "카렌처럼 엄격한 예법 훈련을 받은 사람이 아니라면,\n이렇게 기품 있고 우아한 분위기가 느껴지지 않았을 거야.",
  ui_story_5004_50040601_80_dialog_content = "일루미나에선 엄격한 군인이 되도록 가르치니까,\n백야성과는 다를 수밖에 없어.",
  ui_story_5004_50040601_81_dialog_content = "바이스는 일루미나의 군인이지만, 같이 공부할 때\n자연과학 성적은 내 뒤를 바짝 쫓아올 정도였어.",
  ui_story_5004_50040601_82_dialog_content = "헤헷, 그쪽은 내가 자신 있는 분야거든.",
  ui_story_5004_50040601_83_dialog_content = "하지만 예술 쪽 과목은 전혀 소질이 없었지.",
  ui_story_5004_50040601_84_dialog_content = "그건... 백야성에 기계 제도 같은 예술 과목이 없어서 그런 거잖아.",
  ui_story_5004_50040601_85_dialog_content = "그런 것도 예술 과목이야?! 그런 과목은 일루미나 말고는\n어디에서도 안 만들 거라고!",
  ui_story_5004_50040601_86_dialog_content = "하, 하지만 난 음악에 재능이 있을지도 모른다구!\n나랑 PlayerName 둘이서 콜로서스를 가동했잖아!",
  ui_story_5004_50040601_87_dialog_content = "그래그래. 그럼 나도 그렇고 스카이워커 몫까지 우리 바이스 중위님한테\n다시 한번 감사 인사를 해야겠는걸?",
  ui_story_5004_50040601_88_dialog_content = "정말 고마워. 바이스 덕분에 모두가 지금 이런 시간을 보낼 수 있는 거니까.",
  ui_story_5004_50040601_89_dialog_content = "다들 오래 기다렸어~",
  ui_story_5004_50040601_90_dialog_content = "라파엘? 수영복은?",
  ui_story_5004_50040601_91_dialog_content = "라파엘은 임무 수행 중인 의사라구. 보살핌이 필요한 사람을 놔두고\n어떻게 수영복이나 입고 멋대로 놀 수 있겠어?",
  ui_story_5004_50040601_92_dialog_content = "그렇구나. 그럼 베릴은?",
  ui_story_5004_50040601_93_dialog_content = "저기, 베릴?",
  ui_story_5004_50040601_94_dialog_content = "베릴~ 얼른 이리 와.",
  ui_story_5004_50040601_95_dialog_content = "아...안 되겠어. 너무 부끄러워...",
  ui_story_5004_50040601_96_dialog_content = "난 이렇게... 피부가 많이 드러나는 옷은... 처음 입어봐서...",
  ui_story_5004_50040601_97_dialog_content = "부끄러워할 거 없어! 엄청 귀엽다니까!",
  ui_story_5004_50040601_98_dialog_content = "안 그래? PlayerName!",
  ui_story_5004_50040601_99_dialog_content = "응, 분위기가 완전히 달라진 것 같아. 베릴한테 아주 잘 어울려.",
  ui_story_5004_50040601_100_dialog_content = "맞아. 해변의 기사로서 충분한 자격이 있다는 걸 부정할 수 없겠어.",
  ui_story_5004_50040601_101_dialog_content = "디자인도 체형에 잘 맞고, 움직이기도 무척 편리해 보여.",
  ui_story_5004_50040601_102_dialog_content = "나도 같은 생각이야. 베릴이 평소에 입는 옷보다 훨씬 귀여운 것 같아.",
  ui_story_5004_50040601_103_dialog_content = "귀여운 수영복도 입었겠다, 우리랑 같이 수영하러 가자.",
  ui_story_5004_50040601_104_dialog_content = "봐~ 다들 베릴이 귀엽다고 생각하잖아.",
  ui_story_5004_50040601_105_dialog_content = "그리고 다들 똑같이 수영복을 입고 있는걸~",
  ui_story_5004_50040601_106_dialog_content = "그, 그래도...",
  ui_story_5004_50040601_107_dialog_content = "...알겠어.",
  ui_story_5004_50040601_108_dialog_content = "좋아, 베릴~ 너무 신경 쓰지 마!",
  ui_story_5004_50040601_108X1_dialog_content = "<color=#e8d9bb>찰칵.</color>",
  ui_story_5004_50040601_108X2_dialog_content = "<color=#e8d9bb>찰칵, 찰칵.</color>",
  ui_story_5004_50040601_108X3_dialog_content = "응? 어제 그 직원이잖아?",
  ui_story_5004_50040601_108X4_dialog_content = "저건 카메라야~ 백야성에서 비슷한 걸 본 적 있어!",
  ui_story_5004_50040601_108X5_dialog_content = "좀 이상한데... 왜 저기 엎드려서 사진을 찍는 거지?",
  ui_story_5004_50040601_108X6_dialog_content = "풍경 사진 같은 걸 찍어서 홍보에 쓰려는 건가?\n그럼 우리도 한 장 찍게 내가 카메라를 빌려올게!",
  ui_story_5004_50040601_108X7_dialog_content = "이, 이 수영복 사진들... 이거면... 업무 실적으로...",
  ui_story_5004_50040601_108X8_dialog_content = "저기 있잖아~",
  ui_story_5004_50040601_108X9_dialog_content = "으우으아악!",
  ui_story_5004_50040601_108X10_dialog_content = "엥? 아직 말도 안 꺼냈는데 카메라부터 던져주는 거야?",
  ui_story_5004_50040601_108X11_dialog_content = "빌려주겠다는 거지? 그럼 사양하지 않을게!",
  ui_story_5004_50040601_108X12_dialog_content = "까, 깜짝 놀랐잖아요...",
  ui_story_5004_50040601_108X13_dialog_content = "저기... 도, 돌려주세요...",
  ui_story_5004_50040601_108X14_dialog_content = "라파엘... 왠지 곤란해하는 것 같은데 그냥 돌려주는 게 어떨까...?",
  ui_story_5004_50040601_108X15_dialog_content = "베릴은 역시 상냥하다니까~ 자, 그럼 잘 받아.",
  ui_story_5004_50040601_108X16_dialog_content = "고, 고마워요...",
  ui_story_5004_50040601_109_dialog_content = "좋아~ 그럼 우린 놀러 가자, 베릴~",
  ui_story_5004_50040601_110_dialog_content = "우리도 가자, PlayerName.",
  ui_story_5004_50040601_111_dialog_content = "응!",
  ui_story_5004_50040701_1_dialog_content = "정말 다들 기운도 넘치네...",
  ui_story_5004_50040701_2_dialog_content = "(바이스는 꼭 프로펠러를 단 것처럼 물보라를 일으키며\n튜브에 의지해 수면을 가르고 있어.)",
  ui_story_5004_50040701_3_dialog_content = "(카렌은 계속 창을 가지고 처음 보는 모습의 수중 생물들을 자극하고 있고.)",
  ui_story_5004_50040701_4_dialog_content = "(심지어는 자기 몸보다 더 큰 생물을 물가로 던지고 있네...)",
  ui_story_5004_50040701_5_dialog_content = "(베릴과 라파엘도 즐겁게 조개껍데기를 줍고 모래성을 만들고 있어.)",
  ui_story_5004_50040701_6_dialog_content = "(그나저나 베릴이 쌓은 모래성... 뭐랄까, 엄청 대단하네...)",
  ui_story_5004_50040701_7_dialog_content = "(송곳니 같은 가시가 가득하고, 거대한 시계탑도 있어.)",
  ui_story_5004_50040701_X7_dialog_content = "(마치 무슨 악의 세력이 숨어있는 성 같은 느낌인데...)",
  ui_story_5004_50040701_8_dialog_content = "그나저나... 내 체력이 정말로 약해진 건가?",
  ui_story_5004_50040701_9_dialog_content = "하긴, 콜로서스 안에서는 몸을 쓸 일이 거의 없기도 하고...",
  ui_story_5004_50040701_10_dialog_content = "전투 중에는 지휘만 하는 입장이니까...",
  ui_story_5004_50040701_11_dialog_content = "이참에 해변에서 달리기라도 좀 해야겠어.",
  ui_story_5004_50040701_12_dialog_content = "어이~ 위대한 콜로서스의 주인, 일루미나의 차기 장군, 백야성의 수호자...",
  ui_story_5004_50040701_13_dialog_content = "그리고 레디젤 렌치의 차기 대장이 될 바로 나!\n렉커의 친구, PlayerName잖아?",
  ui_story_5004_50040701_14_dialog_content = "렉커? 여기서 뭐 해?",
  ui_story_5004_50040701_15_dialog_content = "플뢰르 도와주러 간 거 아니었어?",
  ui_story_5004_50040701_16_dialog_content = "말이 나온 김에 하는 얘긴데, 네가 사메야마를 이기고\n레디젤 렌치의 새로운 대장이 되는 모습은 잘 상상이 안 된다고.",
  ui_story_5004_50040701_17_dialog_content = "PlayerName, 네가 지휘 능력은 좀 있긴 해도,\n사람을 알아보는 능력은 역시 부족한 모양이네.",
  ui_story_5004_50040701_18_dialog_content = "사메야마 녀석은 이미 내리막길이라고.\n그리고 난 이제 한창 솟아오르는 라이징 스타!",
  ui_story_5004_50040701_X18_dialog_content = "패\n배",
  ui_story_5004_50040701_19_dialog_content = "지금 레디젤 렌치엔 이미 많은 사람들이 날 지지하고 있다고.",
  ui_story_5004_50040701_20_dialog_content = "많은 사람... 누구?",
  ui_story_5004_50040701_21_dialog_content = "...플뢰르.",
  ui_story_5004_50040701_22_dialog_content = "......",
  ui_story_5004_50040701_23_dialog_content = "...그리고?",
  ui_story_5004_50040701_24_dialog_content = "플뢰르, 플뢰르, 그리고 플뢰르...\n아, 이참에 레지나한테도 다시 얘기해 봐야겠어!",
  ui_story_5004_50040701_25_dialog_content = "레지나라면 아마 너랑 이 얘길 할 생각은 없을걸.",
  ui_story_5004_50040701_26_dialog_content = "그럼 너랑 얘기하지 뭐.",
  ui_story_5004_50040701_27_dialog_content = "그리고 네가 아이테르의 지지를 받고 있다고 떠들 생각이지?",
  ui_story_5004_50040701_28_dialog_content = "휴, PlayerName, 역시 넌 내가 아는 아이테르 중에서\n가장 똑똑한 녀석이라니까!",
  ui_story_5004_50040701_29_dialog_content = "뭔데 그 되도 않는 칭찬은! 그리고 나 말고 아는 아이테르도 없으면서!",
  ui_story_5004_50040701_30_dialog_content = "...쉿.",
  ui_story_5004_50040701_31_dialog_content = "...?",
  ui_story_5004_50040701_32_dialog_content = "PlayerName, 저기 <color=#FFB400>저 사람</color> 좀 봐.",
  ui_story_5004_50040701_33_dialog_content = "저 여자애?",
  ui_story_5004_50040701_34_dialog_content = "그래. 뭔가 수상해 보인단 말이지... 마치 주변에서 뭔가를 찾는 것 같잖아.",
  ui_story_5004_50040701_35_dialog_content = "별로 그래 보이진 않는데... 그냥 뭘 잃어버렸거나 그런 거겠지.",
  ui_story_5004_50040701_36_dialog_content = "넌 뭘 잃어버렸을 때 사람보다 큰 바위를 들추면서 찾냐?",
  ui_story_5004_50040701_37_dialog_content = "가자. 뭘 하는 건지 한번 보자고.",
  ui_story_5004_50040701_38_option_content = "그래.",
  ui_story_5004_50040701_39_dialog_content = "근데 왜 그렇게 신경을 쓰는 거야?",
  ui_story_5004_50040701_40_dialog_content = "만약에 도둑이라면?",
  ui_story_5004_50040701_41_dialog_content = "저런 커다란 바위를 들춰서 뭘 훔치는데?! 그 밑에 누가 물건을 숨겼겠냐고!",
  ui_story_5004_50040701_42_dialog_content = "너희 레디젤 렌치가 언제부터 그런 정의감이 있었는데?",
  ui_story_5004_50040701_43_dialog_content = "지금은 달라. 난 플뢰르의 의뢰를 받은 몸이야!\n지금 난무려 <color=#FFB400>헤븐즈 비치의 보안 요원</color>이라고!",
  ui_story_5004_50040701_44_dialog_content = "...(대체 어떤 인간이 레디젤 렌치 멤버한테 보안 요원을 시키는 거야?)",
  ui_story_5004_50040701_45_option_content = "괜히 참견하지 말자.",
  ui_story_5004_50040701_46_dialog_content = "너희 레디젤 렌치가 언제부터 그런 정의감이 있었는데?",
  ui_story_5004_50040701_47_dialog_content = "지금은 달라. 난 플뢰르의 의뢰를 받은 몸이야!\n지금 난 무려 <color=#FFB400>헤븐즈 비치의 보안 요원</color>이라고!",
  ui_story_5004_50040701_48_dialog_content = "...(대체 어떤 인간이 레디젤 렌치 멤버한테 보안 요원을 시키는 거야?)",
  ui_story_5004_50040701_49_dialog_content = "아무튼 잔말 말고 빨리 따라와.",
  ui_story_5004_50040701_50_dialog_content = "어이, 거기 수상한 녀석.",
  ui_story_5004_50040701_51_dialog_content = "......",
  ui_story_5004_50040701_52_dialog_content = "어이!",
  ui_story_5004_50040701_53_dialog_content = "건드리지 마!",
  ui_story_5004_50040701_54_dialog_content = "PlayerName, 봤어?! 이 녀석이 먼저 쳤다고──!",
  ui_story_5004_50040701_55_dialog_content = "잠깐만! 어차피 피해서 안 맞았잖아. 무턱대고 폭력은 곤란해.",
  ui_story_5004_50040701_56_dialog_content = "뭐야? 멍청해 보이는 게.",
  ui_story_5004_50040701_57_dialog_content = "갑자기 소리를 지르질 않나, 멋대로 숙녀의 어깨에 손을 얹어?",
  ui_story_5004_50040701_58_dialog_content = "작업 거는 거면 딴 데 가서 알아보라고! 난 너희 같은 애들이\n건드릴 수 있는 상대가 아니니까.",
  ui_story_5004_50040701_59_dialog_content = "PlayerName, 비켜! 말리지 마! 당장 잡아다가 혼쭐을 내줄 테니까!",
  ui_story_5004_50040701_60_dialog_content = "좋아, 안 그래도 마침 분풀이할 상대가 필요했는데──",
  ui_story_5004_50040701_61_dialog_content = "후후훗... <color=#FFB400>스모키</color>, 오랜만에 만났는데\n그런 저속한 녀석이랑 치근대고 있을 줄은 몰랐네.",
  ui_story_5004_50040701_62_dialog_content = "그래서야 귀족 신분에 부끄럽지 않겠어?",
  ui_story_5004_50040701_63_dialog_content = "넌 또 뭐야? 내가 귀족이든 아니든 네가 무슨 상관인데?",
  ui_story_5004_50040701_64_dialog_content = "뭐, 뭐야?! 날 기억 못 하는 거야?",
  ui_story_5004_50040701_65_dialog_content = "어이, 아직 얘기가 안 끝...",
  ui_story_5004_50040701_66_dialog_content = "조용히 해!",
  ui_story_5004_50040701_67_dialog_content = "다시 똑똑히 봐!",
  ui_story_5004_50040701_68_dialog_content = "전혀 기억이 없다고. 일단 좀 떨어져서 말해.",
  ui_story_5004_50040701_69_dialog_content = "정말 모르겠어? <color=#FFB400>제네비브</color>! <color=#FFB400>브론스키 가문</color>의 <color=#FFB400>제네비브</color>라고!",
  ui_story_5004_50040701_70_dialog_content = "아... 잠깐 생각 좀...",
  ui_story_5004_50040701_71_dialog_content = "페테르부르크의...",
  ui_story_5004_50040701_72_dialog_content = "아, 페테르부르크!",
  ui_story_5004_50040701_73_dialog_content = "<size=30>PlayerName, 이 녀석들... 뭐가 어떻게 된 거지...?</size>",
  ui_story_5004_50040701_74_dialog_content = "<size=30>나라고 알겠냐고...</size>",
  ui_story_5004_50040701_75_dialog_content = "아! 생각났어! 제네비브! 키가 많이 컸잖아?",
  ui_story_5004_50040701_76_dialog_content = "뭐, 뭐야, 그 태도...?! 정말 짜증 난다고...!",
  ui_story_5004_50040701_77_dialog_content = "나와 우리 가문이 고작 너 같은 녀석 때문에 수모를 당하고... 명예를 잃다니!",
  ui_story_5004_50040701_78_dialog_content = "또 무슨 소리야? 이번엔 정말 모르는 얘기라고.",
  ui_story_5004_50040701_79_dialog_content = "아, 방금 머리를 너무 썼더니 어지러워졌어.",
  ui_story_5004_50040701_80_dialog_content = "으음... 아! 그래, 나 사실 기억상실증이야. 이제 됐지?",
  ui_story_5004_50040701_81_dialog_content = "그럼 안녕, 무척이나 아름다워진 제네비브 양──!",
  ui_story_5004_50040701_82_dialog_content = "멈춰! 거기 서!",
  ui_story_5004_50040701_83_dialog_content = "......",
  ui_story_5004_50040701_84_dialog_content = "그렇게 날 쳐다봐도 소용없다고...",
  ui_story_5004_50040701_85_dialog_content = "에? 붙잡지 마. 내가 여자는 안 때리긴 하지만...",
  ui_story_5004_50040701_86_dialog_content = "이렇게 손잡고 있는 걸 남들이 보면 곤란하잖아?",
  ui_story_5004_50040701_87_dialog_content = "누가 우리 사이를 오해하기라도 하면 어떡해?",
  ui_story_5004_50040701_88_dialog_content = "스모키이이──!",
  ui_story_5004_50040701_89_dialog_content = "절대 용서 못 해!",
  ui_story_5004_50040701_90_dialog_content = "PlayerName, 이제 싸우려는 모양인데?",
  ui_story_5004_50040701_91_dialog_content = "뭘 그렇게 기대하는 표정으로 보고 있는 거냐고...",
  ui_story_5004_50040701_92_dialog_content = "어이, 넌 몰라. 레디젤 렌치에서 싸움이란 감정을 나누고\n실력을 증명하는 중요한 활동이라고.",
  ui_story_5004_50040701_93_dialog_content = "뭐, 그러시든지... 근데 난 왠지 저 금발 여자애가 이길 것 같아.",
  ui_story_5004_50040701_94_dialog_content = "왜?",
  ui_story_5004_50040701_95_dialog_content = "아이테르로서의 직감이야.",
  ui_story_5004_50040701_96_dialog_content = "역시 뭘 모른다니까. 저 스모키라는 은발 머리 여자애를 봐.",
  ui_story_5004_50040701_97_dialog_content = "스텝도 안정적이고, 평소 동작에도 빈틈이 전혀 없잖아.",
  ui_story_5004_50040701_98_dialog_content = "게다가 저 자신감 넘치는 눈빛을 봐. 절대 평범한 사람이 아냐.",
  ui_story_5004_50040701_99_dialog_content = "하지만 저 금발 여자애는 기세는 무척 강하지만, 자기 감정을 잘 통제하지 못해.\n그건 다시 말해서 힘을 능숙하게 다루지 못한다는 뜻이기도 해.",
  ui_story_5004_50040701_100_dialog_content = "아마 루미나를 다루는 능력도 아직 부족한 점이 많을 거야.",
  ui_story_5004_50040701_101_dialog_content = "뭐야, 갑자기... 무슨 해설자라도 된 것처럼.",
  ui_story_5004_50040701_102_dialog_content = "크오오──!",
  ui_story_5004_50040701_103_dialog_content = "방해하지 마!",
  ui_story_5004_50040701_103X_dialog_content = "뭐야?! 여기 왜 암귀가 있는 거지?",
  ui_story_5004_50040701_103X1_dialog_content = "뭘 놀라고 그래? 암귀도 그냥 이 지역 특산품으로 취급하면 되잖아.",
  ui_story_5004_50040701_104_dialog_content = "꽤 하잖아? 저 제네비브라는 여자애도 나름대로 실력이 있어.",
  ui_story_5004_50040701_105_dialog_content = "어이, 뒤에도 암귀가 있어!",
  ui_story_5004_50040701_106_dialog_content = "잠깐만, 렉커, 너 보안 요원이라면서? 그냥 이렇게 구경만 해도 되는 거야?",
  ui_story_5004_50040701_107_dialog_content = "아, 맞다! 깜빡 잊고 있었네!",
  ui_story_5004_50040701_108_dialog_content = "자, 암귀 조무래기들, 전부 모래에 파묻힐 준비는 됐겠지?",
  ui_story_5004_50040701_109_dialog_content = "풀 스로틀!",
  ui_story_5004_50040701_110_dialog_content = "둘이서 깔끔하게 쓸어버렸네!",
  ui_story_5004_50040701_111_dialog_content = "당연하지. 별거 아니라고.",
  ui_story_5004_50040701_112_dialog_content = "괜찮아?",
  ui_story_5004_50040701_113_dialog_content = "칫... 누가 멋대로 끼어들래!",
  ui_story_5004_50040701_114_dialog_content = "너희가 갑자기 방해해서 저 녀석이 도망쳤잖아!",
  ui_story_5004_50040701_115_dialog_content = "미, 미안해!",
  ui_story_5004_50040701_116_dialog_content = "최악이야! 나한테 말 걸지 마!",
  ui_story_5004_50040701_117_dialog_content = "그 녀석이 뭘 하고 있는지 알아내야 해...\n그리고 녀석의 계획을 철저히 망가트려 주겠어...!",
  ui_story_5004_50040701_118_dialog_content = "뭐, 그래도 도와준 건 고마워! 그럼 안녕!",
  ui_story_5004_50040701_119_dialog_content = "가버렸어...",
  ui_story_5004_50040701_120_dialog_content = "PlayerName, 봤지? 암귀보다 더 무서운 건 여자들의 싸움이라고.",
  ui_story_5004_50040701_121_dialog_content = "넌 저런 일에 휘말리지 않는 게 좋을 거다.",
  ui_story_5004_50040701_122_dialog_content = "그럴 생각 전혀 없거든...",
  ui_story_5004_50040701_123_dialog_content = "맛있어──!",
  ui_story_5004_50040701_124_dialog_content = "입가에 수프가 묻었잖아. 닦아줄게.",
  ui_story_5004_50040701_125_dialog_content = "으응... 고마워!",
  ui_story_5004_50040701_126_dialog_content = "일루미나의 공동 식당에선 이렇게 맛있는 음식을 먹을 수가 없거든.\n너무 맛있어서 참을 수가 없어!",
  ui_story_5004_50040701_127_dialog_content = "근데 저 밥 퍼주는 언니, 손을 자꾸 덜덜 떨어서...\n원래도 조금밖에 안 주는 고기를 다 떨어트렸다니까.",
  ui_story_5004_50040701_128_dialog_content = "난 아직도 성장 중인데 말이야──! 고기가 필요해!",
  ui_story_5004_50040701_129_dialog_content = "하긴, 넌 백야성에 유학을 왔을 때도 성 안의 레스토랑에 매일 갔을 정도니까.",
  ui_story_5004_50040701_132_dialog_content = "플뢰르, 계속 그렇게 손님 대하듯 챙겨주지 않아도 돼.\n다 친구들인데 너도 같이 앉아서 먹자.",
  ui_story_5004_50040701_133_dialog_content = "그럴 순 없지. 너흰 지금 이 호텔의 귀한 손님들이고,\n내 임무는 최상의 서비스를 제공하는 거니까.",
  ui_story_5004_50040701_134_dialog_content = "그래도...",
  ui_story_5004_50040701_135_dialog_content = "신경 쓸 거 없어, PlayerName.",
  ui_story_5004_50040701_136_dialog_content = "플뢰르가 남을 돕는 걸 좋아하는 성격인 건 모두가 아니까 말이야.\n지금 오히려 즐기고 있는 거라니까.",
  ui_story_5004_50040701_137_dialog_content = "렉커, 뭐 좀 마실래?",
  ui_story_5004_50040701_138_dialog_content = "그럼 난 슈퍼 아이스 하이스키!",
  ui_story_5004_50040701_139_dialog_content = "응, 금방 갖다줄게.",
  ui_story_5004_50040701_140_dialog_content = "......",
  ui_story_5004_50040701_141_dialog_content = "PlayerName, 왜 얼굴이 빨개졌어?",
  ui_story_5004_50040701_142_dialog_content = "내, 내가 뭘?!",
  ui_story_5004_50040701_143_dialog_content = "아무래도 아이테르인 너도 저 녀석의 영향을 피할 순 없는 모양이네.",
  ui_story_5004_50040701_144_dialog_content = "영향이라니... 무슨 뜻이야?",
  ui_story_5004_50040701_145_dialog_content = "궁금하면 녀석한테 직접 물어봐.",
  ui_story_5004_50040701_146_dialog_content = "그나저나, 오후에 본 그 두 여자는 대체 뭐였을까?",
  ui_story_5004_50040701_147_dialog_content = "나도 모르지... 아는 사람도 아니고.",
  ui_story_5004_50040701_148_dialog_content = "정말 수상하단 말이지. 날 찼던 그 녀석, 분명히 뭔가를 찾고 있었어.",
  ui_story_5004_50040701_149_dialog_content = "아무래도 차 열쇠를 다른 곳에 묻어야겠어.",
  ui_story_5004_50040701_150_dialog_content = "네 차를 훔칠 사람은 아무도 없거든!",
  ui_story_5004_50040701_151_dialog_content = "응? 여기저기서 물건 찾는 사람 말이야?\n나랑 베릴도 오늘 오후에 한 명 봤어.",
  ui_story_5004_50040701_152_dialog_content = "맞지? 베릴.",
  ui_story_5004_50040701_153_dialog_content = "응... 회색에 가까운 백발에... 선글라스를 쓰고...\n뭔가 다가가기 어려운... 무서운 느낌이었어...",
  ui_story_5004_50040701_154_dialog_content = "(우리가 본 그 사람이랑 같은 사람인 것 같은데?)",
  ui_story_5004_50040701_155_dialog_content = "그 사람 진짜 무례했다니까, PlayerName.\n이리저리 다니면서 정말 제멋대로였다구.",
  ui_story_5004_50040701_156_dialog_content = "심지어 베릴이 애써 만든 모래성까지 짓밟아 버렸다니까!",
  ui_story_5004_50040701_157_dialog_content = "높이가 3미터가 넘는 커──다란 모래성이었는데, 이~따만했다구!",
  ui_story_5004_50040701_158_dialog_content = "괜찮아. 그 사람도 나한테 진심으로 사과했으니까.",
  ui_story_5004_50040701_159_dialog_content = "그래도~! 베릴이 오후 내내 만든 거잖아!",
  ui_story_5004_50040701_160_dialog_content = "응... 괜찮아. 이렇게 마음 편히 쉴 수 있는 것만으로...\n난... 충분히 즐거운걸.",
  ui_story_5004_50040701_161_dialog_content = "그리고 그 성은... 왠지 계속 내 머릿속에 있는 것 같아...\n눈을 감아도 그 모습이 보여.",
  ui_story_5004_50040701_162_dialog_content = "라파엘이 마음에 들었다면... 내일 또 만들어 줄게...",
  ui_story_5004_50040701_163_dialog_content = "우와! 진짜? 그럼 베릴이랑 또 모래성 쌓을래!",
  ui_story_5004_50040701_164_dialog_content = "응...",
  ui_story_5004_50040701_165_dialog_content = "하지만 결국 그 녀석이 누구인지, 뭘 꾸미고 있는지는 알아내지 못했어.",
  ui_story_5004_50040701_166_dialog_content = "잊어버려, 렉커. 그렇게 신경 쓸 필요는 없잖아.",
  ui_story_5004_50040701_167_dialog_content = "난 플뢰르한테 보안 요원 일을 성실히 맡아주겠다고 약속했다고.",
  ui_story_5004_50040701_168_dialog_content = "(농땡이 부리다 나한테 걸린 주제에...)",
  ui_story_5004_50040701_169_dialog_content = "렉커가 내 부탁을 받고 여기까지 와준 건 사실이야.",
  ui_story_5004_50040701_170_dialog_content = "자, 주문한 거. 얼음도 넣었어.",
  ui_story_5004_50040701_171_dialog_content = "말했잖아. 난 약속한 건 확실하게 지키는...푸우웁!",
  ui_story_5004_50040701_172_dialog_content = "뭐, 뭐야 이거?!",
  ui_story_5004_50040701_173_dialog_content = "아, 미안, 휘발유가 없어서 비슷한 걸 대신 넣었거든! 말해주는 걸 깜빡했네.",
  ui_story_5004_50040701_174_dialog_content = "뭐야? 그럼 렉커가 평소에 마신 건 휘발유였다고?\n레디젤 렌치 사람들은 정말 놀랍다니까...",
  ui_story_5004_50040701_175_dialog_content = "자, 이쪽은 PlayerName 네 거.",
  ui_story_5004_50040701_176_dialog_content = "스페셜 웰컴 드링크야.",
  ui_story_5004_50040701_177_dialog_content = "...이건 휘발유 아니지?",
  ui_story_5004_50040701_178_dialog_content = "술도 아니고, 휘발유도 아니니까 걱정하지 마.\n노약자도 안심하고 마실 수 있는 음료야.",
  ui_story_5004_50040701_X178_dialog_content = "고마워, 넌 정말 볼수록 친절한 것 같네.",
  ui_story_5004_50040701_179_dialog_content = "그나저나, 혹시 괜찮다면... 언제 시간을 내서\nPlayerName 너랑 둘이서 얘기를 좀 하고 싶어.",
  ui_story_5004_50040701_180_dialog_content = "시간이야 있지.",
  ui_story_5004_50040701_181_dialog_content = "(새콤달콤한 게 정말 신기한 맛이네... 귤 향기도 나고, 끝 맛도 뭔가 풍성해.)",
  ui_story_5004_50040701_182_dialog_content = "(무척 복잡한 음료인 모양이네...)",
  ui_story_5004_50040901_1_dialog_content = "안 되겠어. 일어나야지...",
  ui_story_5004_50040901_2_dialog_content = "또 부품 더미 속에서 잠들어 버렸네.\n톱니바퀴 모서리가 배겨서 등이 아프잖아...",
  ui_story_5004_50040901_3_dialog_content = "이 설계도는... 어젯밤에 그린 건가. 음...",
  ui_story_5004_50040901_4_dialog_content = "쓸모없어 보이네. 버리지 뭐.",
  ui_story_5004_50040901_5_dialog_content = "역시 <color=#FFB400>아이테르의 지식</color>을 빌리는 수밖에 없는 건가…",
  ui_story_5004_50040901_6_dialog_content = "백야성과 일루미나의 로봇에 대한 분석만으로는\n내가 꿈꾸는 「그것」을 만들어낼 수가 없어.",
  ui_story_5004_50040901_7_dialog_content = "일단 샤워부터 하고... 이따가 PlayerName한테 만나자고 해야겠어.",
  ui_story_5004_50040901_8_dialog_content = "해신제를 무사히 마칠 수 없다면...\n난 내 <color=#FFB400>특수한 체질</color>의 영향에서 벗어날 수 없을 거라고...",
  ui_story_5004_50040901_9_dialog_content = "(난 원래 그저 평범한 일루미나의 엔지니어였는데...)",
  ui_story_5004_50040901_10_dialog_content = "(하지만 격세유전되는 이 「특이한 체질」 때문에...)",
  ui_story_5004_50040901_11_dialog_content = "(학교에 다닐 때...)",
  ui_story_5004_50040901_12_dialog_content = "플뢰르, <size=45>플뢰르!</size>",
  ui_story_5004_50040901_13_dialog_content = "하하하, 다들 안녕!",
  ui_story_5004_50040901_14_dialog_content = "플뢰르, 이 문제 좀 가르쳐줄 수 있어?",
  ui_story_5004_50040901_15_dialog_content = "물론이야. 잘 모르는 게 있으면 얼마든지 물어봐도 돼.",
  ui_story_5004_50040901_16_dialog_content = "너 왜 맨날 플뢰르한테 귀찮게 구는 거야?",
  ui_story_5004_50040901_17_dialog_content = "설마 플뢰르한테 무슨 딴생각이라도 품고 있는 건 아니지?!",
  ui_story_5004_50040901_18_dialog_content = "그게 뭐! <size=45>플뢰르가 네 것도 아니잖아!</size>",
  ui_story_5004_50040901_19_dialog_content = "어이! 너희 여자애들, 맨날 플뢰르한테 붙어 있지 말라고.",
  ui_story_5004_50040901_20_dialog_content = "플뢰르는 너희 같은 여자애들한테 전혀 관심이 없다고! 안 그래?",
  ui_story_5004_50040901_21_dialog_content = "뭐라고?! 플뢰르, 넌 여자가 좋아? 아니면 남자가 좋아?\n대체 넌 누굴 좋아하는데?",
  ui_story_5004_50040901_22_dialog_content = "난 모두가 좋은데...",
  ui_story_5004_50040901_23_dialog_content = "그 학생은 기계공학 분야에 상당한 재능이 있고, 업무 태도도 성실하며, 사람들에게 친절합니다.",
  ui_story_5004_50040901_24_dialog_content = "일루미나인으로서 매우 모범적인 자라 할 수 있습니다.",
  ui_story_5004_50040901_25_dialog_content = "하지만 그 학생의 특수한 체질은 타인과의 협력을 어렵게 만들고 있습니다...",
  ui_story_5004_50040901_26_dialog_content = "상대가 남성이든, 여성이든, 심지어는 동물까지도 그에게 영향을 받고 맙니다.",
  ui_story_5004_50040901_27_dialog_content = "게다가 <color=#FFB400>「그 사건」</color>으로 인해 다수의 부상자가 발생했습니다.",
  ui_story_5004_50040901_28_dialog_content = "휴, 그러면 그 학생은 새로 건설한 <color=#FFB400>38호 지하성</color>으로 파견하는 게 좋겠군요.\n적어도 거긴 오로리안의 수가 적은 편이니...",
  ui_story_5004_50040901_29_dialog_content = "저번처럼 쉽게 소란이 발생하진 않을 겁니다.",
  ui_story_5004_50040901_30_dialog_content = "축하한다, 플뢰르. 우린 자네를 38호 지하성 건설을\n지원할 전문가로 파견하기로 결정했다.",
  ui_story_5004_50040901_31_dialog_content = "이건 조직이 자네를 그만큼 신뢰한다는 뜻이고, 흔치 않은 기회다.",
  ui_story_5004_50040901_32_dialog_content = "그곳엔 자네의 능력을 발휘할 수 있는 기회가 있을 것이다.\n자네라면 분명히 지난 일을 만회할 큰 성과를 이루리라 믿는다!",
  ui_story_5004_50040901_33_dialog_content = "(그때의 생활은 정말 즐거웠지... 단순하고, 순수하면서... 평온했어.)",
  ui_story_5004_50040901_34_dialog_content = "우리 와이프가 다음 주에 38호 지하성에 올 거야!\n벌써 몇 년째 얼굴도 못 봤다고!",
  ui_story_5004_50040901_35_dialog_content = "근데 저 녀석이 계속 여기 있어서 와이프도 못 보고, 딸아이도 못 오게 됐잖아!",
  ui_story_5004_50040901_36_dialog_content = "심지어 우리 집 개까지 매일 같이 저 녀석한테 가서 애교를 부린다고!",
  ui_story_5004_50040901_37_dialog_content = "다들 녀석한테 멀리 떨어져야 겨우 영향을 피할 수 있어!",
  ui_story_5004_50040901_38_dialog_content = "여러분, 진정하세요. 플뢰르는 여러분이 생각하는 것처럼\n그렇게 무서운 사람이 아닙니다.",
  ui_story_5004_50040901_39_dialog_content = "거짓말하지 마! 전에 녀석이 학교에서 일으킨 <color=#FFB400>「그 사건」</color> 은\n일루미나에서 모르는 사람이 없다고!",
  ui_story_5004_50040901_40_dialog_content = "녀석 때문에 사람들이 다쳤는데 왜 녀석을 감싸고 도는 거야!",
  ui_story_5004_50040901_42_dialog_content = "플뢰르, 지금까지 38호 지하성을 위한 당신의 기여는 연방에서도 감사하고 있어.",
  ui_story_5004_50040901_43_dialog_content = "하지만 이젠 자난성으로 돌아가 줘야겠어. 이곳의 시민들이...",
  ui_story_5004_50040901_44_dialog_content = "말씀 안 하셔도 됩니다. 저도 알고 있으니까요.",
  ui_story_5004_50040901_45_dialog_content = "하지만 전 가고 싶지 않습니다.",
  ui_story_5004_50040901_46_dialog_content = "전 38호 지하성을 떠나고 싶지 않습니다. 이곳에서 전...\n평온하고 즐거운 추억을 많이 만들었습니다.",
  ui_story_5004_50040901_47_dialog_content = "여기선 사람들에게 휩싸이지도 않고 안심하고 원하는 연구를 진행할 수 있잖아요.",
  ui_story_5004_50040901_48_dialog_content = "당신들도 처음에 제게 그랬었죠. 이곳에서 큰 성과를 이룰 거라고 말이죠...",
  ui_story_5004_50040901_49_dialog_content = "......",
  ui_story_5004_50040901_50_dialog_content = "미안해. 지금은 상황이 달라졌어. 당신이 가지 않겠다면,\n우린 당신을 강제로 송환시키는 수밖에 없어.",
  ui_story_5004_50040901_51_dialog_content = "다시 돌아가면... 제가 뭘 할 수 있죠?",
  ui_story_5004_50040901_52_dialog_content = "절 격리시킬 건가요? 아니면 연구 부서로 보낼 건가요?",
  ui_story_5004_50040901_53_dialog_content = "미안해...",
  ui_story_5004_50040901_54_dialog_content = "우린 정말... 최선을 다했어.",
  ui_story_5004_50040901_55_dialog_content = "하지만 지금은... 아직 기회가 있어!",
  ui_story_5004_50040901_56_dialog_content = "플라티나 선라이즈 호텔에 오신 걸 환영해요, 플뢰르 씨.\n편지는 읽어 보셨나요?",
  ui_story_5004_50040901_57_dialog_content = "네, 해신제를 무사히 진행할 수 있도록 도와주면...\n정말 제 「특이한 체질」을 해결할 수 있는 건가요?",
  ui_story_5004_50040901_58_dialog_content = "안심하세요. 이건 제가 유적 발굴 중에 얻은 정보예요.\n만약 「그 전설」이 사실이라면 반드시 가능할 거예요!",
  ui_story_5004_50040901_59_dialog_content = "음... 이 청년이 바로 플뢰르인가?\n그럼 로비 매니저 일과 해신제 준비 작업은 자네에게 맡기겠네.",
  ui_story_5004_50040901_59X1_dialog_content = "알겠어요. 그럼 바로 준비하죠.",
  ui_story_5004_50040901_59X2_dialog_content = "순조로워 보이는군. 그런데 방금 말했던 「그 전설」은 뭐지?",
  ui_story_5004_50040901_59X3_dialog_content = "...그냥 지어낸 거예요. 어쨌든 사람만 불러와 주면 되는 거잖아요?",
  ui_story_5004_50040901_59X4_dialog_content = "하하... 그래, 좋다. 명단에 있는 자들을 데려올 수만 있다면,\n어떤 수단을 사용해도 상관없다...",
  ui_story_5004_50040901_59X5_dialog_content = "해신제... 이번 기회를 절대 놓치지 않겠어.",
  ui_story_5004_50040901_60_dialog_content = "자, 준비는 끝났어...",
  ui_story_5004_50040901_61_dialog_content = "가는 거야... 플뢰르!",
  ui_story_5004_50040901_62_dialog_content = "플뢰르!",
  ui_story_5004_50040901_63_dialog_content = "<size=45>플뢰르 씨!</size>",
  ui_story_5004_50040901_64_dialog_content = "다들 안녕.",
  ui_story_5004_50040901_65_dialog_content = "플뢰르 씨, 향이 정말 매력적이에요~!",
  ui_story_5004_50040901_66_dialog_content = "방금 샤워하신 건가요? 물소리가 들리던데요!",
  ui_story_5004_50040901_67_dialog_content = "아, 저기... 미안하지만, 다들 조금만 비켜줄 수 있을까요?",
  ui_story_5004_50040901_68_dialog_content = "방에 들어가서 좀 구경해도 될까요?",
  ui_story_5004_50040901_69_dialog_content = "아, 방에 있는 부품들을 어지럽히면 곤란해서요...",
  ui_story_5004_50040901_70_dialog_content = "뢰르뢰르~ 요가 선생님 말로는 수업에 등록만 하면\n뢰르뢰르랑 같이 요가를 할 수 있다고 들었는데, 그게 진짜야~?",
  ui_story_5004_50040901_71_dialog_content = "네? 그게 무슨 말이죠? 그건 뭔가 사기당한 것 같은데...",
  ui_story_5004_50040901_72_dialog_content = "자, 다들 진정하세요. 반겨줘서 고맙지만 전 약속이 있어서...\n그러니까 좀 비켜줄 수 있을까요?",
  ui_story_5004_50040901_73_dialog_content = "<anim type=Shake><size=45>뭐야아──?!</size></anim>",
  ui_story_5004_50040901_74_dialog_content = "그게 누구야! 누가 몰래 선수를 친 건데!",
  ui_story_5004_50040901_75_dialog_content = "플뢰르 씨, 나랑 데이트하는 게 더 좋지 않아?",
  ui_story_5004_50040901_76_dialog_content = "(휴, PlayerName... 미안해, 조금만 더 기다려 줘.)",
  ui_story_5004_50041001_1_dialog_content = "그렇구나. 이해했어!",
  ui_story_5004_50041001_2_dialog_content = "설명해 줘서 정말 고마워! 그리고 약속에 늦은 것도\n너그럽게 이해해 줘서 정말 고마워!",
  ui_story_5004_50041001_3_dialog_content = "아니야. 별로 안 기다렸거든. 근데 플뢰르, 정말 로봇을 만들고 싶은 거야?",
  ui_story_5004_50041001_4_dialog_content = "응, 그건 내가 오래전부터 꿈꿔온 거거든.",
  ui_story_5004_50041001_5_dialog_content = "<color=#e8d9bb>똑똑똑.</color>",
  ui_story_5004_50041001_6_dialog_content = "PlayerName 씨~ 들어가도 될까요?",
  ui_story_5004_50041001_7_dialog_content = "들어와.",
  ui_story_5004_50041001_8_dialog_content = "플뢰르 씨도 여기 계셨네요?",
  ui_story_5004_50041001_9_dialog_content = "당신은 해신제 기획팀의 리더잖아요. 혹시 게으름 피우려는 건 아니죠?",
  ui_story_5004_50041001_10_dialog_content = "그럴 리가요. 설계 때문에 PlayerName한테 물어볼 게 있었을 뿐이에요.",
  ui_story_5004_50041001_11_dialog_content = "그럼 가서 한번 시험해 볼게. 안녕.",
  ui_story_5004_50041001_12_dialog_content = "PlayerName 씨, 어떤가요? 해신제에 참가하실 건가요?\n이번 상품은 무려...",
  ui_story_5004_50041001_13_dialog_content = "참가할게.",
  ui_story_5004_50041001_14_dialog_content = "에?",
  ui_story_5004_50041001_15_dialog_content = "왜? 무슨 문제라도 있어? 동료들이랑은 이미 얘기했어.",
  ui_story_5004_50041001_16_dialog_content = "이렇게 흔쾌히 결정해 주실 줄은 몰랐네요!",
  ui_story_5004_50041001_17_dialog_content = "그냥 축제에 참가하는 것뿐이잖아. 망설일 게 뭐 있겠어?",
  ui_story_5004_50041001_18_dialog_content = "우후훗, PlayerName 씨는 혹시 무슨 음모라도 있는 건 아닐까\n걱정되지 않으시는 건가요?",
  ui_story_5004_50041001_19_dialog_content = "음모?! 그럼 참가 안 할래!",
  ui_story_5004_50041001_20_dialog_content = "우후훗~ 정말 귀여운 분이시네요. 비록 제가 진리의 결사의 일원이긴 하지만,\n그렇다고 음모 같은 걸 대놓고 말하거나 하진 않을 거예요.",
  ui_story_5004_50041001_21_dialog_content = "방금 건 장난이었어요. 전 그저 당신의 훌륭한 결단에 경의를 표했을 뿐이에요.",
  ui_story_5004_50041001_22_dialog_content = "(진리의 결사엔 왜 전부 이런 이상한 사람뿐인 건데!)",
  ui_story_5004_50041001_23_dialog_content = "참가를 결정하셨으니, 그럼 이 서류에 사인을 해 주세요.",
  ui_story_5004_50041001_24_dialog_content = "자, 여기 이 펜으로 쓰시면 돼요.",
  ui_story_5004_50041001_25_dialog_content = "으음...! 이 펜, 무척 정교해 보이네.",
  ui_story_5004_50041001_26_dialog_content = "게다가 얼음처럼 차갑고, 손에 착 달라붙는 느낌...",
  ui_story_5004_50041001_27_dialog_content = "이 펜은 무척 비싸답니다. 매우 희귀한 수정으로 만든 거예요.",
  ui_story_5004_50041001_28_dialog_content = "겉보기엔 펜 한 자루일 뿐이지만, 사실은 호텔의 절반 정도를 사들일 만한 가치가 있죠.",
  ui_story_5004_50041001_29_dialog_content = "PlayerName 씨가 관심이 있으시다면, 선물로 드릴 수도 있어요.",
  ui_story_5004_50041001_30_dialog_content = "뭐?! 그렇게 비싼 걸 받을 순 없어.",
  ui_story_5004_50041001_31_dialog_content = "괜찮아요. 어차피 유적에서 발굴한 거니까요.",
  ui_story_5004_50041001_32_dialog_content = "...이곳저곳에서 유적을 파내다니 역시 진리의 결사답네...",
  ui_story_5004_50041001_33_dialog_content = "칭찬 고마워요~ 참, 듣자 하니 콜로서스를 조종하는 장치는...\n피아노 모양이라면서요?",
  ui_story_5004_50041001_34_dialog_content = "전 음악가거든요. 그래서 그 이야기를 듣고 무척 흥미가 생겼지 뭐예요.\n언제 한번 직접 볼 수 있으면 좋겠는데 말이죠~",
  ui_story_5004_50041001_35_dialog_content = "구경이라면 얼마든지 괜찮아. 자, 사인했어. 여기 펜이랑 서류.",
  ui_story_5004_50041001_36_dialog_content = "으음... 확인했어요. 이제 당신은 정식으로 해신제의 참가자가 되었답니다.",
  ui_story_5004_50041001_37_dialog_content = "그럼 조금 더 쉬고 계세요. 오후부터 첫 번째 경기가 시작될 테니까요.",
  ui_story_5004_50041001_38_dialog_content = "그럼 활약을 기대할게요.",
  ui_story_5004_50041001_39_dialog_content = "하아... 이거 정말... 너무 순조롭잖아요.",
  ui_story_5004_50041001_40_dialog_content = "죄책감을 느낄 정도라구요...",
  ui_story_5004_50041001_X40_dialog_content = "뭐, 순조롭지 않을 리가 없겠죠.",
  ui_story_5004_50041001_X40X1_dialog_content = "이제 아이테르도 포함해서... 모두 모였네요.",
  ui_story_5004_50041001_X40X2_dialog_content = "저 사람이 저렇게 쉽게 「그 녀석」의 펜으로 사인을 할 줄이야...",
  ui_story_5004_50041001_X40X3_dialog_content = "「그 녀석」이 대체 무슨 속셈인 건지는 모르겠지만...\n뭐, 고작 그 암귀 몇 마리들이 뭘 할 수 있겠어요...",
  ui_story_5004_50041001_41_dialog_content = "이렇게 손쉽게 <color=#FFB400>「악장」</color>의 앞부분을 구할 수 있다니...",
  ui_story_5004_50041001_42_dialog_content = "PlayerName... 정말 재미있는 사람이네요.",
  ui_story_5004_50041101_1_dialog_content = "<color=#e8d9bb>같은 시간</color>",
  ui_story_5004_50041101_2_dialog_content = "좋아... 이미 열쇠를 손에 넣었구나...",
  ui_story_5004_50041101_3_dialog_content = "이제 그의 힘을 이용해... 신의 울림에 한 발 더 다가가는 거다.",
  ui_story_5004_50041101_4_dialog_content = "내가 너를 이끌어 주마... 넌 나를 위해 「열매」를 가져와라.",
  ui_story_5004_50041101_5_dialog_content = "이제 더는 보잘것없는 자들을 상대할 필요는 없다...\n이제 넌 진정한 음악의 극치로 나아가게 되는 것이다...",
  ui_story_5004_50041101_6_dialog_content = "네... 그게 바로... 제가 항상 꿈꿔왔던 거예요...!",
  ui_story_5004_50041101_7_dialog_content = "쳇, 네 혼잣말을 들을 때마다 괴상해서 기분이 나쁘다니까.\n네 머릿속의 목소리가 또 뭐라고 떠든 모양이지?",
  ui_story_5004_50041101_8_dialog_content = "뭐, 됐어. 네가 명단 속 사람들을 데려왔으니까,\n약속대로 악장의 앞부분은 넘겨줬다.",
  ui_story_5004_50041101_9_dialog_content = "그 소리가 악장의 뒷부분도 얼른 찾아달라고 재촉하고 있지 않나?",
  ui_story_5004_50041101_10_dialog_content = "이쪽은 이미 더 많은 암귀를 보내서 파내고 있는 중이다.\n하지만 손에 넣는다 해도 쓸모는 없을 거다.",
  ui_story_5004_50041101_11_dialog_content = "그건 아이테르의 힘이 없으면 깨울 수 없으니까.",
  ui_story_5004_50041101_12_dialog_content = "...당신이 상관할 일이 아니잖아요?",
  ui_story_5004_50041101_13_dialog_content = "분명히 말해둘게요. 제 목표는 완벽한 「신의 악장」을 손에 넣는 거지,\n당신들 같은 「암귀」와 손을 잡는 일이 아니라구요.",
  ui_story_5004_50041101_14_dialog_content = "당신들이 악장의 앞부분을 줬고, 뒷부분도 주겠다는 약속을 했으니까\n잠깐 협력하고 있을 뿐이에요.",
  ui_story_5004_50041101_15_dialog_content = "어디까지나 일시적인 거라구요. 앞으로도 계속해서 당신들과\n「작당」할 생각은 없어요. 아시겠어요?",
  ui_story_5004_50041101_15X_dialog_content = "그리고 당신들이 보낸 암귀는 이미 PlayerName 일행이 쓰러트렸어요.",
  ui_story_5004_50041101_16_dialog_content = "그 쓸모없는 생.쥐.들 말이죠.",
  ui_story_5004_50041101_17_dialog_content = "이 불결하고 추악한 오로리안이 감히!",
  ui_story_5004_50041101_18_dialog_content = "진정하세요.",
  ui_story_5004_50041101_19_dialog_content = "그 생쥐들이 들켜서 전멸당하면 당신도 곤란하지 않겠어요?",
  ui_story_5004_50041101_20_dialog_content = "그 우스꽝스러운 계획을 망치면 안 될 테니까요. 해신제를 이용해\n관광객을 모으고, 수영복 사진집을 팔아서 군자금을 버는 일 말이죠.",
  ui_story_5004_50041101_21_dialog_content = "게다가 요가 수업 같은 걸로 관광객한테 바가지를 씌우질 않나...",
  ui_story_5004_50041101_22_dialog_content = "정작 그렇게 모은 돈의 대부분은 배후의 진짜 보스에게 바치는 신세라니.",
  ui_story_5004_50041101_23_dialog_content = "「총지배인 대리」 씨도 결국엔 도구 신세네요~",
  ui_story_5004_50041101_24_dialog_content = "오로리안에게 고용당한 암귀라니, 소문이라도 났다간 동족들에게\n무슨 망신을 당할지 모른다구요.",
  ui_story_5004_50041101_25_dialog_content = "이, 이 자식! 네가 뭘 안다고! 우린...",
  ui_story_5004_50041101_26_dialog_content = "펭그그 님!",
  ui_story_5004_50041101_27_dialog_content = "제길... 그렇게 멋대로 지껄이는 것도 언젠가는 끝이다!",
  ui_story_5004_50041101_28_dialog_content = "타드, 손님 배웅해라.",
  ui_story_5004_50041101_29_dialog_content = "보나시외 양, 가시죠.",
  ui_story_5004_50041101_30_dialog_content = "같이 가시면서 제가 새로 기획한 요가 클래스에 대해 설명해 드리겠습니다.",
  ui_story_5004_50041101_31_dialog_content = "「완벽함은 태도에서 시작되고, 우아함은 생활에서 드러납니다.\n마음가짐이 너그러움은 만들고, 아름다운 인생은 요가에서 시작되죠.」",
  ui_story_5004_50041101_32_dialog_content = "「요가는 당신을 평범함에서 벗어나 특별한 아름다움을 지니도록 도와줍니다.」",
  ui_story_5004_50041101_33_dialog_content = "「요가는 일상을 벗어나 영혼을 치유하는 예술인 것입니다.」",
  ui_story_5004_50041101_34_dialog_content = "......",
  ui_story_5004_50041201_1_dialog_content = "도착했어. 여기가 경기장인가?",
  ui_story_5004_50041201_2_dialog_content = "...심판석, 네트... 스카이워커의 데이터베이스에서 본 모습이랑\n크게 다르지 않은 것 같아.",
  ui_story_5004_50041201_2X1_dialog_content = "응? 뭔가 특이한 물건이 있는데?",
  ui_story_5004_50041201_2X2_dialog_content = "신경 쓰지 않으셔도 돼요. 그저 평범한 「억제 장치」니까요.",
  ui_story_5004_50041201_2X3_dialog_content = "경기가 너무 과열돼서 주변의 시설을 망가트리는 일이 없게 방지하는 거예요.",
  ui_story_5004_50041201_2X4_dialog_content = "(엥? 그냥 평범한 비치발리볼 아니었어...?)",
  ui_story_5004_50041201_2X5_dialog_content = "휴... 이제 됐어요.",
  ui_story_5004_50041201_3_dialog_content = "응, 심판도 자리를 잡았어.",
  ui_story_5004_50041201_4_dialog_content = "신사 숙녀 여러분, 해신제의 첫 번째 경기에 오신 것을 환영합니다.\n이번 경기는 힘과 용기를 상징하는 비치발리볼 경기입니다.",
  ui_story_5004_50041201_5_dialog_content = "먼저 이쪽은 PlayerName 씨의 팀입니다.",
  ui_story_5004_50041201_6_dialog_content = "저기, 플뢰르 씨, 당신도 PlayerName 씨 쪽이에요.\n얼른 이쪽으로 서세요.",
  ui_story_5004_50041201_7_dialog_content = "어라? 플뢰르도 왔어?",
  ui_story_5004_50041201_8_dialog_content = "오랜만에 렉커랑 같이 경기에 나서볼까 했거든.\n보나시외 씨도 계속 권했고 말이야.",
  ui_story_5004_50041201_9_dialog_content = "이런, 이 녀석이 있으면 경기장이 난장판이 될 거라고...",
  ui_story_5004_50041201_10_dialog_content = "플뢰르──!",
  ui_story_5004_50041201_11_dialog_content = "뢰르뢰르!",
  ui_story_5004_50041201_12_dialog_content = "저럴 줄 알았다니까...",
  ui_story_5004_50041201_13_dialog_content = "휴, 난 스포츠 같은 건 영 자신이 없는데...",
  ui_story_5004_50041201_14_dialog_content = "PlayerName, 걱정하지 마. 나 비치발리볼 완전 잘해!",
  ui_story_5004_50041201_15_dialog_content = "바이스는 아카데미에서도 체육 성적은 아주 좋았어.",
  ui_story_5004_50041201_16_dialog_content = "<color=#FFB400>「철완소녀 바이스」</color>라는 별명이 있었을 정도니까.",
  ui_story_5004_50041201_17_dialog_content = "그러니까 안심해도 좋아, PlayerName.",
  ui_story_5004_50041201_18_dialog_content = "(백야성의 아카데미는 별명도 참 특이하게 짓는구나...)",
  ui_story_5004_50041201_19_dialog_content = "그, 그렇구나. 그럼 잘 됐네! 기대할게, 바이스!",
  ui_story_5004_50041201_20_dialog_content = "쳇, 너네랑 같은 팀이 될 줄은 몰랐네.",
  ui_story_5004_50041201_21_dialog_content = "넌 어제 그... 너도 해신제 경기에 참가하러 온 거야?",
  ui_story_5004_50041201_22_dialog_content = "이 사람! 어제 베릴이 쌓은 모래성을 부순 사람이야!",
  ui_story_5004_50041201_23_dialog_content = "뭔데? 오면 안 되는 이유라도 있어? 나도 저 보나시외한테 초대받은 거라고.",
  ui_story_5004_50041201_24_dialog_content = "그리고, 난 스모키야. 모래성 일은 이미 사과했잖아.",
  ui_story_5004_50041201_25_dialog_content = "그러니까 어차피 같은 팀이 된 이상, 그 얘기는 이제 그만 해.\n그럴 시간에 이기기 위해 전력을 다하라고.",
  ui_story_5004_50041201_26_dialog_content = "저 사나운 여자애가 어제 네가 말한 그 사람이지?\n왠지 상대하기 힘든 타입 같네...",
  ui_story_5004_50041201_27_dialog_content = "맞아... 근데... <color=#FFB400>다른 한 명</color>은 더 힘들걸.",
  ui_story_5004_50041201_28_dialog_content = "그리고 이쪽은 제네비브 씨와 친위대입니다!",
  ui_story_5004_50041201_29_dialog_content = "흥!",
  ui_story_5004_50041201_30_dialog_content = "내가 지금 말한 게 바로 저 녀석이야!",
  ui_story_5004_50041201_31_dialog_content = "<anim type=Shake><size=45>우와아아아──!</size></anim>",
  ui_story_5004_50041201_32_dialog_content = "후후훗... 봤지? 스모키!",
  ui_story_5004_50041201_33_dialog_content = "진정한 귀족이라면 가는 곳마다 평민들의 추앙을 받는 법이라고.",
  ui_story_5004_50041201_34_dialog_content = "저들은 내 고귀한 기품을 칭송하고, 내 막강한 힘에 굴복하는 거야.",
  ui_story_5004_50041201_35_dialog_content = "너 같은 녀석은 절대 이해하지 못한다고! 스모키!",
  ui_story_5004_50041201_36_dialog_content = "...아, 그래, 그래.",
  ui_story_5004_50041201_37_dialog_content = "참 나, 누가 그런 거 알고 싶대?\n넌 아직도 그런 귀찮고 시시한 일에 빠져 있는 거구나.",
  ui_story_5004_50041201_38_dialog_content = "어이, 거기 너희들, 정신 바짝 차리고 얼른 시작해 봐!",
  ui_story_5004_50041201_39_dialog_content = "죽음을 눈앞에 두고도 건방지긴... 이거나 받아라!",
  ui_story_5004_50041201_40_dialog_content = "잠깐만! 아직 경기 시작도 안 했다고!",
  ui_story_5004_50041201_41_dialog_content = "칫.",
  ui_story_5004_50041201_42_dialog_content = "우와, 그걸 피했어?!",
  ui_story_5004_50041201_43_dialog_content = "!!!",
  ui_story_5004_50041201_44_dialog_content = "(스모키가 피한 공이 이쪽으로 날아오고 있다.)",
  ui_story_5004_50041201_45_dialog_content = "(비치발리볼 경기에 참가했을 뿐인데, 자신의 나약함을\n이토록 원망해본 적은 태어나서 처음이다.)",
  ui_story_5004_50041201_46_dialog_content = "(암귀와 맞서는 공포보다... 이 죽음의 비치발리볼이 훨씬 더 무섭다.)",
  ui_story_5004_50041201_47_dialog_content = "(순간 주마등처럼 여러 생각이 스쳐 지나갔고, 나는 이미 눈을 감은 채였다.)",
  ui_story_5004_50041201_48_dialog_content = "(그저 내가 공에 맞아 바다로 날아가면 바이스가 최대한 빨리\n건져주길 기도할 뿐이었다.)",
  ui_story_5004_50041201_49_dialog_content = "바닷물은... 어떤 맛일까?",
  ui_story_5004_50041201_50_dialog_content = "PlayerName!",
  ui_story_5004_50041201_51_dialog_content = "...바이스! 괜찮아?",
  ui_story_5004_50041201_52_dialog_content = "난 괜찮아... 잘못하면 코트 밖으로 날아갈 뻔했어.",
  ui_story_5004_50041201_53_dialog_content = "너! 제네비브라고 했지! 아직 경기 시작 전이잖아! 이건 반칙이야!",
  ui_story_5004_50041201_54_dialog_content = "PlayerName 씨, 아무래도 제가 드린 참가자 매뉴얼을\n제대로 안 읽으신 모양이네요.",
  ui_story_5004_50041201_55_dialog_content = "그런 무겁고 두꺼운 데다가 광고가 잔뜩 있는 책자를 누가 다 읽겠냐고!",
  ui_story_5004_50041201_56_dialog_content = "그럼 제 탓을 하시면 안 되죠!",
  ui_story_5004_50041201_57_dialog_content = "자! 그럼 지금부터 여러분의 멋진 모습을 신들에게 보여주세요!\n싸움이 끝나는 그 순간까지──!",
  ui_story_5004_50041201_58_dialog_content = "(그제서야 나는 깨달았다. 이건 내가 생각한\n그런 비치발리볼 경기가 아니었다.)",
  ui_story_5004_50041201_59_dialog_content = "(이것은 해변을 무대로, 공을 무기로 삼아 싸우는\n피비린내 나는 혈투였던 것이다.)",
  ui_story_5004_50041202_1_dialog_content = "하아... 하아... 아직... 더 할 수 있어...",
  ui_story_5004_50041202_2_dialog_content = "왜 그래? 겨우 그 정도 실력밖에 안 되는 거야?",
  ui_story_5004_50041202_3_dialog_content = "미안해, PlayerName. 이럴 줄 알았으면 달의 고치를 가지고 왔을 텐데...",
  ui_story_5004_50041202_4_dialog_content = "괜찮아, 달의 고치가 있었어도 공만 터트렸을 거야...\n렉커랑 플뢰르도 있으니까, 우선 체력을 아껴 둬.",
  ui_story_5004_50041202_5_dialog_content = "어이! 너희 좀 더 힘을 내라고!",
  ui_story_5004_50041202_6_dialog_content = "그러는 넌 입만 떠들고 있잖아!",
  ui_story_5004_50041202_7_dialog_content = "야! 정신 차려! 공격이 온다고!",
  ui_story_5004_50041202_8_dialog_content = "고마워! 렉커!",
  ui_story_5004_50041202_9_dialog_content = "진형을 정비한다! 제네비브 님을 위하여!",
  ui_story_5004_50041202_10_dialog_content = "<size=45>제네비브 님을 위하여!</size>",
  ui_story_5004_50041202_11_dialog_content = "제길... 나는 안중에도 없는 것 같잖아.\n전혀 위협이 안 된다고 생각하는 건가?",
  ui_story_5004_50041202_12_dialog_content = "이대로는 안 돼... <color=#FFB400>그걸</color> 쓸 수밖에 없겠어!",
  ui_story_5004_50041202_13_dialog_content = "잠깐만! 갑자기 뭘 꺼낸 거야?!",
  ui_story_5004_50041202_14_dialog_content = "뭐야, <color=#FFB400>로봇 팔</color> 아냐?!",
  ui_story_5004_50041202_15_dialog_content = "하하, 무슨 소리야. 이건 그냥 <color=#FFB400>내 팔</color>이잖아.",
  ui_story_5004_50041202_16_dialog_content = "이건 「재난」 RX-100 모델이야. 타이니랑 공동 제작한 모델인데,\n특별히 출력을 3배로 향상시켰어!",
  ui_story_5004_50041202_17_dialog_content = "「재난」? 그거 요나가 쓰는 로봇 팔 아냐?!",
  ui_story_5004_50041202_18_dialog_content = "게다가 주먹에 빨간 장식만 더했을 뿐이잖아, 어디가 출력 3배라는 거냐!",
  ui_story_5004_50041202_19_dialog_content = "나의 손이 붉게 타오르고 있다! 승리를 움켜쥐라고 힘차게 외치고 있다──!",
  ui_story_5004_50041202_20_dialog_content = "이상한 대사는 그만해. 아무튼 로봇 팔은 안 돼.",
  ui_story_5004_50041202_21_dialog_content = "이 팔의 정확도와 힘은 그 누구한테도 뒤지지 않는다고.",
  ui_story_5004_50041202_22_dialog_content = "당연하지. 그게 로봇이니까.",
  ui_story_5004_50041202_23_dialog_content = "아무튼 이거 정말 대단하다니까. 공 같은 거 없이도\n사람을 10미터 넘게 날려버릴 수 있어.",
  ui_story_5004_50041202_24_dialog_content = "휴, 출력이 너무 셀까 걱정이네...",
  ui_story_5004_50041202_25_dialog_content = "됐으니까 로봇 팔 같은 건 빨리 떼라고! 이러다 실격 처리된다고!",
  ui_story_5004_50041202_26_dialog_content = "역시 안 되나? ...렉커는 정말 로망을 모른다니까.",
  ui_story_5004_50041202_27_dialog_content = "조심해!",
  ui_story_5004_50041202_28_dialog_content = "빈틈이다──!",
  ui_story_5004_50041202_29_dialog_content = "<color=#e8d9bb>펑! 퍼엉!</color>",
  ui_story_5004_50041202_30_dialog_content = "윽! ...으윽...",
  ui_story_5004_50041202_31_dialog_content = "아아... 여기서 끝인가... 하늘이... 정말 아름답네...",
  ui_story_5004_50041202_32_dialog_content = "렉커가 날아가서 모래 속에 처박혀 버렸어... 이게 어디가 비치발리볼이야?!",
  ui_story_5004_50041202_33_dialog_content = "1차전 종료! 중간 휴식 시간입니다──",
  ui_story_5004_50041202_34_dialog_content = "휴식 시간 동안 저희 스폰서 광고를 시청해주세요──",
  ui_story_5004_50041202_X33_dialog_content = "3",
  ui_story_5004_50041202_X34_dialog_content = "2",
  ui_story_5004_50041202_X35_dialog_content = "1",
  ui_story_5004_50041202_35_dialog_content = "지금 소개해 드릴 제품은 이번 시즌 공중상회에서\n가장 인기 있는 패키지 상품이랍니다.",
  ui_story_5004_50041202_36_dialog_content = "지금 바로 아이콘을 터치하시면 저 보나시외가 단독 제공하는\n스페셜 할인가에 특별 소집 스타 마커 10개까지 추가로 증정!",
  ui_story_5004_50041202_37_dialog_content = "사은품으로 해변에 가장 어울리는 튜브 탱크도 드린답니다!",
  ui_story_5004_50041202_38_dialog_content = "남은 패키지는 5000개, 앗! 벌써 1001개밖에 안 남았네요!",
  ui_story_5004_50041202_39_dialog_content = "매진 임박! 지금 당장 주문하세요──!",
  ui_story_5004_50041202_40_dialog_content = "어머! 벌써 패키지가 매진되었네요~",
  ui_story_5004_50041202_41_dialog_content = "그럼 앞으로도 보나시외의 쇼핑 초이스 채널에 많은 관심 부탁드릴게요.\n다음에 또 만나요~!",
  ui_story_5004_50041202_42_dialog_content = "지금 광고 같은 걸 할 때가 아니잖아아아!",
  ui_story_5004_50041202_43_dialog_content = "그럼 이제 움직일 수 있는 건 나랑...\n꿈쩍도 안 하는 저 스모키밖에 없는 거야?!",
  ui_story_5004_50041202_44_dialog_content = "어이! 스모키! 남의 일처럼 굴지 말고 너도 뭔가 방법을 찾아 보라고!",
  ui_story_5004_50041202_45_dialog_content = "뭐? 귀찮네, 너희가 알아서 끝내줄 줄 알았는데 말이지.",
  ui_story_5004_50041202_46_dialog_content = "정말 누구 하나 도움이 되는 녀석이 없네!",
  ui_story_5004_50041202_47_dialog_content = "조금 전까지 다들 널 지켜줬으니까 네가 공에 안 맞은 거잖아!",
  ui_story_5004_50041202_48_dialog_content = "다들 필사적으로 서로 돕지 않았다면 너도 진작에 탈락했을 거라고!",
  ui_story_5004_50041202_49_dialog_content = "이대로라면 경기에서 지고 말 거야. 그럼 모두의 희생이 물거품이 되고 말아!",
  ui_story_5004_50041202_50_dialog_content = "아, 그래그래. 말 하나는 번지르르하네.\n그래봤자 너도 옆에서 보고만 있었잖아?",
  ui_story_5004_50041202_51_dialog_content = "뭐, 그래도 너희들한테 빚을 지고 싶진 않으니까.",
  ui_story_5004_50041202_52_dialog_content = "그럼 넌 옆에서 내 멋진 모습이나 해설하고 있어.\n내가 어떻게 승리를 거머쥐는지 말이야!",
  ui_story_5004_50041202_53_dialog_content = "뭐? 해설이라니...? 뭐, 알겠어!\n네가 공을 받아낸다면 얼마든지 해줄 테니까!",
  ui_story_5004_50041202_54_dialog_content = "좋아!",
  ui_story_5004_50041202_55_dialog_content = "어이!",
  ui_story_5004_50041202_56_dialog_content = "제네비브──!",
  ui_story_5004_50041202_57_dialog_content = "응? 벌써 무서워졌어? 봐달라고 구걸이라도 할 생각이야?",
  ui_story_5004_50041202_58_dialog_content = "너 말이야. 남이 너보다 잘난 게 그렇게 신경 쓰여?",
  ui_story_5004_50041202_59_dialog_content = "당연하지... 나한테는 중요한 일이야. 우리 가문의 가훈도,\n내 자존심도 패배는 절대 용납하지 않아! 특히 너한테는 더더욱!",
  ui_story_5004_50041202_60_dialog_content = "넌 내 명예를 빼앗아갔어. 그래서 지난 몇 년 동안\n난 계속해서 네 행방을 쫓고 널 찾아다녔어.",
  ui_story_5004_50041202_61_dialog_content = "널 철저히 패배시켜 좌절과 고통, 후회로 몸부림치는 모습을 보기 위해서 말이야!",
  ui_story_5004_50041202_62_dialog_content = "...그거 정말 유감이네.",
  ui_story_5004_50041202_63_dialog_content = "뭐라고?!",
  ui_story_5004_50041202_64_dialog_content = "왜냐면... 나도 지는 건 무엇보다 싫은 사람이거든!",
  ui_story_5004_50041202_65_dialog_content = "그럼... 이 한 방으로 어디 한번 확인해 보자고!",
  ui_story_5004_50041202_66_dialog_content = "네 실력, 그리고 네 결심이 날 넘어섰는지 말이야!",
  ui_story_5004_50041202_67_dialog_content = "<anim type=Shake><size=45>「폭☆염 슈퍼 스파이크」!</size></anim>",
  ui_story_5004_50041202_68_dialog_content = "!!!",
  ui_story_5004_50041202_69_dialog_content = "이, 이건! 마치 지옥의 불꽃을 두른 듯한 강속구가\n제네비브를 향해 힘차게 날아가고 있어!",
  ui_story_5004_50041202_70_dialog_content = "(왜 나도 모르게 해설을 하고 있는 거냐고... 부끄럽게시리!)",
  ui_story_5004_50041202_71_dialog_content = "제네비브 님!",
  ui_story_5004_50041202_72_dialog_content = "제네비브를 지키려는 친위대! 과연 효과가 있을까?!",
  ui_story_5004_50041202_73_dialog_content = "말도 안 돼! 불덩이가 사람들 사이에서 폭발했어!\n마치 불타는 운석처럼 지면을 강타했잖아!",
  ui_story_5004_50041202_74_dialog_content = "불쌍한 제네비브와 친위대들... 이번 스파이크 한 방에 모두 퇴장했어!\n코트 중앙엔 폭발 때문에 커다란 구멍까지 났다고!",
  ui_story_5004_50041202_75_dialog_content = "승자는── PlayerName 팀입니다!",
  ui_story_5004_50041202_76_dialog_content = "강속구로 승리를 거머쥔 스모키! 검지를 하늘 높이 들면서 승리의 포즈!\n정말 멋진 스파이크였어!",
  ui_story_5004_50041202_77_dialog_content = "흥, 해설도 그런대로 나쁘지 않네. 내 대단함을 절반 정도는 표현해준 것 같아.",
  ui_story_5004_50041202_78_dialog_content = "칭찬 고마워...가 아니지! 해설이라면 선수가 아니라\n경기장 바깥에다 부탁했어야지!",
  ui_story_5004_50041202_79_dialog_content = "뭐, 그건 그렇고... 너무 강하잖아! 순식간에 전멸시키다니...",
  ui_story_5004_50041202_80_dialog_content = "(이런 괴물을 넘어서려고 하는 건가...\n갑자기 제네비브가 불쌍하게 느껴지는걸...)",
  ui_story_5004_50041301_1_dialog_content = "하아... 힘들었어!",
  ui_story_5004_50041301_2_dialog_content = "아무 도움도 안 됐지만, 뛰어다니면서\n공을 피하는 것만으로도 이미 지쳤다고...",
  ui_story_5004_50041301_3_dialog_content = "첫날부터 이런 치열한 경기가 벌어질 줄이야...",
  ui_story_5004_50041301_4_dialog_content = "제네비브도 강하긴 했지만, 스모키는 정말 차원이 다르잖아...",
  ui_story_5004_50041301_5_dialog_content = "둘 사이에 대체 어떤 원한이 있는 거지?",
  ui_story_5004_50041301_6_dialog_content = "베릴이랑 라파엘은 또 낚시를 하러 간 모양이네...\n둘이 같이 잘 노는 것 같아서 정말 다행이야.",
  ui_story_5004_50041301_7_dialog_content = "베릴이 어제 좀 피곤해 보이긴 했지만...\n라파엘이 옆에 있으니까 별문제 없겠지.",
  ui_story_5004_50041301_8_dialog_content = "맞다! 나 대신 공을 막아준 바이스한테 고맙다고 해야 되는데...",
  ui_story_5004_50041301_9_dialog_content = "바이스가 없었다면 난 아직도 바다에서 표류 중일 수도 있었으니까...",
  ui_story_5004_50041301_10_dialog_content = "<color=#e8d9bb>똑똑똑.</color>",
  ui_story_5004_50041301_11_dialog_content = "PlayerName, 쉬고 있어?",
  ui_story_5004_50041301_12_dialog_content = "잠깐만, 금방 열어줄게.",
  ui_story_5004_50041301_13_dialog_content = "카렌? 무슨 일이야?",
  ui_story_5004_50041301_14_dialog_content = "음... 잘 쉬고 있나 한번 보러 왔어.",
  ui_story_5004_50041301_15_dialog_content = "모처럼 바다에 왔는데... 저녁이라고 방에 틀어박혀 있고 싶지도 않고 말이야.",
  ui_story_5004_50041301_16_dialog_content = "해변 산책하지 않을래?",
  ui_story_5004_50041301_17_dialog_content = "물론 좋지!",
  ui_story_5004_50041301_19_dialog_content = "그럼 가자.",
  ui_story_5004_50041301_20_dialog_content = "음...",
  ui_story_5004_50041301_21_dialog_content = "(뭔가... 좀 어색하네...)",
  ui_story_5004_50041301_22_dialog_content = "PlayerName.",
  ui_story_5004_50041301_23_dialog_content = "으, 응?!",
  ui_story_5004_50041301_24_dialog_content = "디바우러호와 슈모르의 일로... 너한테 제대로 고맙다는 인사를\n해야겠다고 계속 생각하고 있었어.",
  ui_story_5004_50041301_25_dialog_content = "아니야. 내가 한 것도 별로 없는걸.",
  ui_story_5004_50041301_26_dialog_content = "그리고 내가 카렌이나 바이스한테 도움을 받은 게 더 많잖아.",
  ui_story_5004_50041301_27_dialog_content = "음... 그 일들을 이런 멋진 해변에서 떠올리려니까...",
  ui_story_5004_50041301_28_dialog_content = "마치 그게 전부 꿈이었던 것처럼 실감이 잘 안 나. 그렇지?",
  ui_story_5004_50041301_29_dialog_content = "심지어 지금 이 순간조차 왠지 꿈속에 있는 게 아닐까 싶은 생각도 들어...",
  ui_story_5004_50041301_30_dialog_content = "처음 널 만났을 때, 난 네가 혼자서 십여 년을 살았다는 게 믿기질 않았어...",
  ui_story_5004_50041301_31_dialog_content = "아이테르를 만난 건 네가 처음이었고...\n너한텐 빛의 궤적이 보인다는 게 정말 신기했어.",
  ui_story_5004_50041301_32_dialog_content = "게다가 넌 어떤 위기 앞에서도 침착하게 자신을 증명했고,\n확실히 보통 사람에겐 없는 지휘의 재능을 가지고 있어.",
  ui_story_5004_50041301_33_dialog_content = "비록 암귀와 싸울 힘은 없지만, 놈들 앞에서도 움츠러들지 않았고 말이야.",
  ui_story_5004_50041301_34_dialog_content = "......",
  ui_story_5004_50041301_35_dialog_content = "심지어 모두를 위해 위험을 무릅쓸 용기도 있어.",
  ui_story_5004_50041301_36_dialog_content = "남을 위해 희생하는 정신은 보통 사람이 가질 수 없는 거야.\n목숨을 내놓을 용기는 말할 것도 없고.",
  ui_story_5004_50041301_37_dialog_content = "재난이 닥치기 전까지 자기 생각만 하고 멋대로 살아온 귀족들에 비하면,\n네가 보여준 용기는 훨씬 존경할 만하다고 생각해.",
  ui_story_5004_50041301_38_dialog_content = "......",
  ui_story_5004_50041301_39_dialog_content = "PlayerName? 듣고 있어?",
  ui_story_5004_50041301_40_dialog_content = "음... 내가 너무 말이 많았나...",
  ui_story_5004_50041301_41_dialog_content = "듣고 있어. 카렌이 한 말에 대해서 생각하고 있었어...\n이렇게 바닷바람을 느끼면서 너랑 이야기를 나눌 수 있어서 정말 기뻐.",
  ui_story_5004_50041301_42_dialog_content = "그리고 이곳의 모든 게...",
  ui_story_5004_50041301_43_dialog_content = "바다도... 밤하늘도...",
  ui_story_5004_50041301_44_dialog_content = "그리고...",
  ui_story_5004_50041301_45_dialog_content = "......",
  ui_story_5004_50041301_46_dialog_content = "...모든 게 정말 아름다워.",
  ui_story_5004_50041301_47_dialog_content = "......",
  ui_story_5004_50041301_48_dialog_content = "......",
  ui_story_5004_50041301_49_dialog_content = "(왠지 더 분위기가 어색해진 것 같은데...)",
  ui_story_5004_50041301_50_dialog_content = "그래! 백야성에선 절대로 볼 수 없는 경치니까.",
  ui_story_5004_50041301_51_dialog_content = "익숙한 밤하늘도 잔잔한 바다와 함께 펼쳐지니까\n평소와는 다른 웅장한 아름다움이 느껴지는 것 같아.",
  ui_story_5004_50041301_52_dialog_content = "(카렌은 어색함을 못 느낀 것 같네... 다행이야...)",
  ui_story_5004_50041301_53_dialog_content = "아, 맞다. 여긴 바다가 이렇게 깨끗하니까, 물고기도 엄청 맛있겠지?!",
  ui_story_5004_50041301_54_dialog_content = "잡아서 구워 먹어볼까!",
  ui_story_5004_50041301_55_dialog_content = "좋은 생각이야. 하지만 난 요리는 배워본 적 없는걸.",
  ui_story_5004_50041301_56_dialog_content = "대신 물고기를 잡아서 호텔로 가져가면,\n그 이상한 요리사가 요리를 해주지 않을까?",
  ui_story_5004_50041301_57_dialog_content = "아니면 백야성으로 가져가도 괜찮을 것 같아.\n마침 맛도 분위기도 흠잡을 데 없는 조용한 가게가 한 곳 있거든.",
  ui_story_5004_50041301_58_dialog_content = "좋아! 그럼 그렇게 하자.",
  ui_story_5004_50041301_59_dialog_content = "근데... 역시 지금은 좀 그렇겠지? 시간도 늦었고...\n바다에 들어가는 건 위험할 것 같아...",
  ui_story_5004_50041301_60_dialog_content = "게다가 오늘 비치발리볼 경기 때문에 카렌도 피곤하지 않아?",
  ui_story_5004_50041301_61_dialog_content = "그것도 그렇네. 그럼 다음에 잡자.",
  ui_story_5004_50041301_62_dialog_content = "어라...?",
  ui_story_5004_50041301_63_dialog_content = "왜 그래, PlayerName?",
  ui_story_5004_50041301_64_dialog_content = "잠깐만, 방금 저 멀리 있는 조각상이 번쩍거린 것 같은데?",
  ui_story_5004_50041301_65_dialog_content = "난 못 봤어... 피곤해서 잘못 본 거 아냐?",
  ui_story_5004_50041301_66_dialog_content = "아니면 스모키의 「폭☆염 슈퍼 스파이크」의 인상이 너무 강했나?",
  ui_story_5004_50041301_67_dialog_content = "그 이름을 아직도 기억하고 있었어?!",
  ui_story_5004_50041301_68_dialog_content = "뭐... 내가 잘못 본 거겠지...",
  ui_story_5004_50041301_69_dialog_content = "그럼 돌아가자.",
  ui_story_5004_50041301_70_dialog_content = "아이테르의 자손... 수정의 힘... 「그 장치」도 이제 가동됐어...",
  ui_story_5004_50041301_71_dialog_content = "스스로 루미나를 바치는 어리석은 오로리안들...",
  ui_story_5004_50041301_72_dialog_content = "그리고...",
  ui_story_5004_50041301_73_dialog_content = "베릴.",
  ui_story_5004_50041301_74_dialog_content = "드디어... 내가 움직일 차례가 됐어.",
  ui_story_5004_50041501_1_dialog_content = "<color=#e8d9bb>며칠 전</color>",
  ui_story_5004_50041501_2_dialog_content = "제길...!",
  ui_story_5004_50041501_3_dialog_content = "<color=#e8d9bb>스모키는 화가 난 듯 편지를 갈기갈기 찢어버렸다.</color>",
  ui_story_5004_50041501_4_dialog_content = "그 녀석한테 놀아난 건가...",
  ui_story_5004_50041501_5_dialog_content = "때, 때리지 마. 돈이라면 얼마든지 줄 테니까!",
  ui_story_5004_50041501_6_dialog_content = "하아? 그게 조금 전까지 여자애를 협박하던 녀석이 할 대사야?",
  ui_story_5004_50041501_7_dialog_content = "왜 그래? 어디 그 역겨운 얼굴로 다시 한번 나한테 돈을 뜯어보지 그래?",
  ui_story_5004_50041501_8_dialog_content = "겨우 이틀 정도 신경을 안 썼더니, 동네 분위기가 엉망이네.\n여기가 누구 영역인지도 모르는 거야?",
  ui_story_5004_50041501_9_dialog_content = "내가 여기 「여자를 괴롭히지 마라」는 규칙을 세웠는데,\n<size=45>너흰 날 바보로 아는 모양이지?</size>",
  ui_story_5004_50041501_10_dialog_content = "나, 난 이 지역 사람이 아니라고...\n한 번만 봐주면 다시는 얼씬도 안 할게!",
  ui_story_5004_50041501_11_dialog_content = "응? 여기 사람이 아니라고? 변명도 참 그럴싸하네.",
  ui_story_5004_50041501_12_dialog_content = "어디서 왔어? 뭘 하러 온 거야? 너희 두목은 누구고?\n30초 안에 다 얘기해.",
  ui_story_5004_50041501_13_dialog_content = "만족할 만한 답을 하면 용서해 줄게.",
  ui_story_5004_50041501_14_dialog_content = "만약 답이 마음에 안 든다면...",
  ui_story_5004_50041501_15_dialog_content = "30초마다 손가락을 한 개씩 부러트려 줄게. 알겠어?",
  ui_story_5004_50041501_16_dialog_content = "자, 첫 번째, 지금부터 센다. 30, 29...",
  ui_story_5004_50041501_17_dialog_content = "하, 한 번만 용서해 줘! 난 그저 시키는 대로 물건을 전하러 왔을 뿐이라고!",
  ui_story_5004_50041501_18_dialog_content = "정말 나쁜 짓을 할 생각은 없었어! 저 아가씨가\n너무 눈에 띄어서 그런 거지... 진짜야!",
  ui_story_5004_50041501_19_dialog_content = "그저 시키는 대로 물건만 전해준 거지 두목 같은 것도 없다고!",
  ui_story_5004_50041501_20_dialog_content = "10, 9, 8...",
  ui_story_5004_50041501_21_dialog_content = "이미 다 얘기했는데 또 무슨 얘기를 하라는 거야!",
  ui_story_5004_50041501_22_dialog_content = "우드득── 콰직──",
  ui_story_5004_50041501_23_dialog_content = "<size=45><anim type=Shake>끄아아아아악! 소, 손가락! 내 손가라아아아악!</anim></size>",
  ui_story_5004_50041501_24_dialog_content = "이, 이런 빌어먹을! 하, 하나씩이라면서 왜 두 개나 부러트린 거냐고!",
  ui_story_5004_50041501_25_dialog_content = "사, 사람 살려! 여기 미친 여자가 있어!",
  ui_story_5004_50041501_26_dialog_content = "하나는 시간 초과라서, 다른 하나는 태도가 불성실해서.",
  ui_story_5004_50041501_27_dialog_content = "빌어먹을... 난... 진짜로 물건만 전해주러 온 거라고...",
  ui_story_5004_50041501_28_dialog_content = "꺼내 봐.",
  ui_story_5004_50041501_29_dialog_content = "안 돼!",
  ui_story_5004_50041501_30_dialog_content = "응? 세 번째 손가락이 부러질 시간도 얼마 안 남았어. 5, 4...",
  ui_story_5004_50041501_31_dialog_content = "저, 정말 안 된다고! 놈들이 날 죽일 거야!",
  ui_story_5004_50041501_32_dialog_content = "0",
  ui_story_5004_50041501_33_dialog_content = "<size=45><anim type=Shake>끄아아아!</anim></size> 끄윽... 흐어억...",
  ui_story_5004_50041501_34_dialog_content = "그럼 난 널 안 죽일 것 같아?",
  ui_story_5004_50041501_35_dialog_content = "지금 죽든지, 나중에 죽든지, 알아서 생각해.",
  ui_story_5004_50041501_36_dialog_content = "아, 알았어! 알았으니까! 좀 놔 줘!",
  ui_story_5004_50041501_37_dialog_content = "자, 줄 테니까! 이런 젠장할...",
  ui_story_5004_50041501_38_dialog_content = "에? 편지? 무슨 내용인데?",
  ui_story_5004_50041501_39_dialog_content = "아, 아니지... 역시 안 되겠어. 지금 당장 돌려줘...\n그건 아주 중요한 사람한테 전할 물건이야. 그걸 네가 가져가면\n나만 죽는 게 아니라 너도 무사하진 못할 거라고!",
  ui_story_5004_50041501_40_dialog_content = "이미 늦었어.",
  ui_story_5004_50041501_41_dialog_content = "그런 대단한 사람한테 보낼 물건이라면, 뭔지 더 궁금해지는걸.",
  ui_story_5004_50041501_42_dialog_content = "뭐야, 이게... 「헤븐즈 비치」...?",
  ui_story_5004_50041501_43_dialog_content = "이건 뭘 그린 거야... 보물지도인가?",
  ui_story_5004_50041501_44_dialog_content = "누가 벌써 뜯으래?! 이제 우린 다 죽었다고!",
  ui_story_5004_50041501_45_dialog_content = "<size=45>지금 이게 뭐냐고 묻잖아──</size>",
  ui_story_5004_50041501_46_dialog_content = "나, 나도 몰라. 내가 아는 건 그저 그놈들이 무척 위험한 자들이라는 것뿐이야!",
  ui_story_5004_50041501_47_dialog_content = "무슨 수상한 의식 같은 걸 준비한다고 했어.\n세상을 멸망시키는 재앙을 일으키겠다면서 말이야!",
  ui_story_5004_50041501_48_dialog_content = "얼른 돌려줘! 난 이 일에 휘말리고 싶지 않다고!",
  ui_story_5004_50041501_49_dialog_content = "하아? 아무래도 아까 덜 맞은 모양이지?",
  ui_story_5004_50041501_50_dialog_content = "계속 헛소리만 하고 있어.",
  ui_story_5004_50041501_51_dialog_content = "네가 무슨 말을 하든 내가 속을 것 같아?",
  ui_story_5004_50041501_52_dialog_content = "그럼 당연히 확인하러 가 봐야지!",
  ui_story_5004_50041501_53_dialog_content = "<color=#e8d9bb>편지에는 이렇게 적혀 있었다──</color>",
  ui_story_5004_50041501_54_dialog_content = "<color=#e8d9bb>내가 원하는 것은 세 가지 탄식의 벽</color>",
  ui_story_5004_50041501_55_dialog_content = "<color=#e8d9bb>내가 찾는 것은 잿더미로부터의 부활</color>",
  ui_story_5004_50041501_56_dialog_content = "<color=#e8d9bb>여명 속에서 피의 비가 내리면</color>",
  ui_story_5004_50041501_57_dialog_content = "<color=#e8d9bb>석양에 물들어 슬피 울지니</color>",
  ui_story_5004_50041501_58_dialog_content = "<color=#e8d9bb>심판과 종말이 찾아오는 그 끝에</color>",
  ui_story_5004_50041501_59_dialog_content = "<color=#e8d9bb>왕이 깨어나리라</color>",
  ui_story_5004_50041501_60_dialog_content = "이건 또 무슨 개뼈다귀 같은 소리야... 수수께끼도 아니고...",
  ui_story_5004_50041501_61_dialog_content = "설마 정말 헛걸음한 건가...",
  ui_story_5004_50041501_62_dialog_content = "<color=#e8d9bb>똑똑똑.</color>",
  ui_story_5004_50041501_63_dialog_content = "들어와.",
  ui_story_5004_50041501_64_dialog_content = "실례합니다. 혹시 움브라톤의 스모키 만티코어 씨가 맞나요?",
  ui_story_5004_50041501_65_dialog_content = "...날 알아?",
  ui_story_5004_50041501_66_dialog_content = "물론이죠. 당신이 여기에 온 이유도,\n당신 것이 아닌 편지를 받은 사실도 알고 있어요.",
  ui_story_5004_50041501_67_dialog_content = "말해, 무슨 수작인지.",
  ui_story_5004_50041501_68_dialog_content = "풉... 우후후훗~",
  ui_story_5004_50041501_69_dialog_content = "...?",
  ui_story_5004_50041501_70_dialog_content = "아, 제가 추태를 보였네요... 말씀이 너무 재미있어서요.",
  ui_story_5004_50041501_71_dialog_content = "수작 같은 건 없어요. 저는 이번 「해신제」의 주최자로서\n스모키 씨를 초대하러 왔을 뿐이에요.",
  ui_story_5004_50041501_72_dialog_content = "그게 다야?",
  ui_story_5004_50041501_73_dialog_content = "그게 다예요.",
  ui_story_5004_50041501_74_dialog_content = "너, 진리의 결사 쪽 사람이지? 난 너희 같은 녀석들 안 믿어.",
  ui_story_5004_50041501_75_dialog_content = "비록 진리의 결사 소속이라 해도, 가끔씩 의식이나 행사의 주최자를 맡는\n취미 정도는 가질 수 있잖아요.",
  ui_story_5004_50041501_76_dialog_content = "진리를 추구하기 위해서도 물질적인 조건이 충족돼야만 해요.\n이번 일은 꽤 많은 보수를 지급하거든요.",
  ui_story_5004_50041501_77_dialog_content = "그럼... 참가하시겠어요? 당신이 추구하는 것도\n어쩌면 우승 상품 중에 있을지도 몰라요.",
  ui_story_5004_50041501_78_dialog_content = "비록 지더라도...",
  ui_story_5004_50041501_79_dialog_content = "그만, 나머지는 말할 필요 없어. 난 지지 않으니까.\n지면 어떻게 되는지 같은 건 관심 없다고.",
  ui_story_5004_50041501_80_dialog_content = "그 심부름꾼은 너희 패거리야?",
  ui_story_5004_50041501_81_dialog_content = "어머, 제가 그런 사람을 어떻게 알겠어요~",
  ui_story_5004_50041501_82_dialog_content = "흥. 여기까지 왔는데 피할 것도 없겠지.",
  ui_story_5004_50041501_83_dialog_content = "그럼 어디 나한테 무슨 꿍꿍이인지 두고 보겠어.",
  ui_story_5004_50041601_1_dialog_content = "그러니까... 베릴의 상태가 안 좋은 건\n몸 안의 루미나가 불안정한 게 원인이라는 얘기야?",
  ui_story_5004_50041601_2_dialog_content = "맞아. 지난 며칠 동안 내 조수 베르타한테 연락해서\n비슷한 증상에 대해 조사를 부탁했거든.",
  ui_story_5004_50041601_3_dialog_content = "그리고 「고티에」 가문에 관한 문서도 찾을 수 있었어...",
  ui_story_5004_50041601_4_dialog_content = "하지만 기밀 문서고는 관리가 엄격해서 성주님과 소수의 사람만\n그 안의 문서를 열람할 수 있어.",
  ui_story_5004_50041601_5_dialog_content = "「고티에」... 그게 베릴의 성이야?",
  ui_story_5004_50041601_6_dialog_content = "응! 어제 둘이 얘기하다가 베릴이 자기 가문에 대해 말해줬거든.\n그리고 다른 무슨 가문 얘기도 했었는데...",
  ui_story_5004_50041601_7_dialog_content = "음... 피로스라고 했었나... 기억이 잘 안 나네.",
  ui_story_5004_50041601_8_dialog_content = "응... 무리하지 않아도 돼. 그나저나 둘이 참 많이 친해진 것 같네.",
  ui_story_5004_50041601_9_dialog_content = "당연하지. 여자애들끼린 이야기가 끝이 없으니까~\n그리고 베릴은 네가 생각하는 것보다 훨씬 말을 잘하거든.",
  ui_story_5004_50041601_10_dialog_content = "그렇구나... 아무튼 베릴 일은 신경 써 줘서 고마워. 나머지도 부탁할게.",
  ui_story_5004_50041601_11_dialog_content = "맡겨줘~ 카렌 언니랑 얘기해보고 새로운 정보가 생기면 바로 말해줄게~",
  ui_story_5004_50041601_12_dialog_content = "그럼 난 베릴한테 가볼 테니까! 이따 경기장에서 봐!",
  ui_story_5004_50041601_13_dialog_content = "응, 이따가 봐.",
  ui_story_5004_50041601_14_dialog_content = "우와앗──!",
  ui_story_5004_50041601_15_dialog_content = "뭐야, 괜찮아?",
  ui_story_5004_50041601_16_dialog_content = "괘, 괜찮아! 미안!",
  ui_story_5004_50041601_17_dialog_content = "어라? 스모키, 네가 여긴 무슨 일이야?",
  ui_story_5004_50041601_18_dialog_content = "PlayerName, 맞지? 정식으로 인사하고 싶어.",
  ui_story_5004_50041601_19_dialog_content = "난 스모키야. 움브라톤에서 왔어.",
  ui_story_5004_50041601_20_dialog_content = "......",
  ui_story_5004_50041601_21_dialog_content = "......",
  ui_story_5004_50041601_22_dialog_content = "끝이야?",
  ui_story_5004_50041601_23_dialog_content = "그래.",
  ui_story_5004_50041601_24_dialog_content = "아... 그래서, 나한테 무슨 볼일인데?",
  ui_story_5004_50041601_25_dialog_content = "같은 팀의 동료가 된 이상, 인사라도 제대로 해야지 싶었거든.",
  ui_story_5004_50041601_26_dialog_content = "지난번 경기를 보고 나니까, 나 혼자만으론\n곤란한 상황이 생길 수도 있겠다는 생각이 들었어.",
  ui_story_5004_50041601_27_dialog_content = "(...네가 곤란해질 정도면 대체 어떤 상황인 거냐고...)",
  ui_story_5004_50041601_28_dialog_content = "그러니까 앞으로 잘 지내보자는 얘기야.",
  ui_story_5004_50041601_29_dialog_content = "아무튼 같이 힘내보자고. 이따 봐.",
  ui_story_5004_50041601_30_dialog_content = "잠깐만.",
  ui_story_5004_50041601_31_dialog_content = "응? 또 뭐 있어?",
  ui_story_5004_50041601_32_dialog_content = "물어보고 싶은 게 있는데... 너랑 제네비브는 대체 어떤 사이야?",
  ui_story_5004_50041601_33_dialog_content = "...그 얘기일 줄 알았다니까.",
  ui_story_5004_50041601_34_dialog_content = "근데 내 대답을 들어도 네가 만족할진 잘 모르겠네.",
  ui_story_5004_50041601_35_dialog_content = "우린 둘 다 페테르부르크 출신이야. 나는 만티코어 가문, 그 애는 브론스키 가문 사람이고.",
  ui_story_5004_50041601_36_dialog_content = "음, 뭐랄까. 두 가문은 쭉 사이가 별로였거든.\n그래도 우리 둘이는 어렸을 때 그런대로 친했어.",
  ui_story_5004_50041601_37_dialog_content = "그땐 그 녀석, 꽤 귀여웠어. 날 졸졸 따라다녔고.\n지금보다 더 사람들한테 사랑받는 애였어.",
  ui_story_5004_50041601_38_dialog_content = "하지만 그때 난 아직 어렸고, 성격도 반항적인 데다가 자극을 즐겼거든.",
  ui_story_5004_50041601_39_dialog_content = "한번은 제네비브도 참가했던 어느 시험에서 살짝 실력 발휘를 좀 해봤어.",
  ui_story_5004_50041601_X39_dialog_content = "근데 그게 시험관 마음에 들었던 모양이야.\n그래서 그 애는 백야성의 유력 귀족과 협력할 기회를 잃고 말았어.",
  ui_story_5004_50041601_40_dialog_content = "그 애도, 그 애의 가문도 그걸 무척 수치스럽게 여겼던 것 같아.",
  ui_story_5004_50041601_41_dialog_content = "하지만 난 그냥 재미를 좀 느끼고 싶었을 뿐이고,\n그 사람들이 그렇게까지 약할 줄은 몰랐다고.",
  ui_story_5004_50041601_42_dialog_content = "그래서 난 귀족이니 뭐니 그런 게 정말 귀찮다니까.\n그리고 그 뒤로 난 집을 떠났어.",
  ui_story_5004_50041601_43_dialog_content = "그런 일이 있었구나...",
  ui_story_5004_50041601_44_dialog_content = "이제 됐지? 갈게. 그럼 오후 경기도 잘해보자고.",
  ui_story_5004_50041701_1_dialog_content = "휴...",
  ui_story_5004_50041701_2_dialog_content = "PlayerName, 긴장했어?",
  ui_story_5004_50041701_3_dialog_content = "조금...",
  ui_story_5004_50041701_4_dialog_content = "자, 마음 편히 가져. 히이로 님이 이런 말씀을 해주신 적 있어.\n<color=#FFB400>차가 오면 장군이 막고, 물이 오면 돌로 막는다</color>고 말이야.",
  ui_story_5004_50041701_5_dialog_content = "그거 <color=#FFB400>「병사가 오면 장군이 막고, 물이 오면 흙으로 막는다」</color> 아냐?",
  ui_story_5004_50041701_6_dialog_content = "아, 맞아, 그거야! 난 지금까지 히이로 님이\n레디젤 렌치의 차를 전복시켰다는 뜻인가 싶었거든...",
  ui_story_5004_50041701_7_dialog_content = "(히이로 씨가 들었으면 지금 그 말을 100번 베껴 쓰라고 했을걸!)",
  ui_story_5004_50041701_8_dialog_content = "오늘은 달의 고치를 가지고 왔으니까, 돌격은 내게 맡겨.",
  ui_story_5004_50041701_9_dialog_content = "그럼 난 장외에서 미사일을 쏘고 엄호할게!",
  ui_story_5004_50041701_10_dialog_content = "안 돼! 아무리 전투 위주의 경기라고 해도 기본적인 룰은 지켜야 돼.",
  ui_story_5004_50041701_11_dialog_content = "라파엘의 미사일은... 아껴뒀다가 암귀한테 쓰는 게 좋을 것 같아.",
  ui_story_5004_50041701_12_dialog_content = "넌 백야성의... 천사니까.",
  ui_story_5004_50041701_13_dialog_content = "음~ 그것도 그렇네. 난 베릴도 지켜줘야 하니까!",
  ui_story_5004_50041701_14_dialog_content = "그럼 베릴이랑 같이 응원할게!",
  ui_story_5004_50041701_15_dialog_content = "참, 바이스 너는 수비 포지션이니까, 화살을 쓰면 안 될 거야.",
  ui_story_5004_50041701_16_dialog_content = "맞아. 그래서 대비 차원에서 베릴한테 수정으로\n활에 붙일 수 있는 쌍검을 만들어달라고 했어.",
  ui_story_5004_50041701_17_dialog_content = "계속 만들어 봤는데... 오늘 아침에 겨우 마음에 드는 결과물이 나왔어...",
  ui_story_5004_50041701_18_dialog_content = "도움이 됐으면 좋겠어...",
  ui_story_5004_50041701_19_dialog_content = "무척 튼튼하고 날카로운 것 같아. 베릴이 정성껏 만들었다는 게 느껴져.",
  ui_story_5004_50041701_20_dialog_content = "(베릴은 정말 착한 애구나...)",
  ui_story_5004_50041701_21_dialog_content = "고마워. 그럼 이제 우리의 승리를 지켜봐 줘!",
  ui_story_5004_50041701_22_dialog_content = "응, 바이스. 아주 든든해 보여! 기운도 넘치고 말이야!",
  ui_story_5004_50041701_23_dialog_content = "(근데 궁수가 쌍검을 써도... 정말 괜찮은 건가?)",
  ui_story_5004_50041701_24_dialog_content = "아무래도 격렬한 싸움이 될지도 모르겠어. 비록 체스일 뿐이지만...",
  ui_story_5004_50041701_25_dialog_content = "...그냥 체스로 끝나면 다행이겠지만, 스모키나 제네비브는\n쉽게 패배를 인정하지 않는 타입이야.",
  ui_story_5004_50041701_26_dialog_content = "만반의 준비를 해둘 필요가 있어.",
  ui_story_5004_50041701_27_dialog_content = "흠흠, 아무래도 모두 준비가 끝나신 모양이네요.",
  ui_story_5004_50041701_28_dialog_content = "자, 그럼 모두 정숙해 주세요──",
  ui_story_5004_50041701_29_dialog_content = "여러분도 아시다시피, 대륙에서 널리 사랑받는 체스는\n이곳에서 처음 시작되었다고 알려져 있어요.",
  ui_story_5004_50041701_30_dialog_content = "오래전 이곳에는 현명하고 자애로운 왕이 있었답니다.\n그는 자신의 백성들도 그와 같은 지혜를 얻을 수 있기를 원했어요.",
  ui_story_5004_50041701_31_dialog_content = "그래서 직접 발명한 이 놀이를 통해 백성들이\n판단력과 전술적 능력을 단련하게 했죠.",
  ui_story_5004_50041701_32_dialog_content = "이를 통해 왕은 암귀들조차 두려워할 만한 강력한 군대를 양성했고,\n나라를 침략으로부터 지켜내 백성들이 평화롭게 살 수 있었습니다.",
  ui_story_5004_50041701_33_dialog_content = "하지만 그것도 이미 오래전의 이야기가 되었죠.",
  ui_story_5004_50041701_34_dialog_content = "오늘은 바로 그 왕을 기념하기 위해,\n인간 체스의 방식으로 두 번째 경기를 진행하려 해요.",
  ui_story_5004_50041701_35_dialog_content = "자, 그럼 지혜와 결단력을 상징하는 체스 경기를 지금부터 시작합니다!",
  ui_story_5004_50041701_36_dialog_content = "PlayerName!",
  ui_story_5004_50041701_37_dialog_content = "응!",
  ui_story_5004_50041701_38_dialog_content = "정신 바짝 차려. 지휘는 너한테 맡길 테니까,\n우리가 전력을 다해 승리를 선물할게.",
  ui_story_5004_50041701_39_dialog_content = "(정신 바짝 차리자. 난 할 수 있어. 체스 같은 건 바튼 씨랑도 자주 했었잖아.)",
  ui_story_5004_50041701_40_dialog_content = "(그때를 떠올려 보자... 바튼 씨랑 게임을 했을 때...)",
  ui_story_5004_50041701_41_dialog_content = "우리가 승리한 이유는 <color=#FFB400>「장군들이 우리를 위해 노선을 개척해뒀기 때문이다」</color>.",
  ui_story_5004_50041701_42_dialog_content = "생각났어...!",
  ui_story_5004_50041701_43_dialog_content = "바튼 씨, 지켜봐 줘... 내가 대장으로서 앞장서는 모습을!",
  ui_story_5004_50041701_44_dialog_content = "내 턴이다!",
  ui_story_5004_50041701_45_dialog_content = "킹, 앞으로 1칸!",
  ui_story_5004_50041701_46_dialog_content = "......",
  ui_story_5004_50041701_47_dialog_content = "야, PlayerName... 나도 체스 같은 건 젬병이긴 한데.",
  ui_story_5004_50041701_48_dialog_content = "네가 나서면 안 된다는 것 정도는 안다고.\n말에 올라탈 생각이 아니라면 말이지.",
  ui_story_5004_50041701_49_dialog_content = "후후훗──",
  ui_story_5004_50041701_50_dialog_content = "거기 아이테르, 당신들 종족이 전술과 지휘에 능하다는 건 알고 있어.",
  ui_story_5004_50041701_51_dialog_content = "하지만 체스처럼 품위 있는 종목에 대해선 전혀 아는 게 없어 보이네.",
  ui_story_5004_50041701_52_dialog_content = "이번엔 네 동료 오로리안들한테 전력이 뒤질 순 없으니까,\n이쪽도 강력한 <color=#FFB400>용사</color>를 초빙해 왔다고!",
  ui_story_5004_50041701_53_dialog_content = "쳇, 이 여자 말도 참 많네. 정체는 밝히지 않겠다고 약속했잖아.",
  ui_story_5004_50041701_54_dialog_content = "보스, 보스! 이러시면 계약 제3조 제9항을 위반하시는 거라고요.",
  ui_story_5004_50041701_55_dialog_content = "계약 내용에 따라 보수의 135%를 추가로 지급하셔야 돼요.",
  ui_story_5004_50041701_56_dialog_content = "시끄러워. 돈은 제대로 줄 테니까... 어서 가!",
  ui_story_5004_50041701_57_dialog_content = "PlayerName! 나와 감응해 줘. 내가 지휘를 도와줄게!",
  ui_story_5004_50041701_58_dialog_content = "응, 부탁할게!",
  ui_story_5004_50041701_59_dialog_content = "흐아압──!",
  ui_story_5004_50041701_60_dialog_content = "으윽! 이 녀석... 엄청난 실력이야...\n히이로 님 못지않게 강한 것 같잖아...",
  ui_story_5004_50041701_61_dialog_content = "게다가 이 검술... 설마...?!",
  ui_story_5004_50041701_62_dialog_content = "하하... 어차피 들킨 것 같으니까, 그럼 더는 숨길 필요도 없겠군.",
  ui_story_5004_50041701_63_dialog_content = "타키 씨!",
  ui_story_5004_50041701_64_dialog_content = "타키 씨?!",
  ui_story_5004_50041701_65_dialog_content = "여긴 어쩐 일이죠?",
  ui_story_5004_50041701_66_dialog_content = "미안하게 됐어... 흥신소라는 건 말이지.\n도의에 어긋나는 일만 아니라면 무슨 의뢰든 가리지 않거든!",
  ui_story_5004_50041701_67_dialog_content = "뭐, 어차피 그냥 시합일 뿐이잖아? 그러니 봐주는 일은 없을 거다!",
  ui_story_5004_50041701_68_dialog_content = "PlayerName, 어서 항복하지 그래? 힘도 없는 네 녀석을\n다치게 하고 싶진 않으니 말이야!",
  ui_story_5004_50041701_69_dialog_content = "타, 타키 씨, 정체를 들키면 앞으로의 제 사업에 곤란하다고요!",
  ui_story_5004_50041701_70_dialog_content = "허점이다──!",
  ui_story_5004_50041701_71_dialog_content = "어이쿠!",
  ui_story_5004_50041701_72_dialog_content = "카렌, 살살 해! 저러다 코코넛 밀크가 쏟아져 나오겠어!",
  ui_story_5004_50041701_72X1_dialog_content = "무슨 소리야? 저건 그냥 가면이지 진짜 코코넛이 아니라고.",
  ui_story_5004_50041701_72X2_dialog_content = "아... 그렇네. 뭐야, 진짜랑 너무 똑같이 생겼잖아!",
  ui_story_5004_50041701_73_dialog_content = "조무... 너인 거 다 안다고.",
  ui_story_5004_50041701_74_dialog_content = "보스, 제 말 좀 들어보세요. 이번 의뢰는 조무...\n아, 아니 제가... <color=#FFB400>보스</color>를 위해서 받은 거라고요.",
  ui_story_5004_50041701_75_dialog_content = "뭐? 날 위해서?",
  ui_story_5004_50041701_76_dialog_content = "그래요! 이번에 제네비브 씨한테서 상금을 받으면 제 사업을 더 확장할 수 있겠죠.",
  ui_story_5004_50041701_77_dialog_content = "그럼 앞으로 <color=#FFB400>라피스</color> 같은 것도\n저한테서 나이티움으로 사실 수 있을지도 몰라요.",
  ui_story_5004_50041701_78_dialog_content = "그러면 제가 특별히... 0.5% 할인해 드릴게요.\n그리고 당월 한정판 <color=#FFB400>굿즈 상자</color>도 하나 드리고요.",
  ui_story_5004_50041701_79_dialog_content = "PlayerName, 저기 <color=#FFFFFF>가면</color>을 쓰고 있는 녀석들도 수상해...!",
  ui_story_5004_50041701_80_dialog_content = "일단 저 녀석들의 가면부터 벗겨버리자!",
  ui_story_5004_50041701_81_dialog_content = "알겠어! 바이스, 카렌, 부탁할게!",
  ui_story_5004_50041701_82_dialog_content = "뭐, 뭐야?! 톱에 오일이 다 떨어졌어! 나, 난 먼저 갈게!",
  ui_story_5004_50041701_83_dialog_content = "나, 나도 여기까지다! 그럼 이만!",
  ui_story_5004_50041701_84_dialog_content = "짹짹!",
  ui_story_5004_50041701_85_dialog_content = "쳇. 역시 믿을 수 없는 녀석들이었어.",
  ui_story_5004_50041701_86_dialog_content = "어머, 아무래도 경기가 교착 상태에 빠진 것 같네요.",
  ui_story_5004_50041701_87_dialog_content = "한쪽은 말들이 달아나버렸고, 다른 한쪽은 곧 체크메이트가 될 것 같네요.",
  ui_story_5004_50041701_88_dialog_content = "어이, 얼른 날 움직여!",
  ui_story_5004_50041701_89_dialog_content = "끝까지 가서 승진시키든, 곧장 전진시켜서 체크메이트를 노리든지 하라고.\n날 제네비브한테 접근시키면 내가 녀석을 쓰러트릴 수 있어!",
  ui_story_5004_50041701_90_dialog_content = "뭐? 그러면 안 되는 거 아냐? 지금 상황이라면 카렌을 다시 데려와서\n바이스를 지키게 하고, 재정비한 뒤에 공격하는 게 좋잖아?",
  ui_story_5004_50041701_91_dialog_content = "그럴 시간 없어. 상대 쪽의 기세가 꺾여 있는 지금이 기회야.\n지금 네 여친을 구하러 가는 게 중요한 게 아니라고.",
  ui_story_5004_50041701_92_dialog_content = "뭐? 여친? 우, 우린 그런 사이...",
  ui_story_5004_50041701_93_dialog_content = "내 말대로 해! 그럼 이길 수 있으니까!",
  ui_story_5004_50041701_94_dialog_content = "아, 알겠어!",
  ui_story_5004_50041701_95_dialog_content = "제네비브!",
  ui_story_5004_50041701_96_dialog_content = "스모키! 덤벼 보시지!",
  ui_story_5004_50041701_97_dialog_content = "이야압!",
  ui_story_5004_50041701_98_dialog_content = "시작부터 필살기야?!",
  ui_story_5004_50041701_99_dialog_content = "흥──",
  ui_story_5004_50041701_100_dialog_content = "막아냈어?! 저 녀석, 격투 실력까지 저런 수준이었단 말이야?!",
  ui_story_5004_50041701_101_dialog_content = "저번엔 잠깐 방심했을 뿐이야. 네가 매번 이길 수 있다고 생각했다면 오산이야!",
  ui_story_5004_50041701_102_dialog_content = "확실히 전보다 세지긴 했네. 그래도 아직 멀었다고!",
  ui_story_5004_50041701_103_dialog_content = "안 돼... 너무 팽팽해서 승부가 안 나.\n이대로면 튀는 불꽃에 경기장이 전부 타버리고 말 거야!",
  ui_story_5004_50041701_104_dialog_content = "저기, 여러분? 이대로 계속 승부가 나지 않으면 제한 시간을 초과할 거예요.",
  ui_story_5004_50041701_105_dialog_content = "어쩔 수 없네요. 그럼 이런 때를 위해 준비한 룰을 적용할 수밖에요.",
  ui_story_5004_50041701_106_dialog_content = "지금부터 새로운 경기 방식을 도입하겠어요!",
  ui_story_5004_50041701_107_dialog_content = "제가 미리 경기장 중앙에 「크리스탈 킹」이라는 특수한 체스말을 준비했어요.",
  ui_story_5004_50041701_108_dialog_content = "양팀의 「킹」 중에 먼저 그 「크리스탈 킹」을 차지하는 쪽이 승리합니다!",
  ui_story_5004_50041701_109_dialog_content = "그렇다면 이 방법밖에 없겠어... 친위대!",
  ui_story_5004_50041701_110_dialog_content = "공격 개시!",
  ui_story_5004_50041701_111_dialog_content = "제네비브 님을 위하여!",
  ui_story_5004_50041701_112_dialog_content = "쳇, 저 녀석들, 어디 갔나 했는데, 아직도 데리고 있었네.",
  ui_story_5004_50041701_113_dialog_content = "뭐, 뭐야?! 잠깐만, 뭐가 어떻게 된 건데? 갑자기 웬 물총이야?!\n저 친위대는 또 왜 끼어드는 거냐고!",
  ui_story_5004_50041701_114_dialog_content = "역시나 제가 새로 보내드린 매뉴얼도 안 읽으신 모양이네요.",
  ui_story_5004_50041701_115_dialog_content = "광고가 2배로 늘었는데 읽겠냐고!",
  ui_story_5004_50041701_116_dialog_content = "지난 경기가 주목을 받아서 광고주가 늘었거든요.",
  ui_story_5004_50041701_117_dialog_content = "아까 싸움은 제네비브 씨가 시간 내에 움직이지 않아서 무승부 처리됐어요.",
  ui_story_5004_50041701_118_dialog_content = "지금부터는 추가 경기인 물총 난투 시간이에요.\n오직 물총만 사용해서 경기를 진행해야 해요!",
  ui_story_5004_50041701_119_dialog_content = "그러니까 말이죠, PlayerName 씨. 싸우기 전에 항상 옆에서\n읽어주는 「전투 수첩」만 들어가지고는 성장할 수 없다니까요.",
  ui_story_5004_50041701_120_dialog_content = "멀쩡하던 경기가 갑자기 물총 싸움으로 변했는데 누가 적응하겠냐고!",
  ui_story_5004_50041701_121_dialog_content = "게다가 우린 물총도 없잖아...",
  ui_story_5004_50041701_122_dialog_content = "어라? 너희 그거 다 어디서 났어?",
  ui_story_5004_50041701_123_dialog_content = "바이스, 엄폐물에 숨어 반격해!",
  ui_story_5004_50041701_124_dialog_content = "응! PlayerName도 빨리 숨어!",
  ui_story_5004_50041701_125_dialog_content = "나, 난 무기가 없다고!",
  ui_story_5004_50041701_126_dialog_content = "PlayerName! 받아!",
  ui_story_5004_50041701_127_dialog_content = "베릴! 대단해!",
  ui_story_5004_50041701_128_dialog_content = "꿈 깨시지!",
  ui_story_5004_50041701_129_dialog_content = "으윽!",
  ui_story_5004_50041701_130_dialog_content = "뭐, 뭐야! 진짜 너무하네! 아, 아니지, 스모키, 뭔가 방법을...!",
  ui_story_5004_50041701_131_dialog_content = "아무래도 내 방식을 보여주는 수밖에 없겠어!",
  ui_story_5004_50041701_132_dialog_content = "그런 <color=#FFB400>초대형 물총</color> 같은 건 또 어디서 가져온 거야?!",
  ui_story_5004_50041701_133_dialog_content = "피라미 자식들, 수만 많다고 이길 줄 알았냐!",
  ui_story_5004_50041701_134_dialog_content = "제길! 제네비브 님을 지켜라!",
  ui_story_5004_50041701_135_dialog_content = "나, 난 여기까지야... 대장...",
  ui_story_5004_50041701_136_dialog_content = "으아아악──!",
  ui_story_5004_50041701_136X1_dialog_content = "내 부하한테 손을 대다니, 정말 겁도 없네.",
  ui_story_5004_50041701_136X2_dialog_content = "그럼 나도 봐주지 않겠어!",
  ui_story_5004_50041701_136X3_dialog_content = "으윽! 눈을 못 뜨겠어!",
  ui_story_5004_50041701_136X4_dialog_content = "바이스, 어서 철수해. 내가 엄호할게.",
  ui_story_5004_50041701_136X5_dialog_content = "이 「로즈 헌터」의 위력을 보여주마!",
  ui_story_5004_50041701_136X6_dialog_content = "받아라──!",
  ui_story_5004_50041701_136X7_dialog_content = "앗! 나, 나도... 아무것도 안 보여!",
  ui_story_5004_50041701_136X8_dialog_content = "지금은 바닷속도 아니잖아! 카렌, 넌 할 수 있어!",
  ui_story_5004_50041701_136X9_dialog_content = "게다가 너흰 둘 다 물의 루미나를 다루면서, 왜 물총 따위에 당하는 건데?!",
  ui_story_5004_50041701_136X10_dialog_content = "우후훗! 젖은 생쥐 꼴이 되기 싫다면 어서 항복해!",
  ui_story_5004_50041701_136X11_dialog_content = "웃음소리가 너무 크다는 생각 안 들어?!",
  ui_story_5004_50041701_136X12_dialog_content = "스모키?! 역시 친위대들만으론 널 막을 수 없는 건가...",
  ui_story_5004_50041701_136X13_dialog_content = "다들 스모키를 집중적으로 견제해!\n난 이 두 녀석부터 처리할 테니까!",
  ui_story_5004_50041701_138_dialog_content = "예! 화력 집중 개시!",
  ui_story_5004_50041701_139_dialog_content = "와아아아아──!",
  ui_story_5004_50041701_140_dialog_content = "쳇! 이래서는 조준을 할 수가 없잖아!",
  ui_story_5004_50041701_141_dialog_content = "스모키가 당하고 말겠어! 렉커! 무슨 방법 없어?!",
  ui_story_5004_50041701_142_dialog_content = "제길, 내가 뭘 할 수 있겠어? 너도 안 읽은 매뉴얼을 내가 읽었겠냐고!",
  ui_story_5004_50041701_143_dialog_content = "아무 준비도 못 했단 말이야! 이렇게 된 이상 주먹으로 가는 수밖에!",
  ui_story_5004_50041701_144_dialog_content = "렉커, PlayerName, 내가 주머니에서 뭘 발견했는지 좀 봐!",
  ui_story_5004_50041701_145_dialog_content = "방수, 방진에 보온 기능까지 있는 <color=#FFB400>캠핑 텐트</color>야! 일단 숨어서 좀 쉬자.",
  ui_story_5004_50041701_146_dialog_content = "누가 너랑 텐트에 들어가겠냐?!",
  ui_story_5004_50041701_147_dialog_content = "텐트 안에서 물총을 맞으면 꼭 빗소리 같아서 기분 좋을 것 같지 않아?",
  ui_story_5004_50041701_148_dialog_content = "그리고 <color=#FFB400>캠핑 의자</color>도 있어. 잠깐 앉아서 좀...",
  ui_story_5004_50041701_149_dialog_content = "됐다고!",
  ui_story_5004_50041701_150_dialog_content = "어이! 너희 거기서 캠핑하고 있을 때냐!",
  ui_story_5004_50041701_151_dialog_content = "너! 렉커라고 했지?",
  ui_story_5004_50041701_152_dialog_content = "그래! 뭔데?",
  ui_story_5004_50041701_153_dialog_content = "내가 시간을 끌 테니까, 그 사이에 PlayerName 녀석이 체스말을\n파낼 수 있게 중앙으로 던져버려!",
  ui_story_5004_50041701_154_dialog_content = "???",
  ui_story_5004_50041701_155_dialog_content = "뭐야? 내가 왜 네 말을 들어야 되는데?",
  ui_story_5004_50041701_156_dialog_content = "그것도 못 하겠으면 그냥 텐트에 들어가서 별이나 세든가!",
  ui_story_5004_50041701_157_dialog_content = "뭐야?! PlayerName, 좀만 참아!",
  ui_story_5004_50041701_158_dialog_content = "이, 이건 아닌 것 같아! 다른 방법이 있을 거라고!",
  ui_story_5004_50041701_159_dialog_content = "3, 2──",
  ui_story_5004_50041701_160_dialog_content = "렉커, 진정해! 일단 이거 좀 놓고 말해!",
  ui_story_5004_50041701_161_dialog_content = "1──!",
  ui_story_5004_50041701_162_dialog_content = "제발 조준 좀 하고 던져어어어──!",
  ui_story_5004_50041701_163_dialog_content = "......",
  ui_story_5004_50041701_164_dialog_content = "......",
  ui_story_5004_50041701_165_dialog_content = "PlayerName...",
  ui_story_5004_50041701_166_dialog_content = "어서 일어나...",
  ui_story_5004_50041701_167_dialog_content = "엄마...?",
  ui_story_5004_50041701_168_dialog_content = "PlayerName, 정신 차려.",
  ui_story_5004_50041701_169_dialog_content = "...렉커?!",
  ui_story_5004_50041701_170_dialog_content = "우리가 이겼어... 방금 렉커가 널 던져서 친위대의 공세를 뚫었고,\n네가 체스말을 파냈어.",
  ui_story_5004_50041701_171_dialog_content = "친위대가 흥분해서는 기절한 너를 막 쏴버렸어...\n제네비브 씨가 바로 말려서 망정이지.",
  ui_story_5004_50041701_172_dialog_content = "미안... 마침 익수자 구조 훈련을 받은 게 렉커밖에 없어서...",
  ui_story_5004_50041701_173_dialog_content = "그렇구나... 그럼 나 조금만 더 쉬어도 될까...?",
  ui_story_5004_50041901_1_dialog_content = "......",
  ui_story_5004_50041901_2_dialog_content = "제네비브.",
  ui_story_5004_50041901_3_dialog_content = "너는 장차 브론스키 가문의 부흥이라는 중임을 맡게 될 거다.",
  ui_story_5004_50041901_4_dialog_content = "......",
  ui_story_5004_50041901_5_dialog_content = "비록 지금 넌 아직 어리지만, 그래도 혹독한 훈련을 받을 필요가 있어.",
  ui_story_5004_50041901_6_dialog_content = "이건 모두 널 위해서야.",
  ui_story_5004_50041901_7_dialog_content = "네... 알고 있어요. 아버지, 어머니.",
  ui_story_5004_50041901_8_dialog_content = "이쪽은 네 루미나틱스 지도를 맡아주실 선생님이시다. 그리고 예법 교육도\n함께 담당하실 거다. 한때 백야성의 대귀족이셨던 분이지.",
  ui_story_5004_50041901_9_dialog_content = "브론스키 가문을 위해 최선을 다해서 선생님의 지도에 따라야 한다.",
  ui_story_5004_50041901_10_dialog_content = "알겠어요.",
  ui_story_5004_50041901_11_dialog_content = "그럼 너도 만티코어 가문의 여자애를 이길 수 있을 거다.",
  ui_story_5004_50041901_12_dialog_content = "제네비브, 제네비브?",
  ui_story_5004_50041901_13_dialog_content = "앗... 죄송해요, 선생님.",
  ui_story_5004_50041901_14_dialog_content = "정신을 다른 곳에 팔다니, 너답지 않구나.",
  ui_story_5004_50041901_15_dialog_content = "내주신 숙제를 빨리 끝내고 싶어서 어제 늦게까지 했거든요.",
  ui_story_5004_50041901_16_dialog_content = "내가 내준 숙제는 일주일 치잖니. 그렇게 무리할 필요는 없어.",
  ui_story_5004_50041901_17_dialog_content = "......",
  ui_story_5004_50041901_18_dialog_content = "제네비브, 넌 커서 뭘 하고 싶니?",
  ui_story_5004_50041901_19_dialog_content = "가문의 명예를 높이는 거요...?",
  ui_story_5004_50041901_20_dialog_content = "가문이 아니라 네가 하고 싶은 걸 묻는 거란다.",
  ui_story_5004_50041901_21_dialog_content = "모르겠어요... 제가 뭘 하고 싶은지...\n왠지 하고 싶은 게 없는 것 같아요.",
  ui_story_5004_50041901_22_dialog_content = "휴, 이 얘기는 그만하자.",
  ui_story_5004_50041901_23_dialog_content = "제네비브, 지난주에도 또 만티코어 가문의 딸을 만나러 갔었지?",
  ui_story_5004_50041901_24_dialog_content = "서, 선생님이 그걸 어떻게 아세요?!",
  ui_story_5004_50041901_25_dialog_content = "쉿, 이 일은 나만 알고 있으니까 걱정 안 해도 돼.\n아무한테도 말하지 않을 테니까.",
  ui_story_5004_50041901_26_dialog_content = "감사해요...",
  ui_story_5004_50041901_27_dialog_content = "근데 왜...",
  ui_story_5004_50041901_28_dialog_content = "...아니야. 역시 물어보지 않는 게 좋겠구나.",
  ui_story_5004_50041901_29_dialog_content = "......",
  ui_story_5004_50041901_30_dialog_content = "하지만 제네비브, 어쩌면 넌 가문의 명예에만 집착해선 안 될 것 같구나.",
  ui_story_5004_50041901_31_dialog_content = "왜죠?!",
  ui_story_5004_50041901_32_dialog_content = "내가 왜 지금은 귀족이 아닌지 알고 있니?",
  ui_story_5004_50041901_33_dialog_content = "지난 몇 년간 열심히 지도해 주셔서 감사합니다.",
  ui_story_5004_50041901_34_dialog_content = "별말씀을요. 제네비브는 재능이 있고 무척 노력하는 아이예요.",
  ui_story_5004_50041901_35_dialog_content = "의식 마법에 대한 지식은 이미 대부분의 귀족을 넘어서는 수준인걸요.",
  ui_story_5004_50041901_36_dialog_content = "그래서 더는 제가 가르쳐줄 게 없게 된 거죠.",
  ui_story_5004_50041901_37_dialog_content = "선생님, 이제 어디로 가실 거죠?",
  ui_story_5004_50041901_38_dialog_content = "너랑 같은 답을 해야겠구나. 선생님도 잘 모르겠어.\n무언가를 찾거나, 아니면 누군가를 찾으러 가게 될지도 모르지.",
  ui_story_5004_50041901_39_dialog_content = "게다가 무언가를 찾는 것 그 자체만으로도 의미가 있는 거란다.",
  ui_story_5004_50041901_40_dialog_content = "제네비브, 그럼 잘 지내렴.",
  ui_story_5004_50041901_41_dialog_content = "뭐라고?! 그 암귀들이 벌써 근처까지 들이닥쳤다고?!",
  ui_story_5004_50041901_42_dialog_content = "우리만으로는 페테르부르크를 지킬 수 없어요.\n반드시 백야성에 도움을 요청해야 해요.",
  ui_story_5004_50041901_43_dialog_content = "이미 백야성의 살라르 가문이 지원군을 파견해주겠다고 했어요...\n대신 저들은 조건을 하나 걸었어요.",
  ui_story_5004_50041901_44_dialog_content = "우리 가문의 후계자가 의식 마법에 얼마나 재능이 있는지를\n시험해 보고 싶다고 하더군요. 결과가 만족스럽다면 그쪽의\n방계 가문으로 받아들이고 싶다고 했어요.",
  ui_story_5004_50041901_45_dialog_content = "그런 유력 가문과 관계를 맺을 수 있다면 좋은 일이지.\n브론스키 가문에도 큰 힘이 되겠어.",
  ui_story_5004_50041901_46_dialog_content = "제네비브.",
  ui_story_5004_50041901_47_dialog_content = "알고 있어요, 아버지.",
  ui_story_5004_50041901_48_dialog_content = "제네비브 브론스키 양, 역시 생각했던 대로 강하시군요.",
  ui_story_5004_50041901_49_dialog_content = "이번 시험이 끝나면 장로님을 뵙게 될 겁니다.",
  ui_story_5004_50041901_50_dialog_content = "고마워요.",
  ui_story_5004_50041901_51_dialog_content = "어이!",
  ui_story_5004_50041901_52_dialog_content = "스모키?! 네가 여긴 왜 왔어?",
  ui_story_5004_50041901_53_dialog_content = "무슨 시합을 한다길래 한번 보러 왔지.",
  ui_story_5004_50041901_54_dialog_content = "루미나로 저 과녁을 맞히면 되는 거지?",
  ui_story_5004_50041901_55_dialog_content = "아, 아니! 이게 무슨...!",
  ui_story_5004_50041901_56_dialog_content = "엄청난 힘이다! 이런 꼬마 아가씨가 어떻게 그런 힘을...!",
  ui_story_5004_50041901_57_dialog_content = "다, 당신, 이름이 뭐죠? 어느 가문 사람입니까?",
  ui_story_5004_50041901_58_dialog_content = "응? 경품이라도 주려고? 시시한 거면 안 받을 거야.",
  ui_story_5004_50041901_59_dialog_content = "잘 들어! 난 만티코어 가문의 스모키 만티코어야!",
  ui_story_5004_50041901_60_dialog_content = "만티코어 가문의... 스모키...",
  ui_story_5004_50041901_61_dialog_content = "다른 종목은 없어? 이게 다야?",
  ui_story_5004_50041901_62_dialog_content = "예! 잠시만 기다리시죠! 저희 장로님께서 하실 말씀이...",
  ui_story_5004_50041901_63_dialog_content = "기다리라고? 그건 곤란해. 지금 옷 사러 갈 거거든.",
  ui_story_5004_50041901_64_dialog_content = "제니, 갈래? 같이 쇼핑 가자!",
  ui_story_5004_50041901_65_dialog_content = "너......",
  ui_story_5004_50041901_66_dialog_content = "휴, 제네비브.",
  ui_story_5004_50041901_67_dialog_content = "넌 일생일대의 기회를 놓쳐버렸다.",
  ui_story_5004_50041901_68_dialog_content = "그래도 살라르 가문이 페테르부르크로 지원군을\n파견해주겠다고 한 건 다행이다만.",
  ui_story_5004_50041901_69_dialog_content = "우린 이제 그들과 동맹을 맺을 기회는 없게 됐다.",
  ui_story_5004_50041901_70_dialog_content = "우선 물러가거라.",
  ui_story_5004_50041901_71_dialog_content = "죄송해요... 아버지...",
  ui_story_5004_50041901_72_dialog_content = "(스모키... 어째서... 네가 거기 나타난 거야...)",
  ui_story_5004_50041901_73_dialog_content = "(그냥 단순히 시험에 참가해서... 날 이기고 싶었던 거야? 아니면...)",
  ui_story_5004_50041901_74_dialog_content = "제, 제네비브!",
  ui_story_5004_50041901_75_dialog_content = "어머니, 무슨 일 있으세요? 우선 진정하시고 천천히 말씀해 보세요...",
  ui_story_5004_50041901_76_dialog_content = "너... 그거 들었니?",
  ui_story_5004_50041901_77_dialog_content = "살라르 가문이 계약 이행을 요구하려고... 만티코어 가문을 찾아갔어...",
  ui_story_5004_50041901_78_dialog_content = "벌써 간 건가요... 알고 있어요. 결혼 일 때문이잖아요.",
  ui_story_5004_50041901_79_dialog_content = "그런데 그 스모키라는 녀석이 사라졌어!",
  ui_story_5004_50041901_80_dialog_content = "......네?",
  ui_story_5004_50041901_81_dialog_content = "스모키가 도망쳤다고?!",
  ui_story_5004_50041901_82_dialog_content = "제길! 페테르부르크 촌뜨기 놈들이 감히!\n역시 분수에도 안 맞는 기회를 주는 게 아니었어!",
  ui_story_5004_50041901_83_dialog_content = "뭐, 헛수고가 돼버렸지만, 이제 그 촌구석에 다시 갈 필요는 없게 됐군.",
  ui_story_5004_50041901_84_dialog_content = "들어라! 장로님께서 명하셨다.\n페테르부르크는 「백야성의 보호를 필요로 하지 않는다」!\n철군하라!",
  ui_story_5004_50041901_85_dialog_content = "애초부터 고비였던 페테르부르크는 그렇게 몰락해 버렸지.",
  ui_story_5004_50041901_86_dialog_content = "어머니는 충격으로 돌아가셨고, 아버지도 병으로 쓰러지셨고 말이야.",
  ui_story_5004_50041901_87_dialog_content = "제네비브...",
  ui_story_5004_50041901_88_dialog_content = "네, 아버지...",
  ui_story_5004_50041901_89_dialog_content = "네가 지킬 이 가문도, 이제 더는 가망이 없게 되었다...",
  ui_story_5004_50041901_90_dialog_content = "네가 지금... 괴로울지... 아니면 기분이 후련할지 모르겠구나...\n앞으로의... 목표는 세웠느냐...",
  ui_story_5004_50041901_91_dialog_content = "전... 모르겠어요, 아버지... 모든 게 너무 갑작스러워서...\n아직 생각해본 적이 없었어요.",
  ui_story_5004_50041901_92_dialog_content = "불쌍한 아이야...",
  ui_story_5004_50041901_93_dialog_content = "......",
  ui_story_5004_50041901_94_dialog_content = "안나, 결국 너까지 내 곁을 떠나게 될 줄은 몰랐어...",
  ui_story_5004_50041901_95_dialog_content = "히힝...",
  ui_story_5004_50041901_96_dialog_content = "아가씨, 이 말, 당신 친구야?",
  ui_story_5004_50041901_97_dialog_content = "맞아...",
  ui_story_5004_50041901_98_dialog_content = "내가 도와줄 수 있어. 하지만 그에 맞는 대가가 필요해...",
  ui_story_5004_50041901_99_dialog_content = "정말?! 부탁할게! 뭐든 할 수 있어! 난 안나가 필요해...\n녀석을 찾으려면 안나가 꼭 필요하다고!",
  ui_story_5004_50041901_100_dialog_content = "스모키...",
  ui_story_5004_50041901_100X1_dialog_content = "당신이 제네비브 씨인가요?",
  ui_story_5004_50041901_100X2_dialog_content = "날 알아? 용건이 있으면 단도직입적으로 말해. 잡담 같은 건 관심 없으니까.",
  ui_story_5004_50041901_100X3_dialog_content = "오늘 제가 준비한 이야기라면 분명히 관심이 있으실 텐데요.\n스모키 씨에 대한 일이니까요...",
  ui_story_5004_50041901_100X4_dialog_content = "!!",
  ui_story_5004_50041901_100X5_dialog_content = "너, 스모키를 알아?",
  ui_story_5004_50041901_100X6_dialog_content = "물론이죠. 그녀가 지금 헤븐즈 비치에 있다는 것도...",
  ui_story_5004_50041901_100X7_dialog_content = "엣?! 잠깐만요, 아직 얘기가 다 안 끝났다구요!",
  ui_story_5004_50041901_102_dialog_content = "제네비브 님.",
  ui_story_5004_50041901_103_dialog_content = "제네비브 님!",
  ui_story_5004_50041901_104_dialog_content = "말해.",
  ui_story_5004_50041901_105_dialog_content = "지시하신 대로 친위대가 분위기를 띄워 놓았습니다.",
  ui_story_5004_50041901_106_dialog_content = "좋아... 이번엔 내가 직접 녀석을 상대하겠어.",
  ui_story_5004_50041901_107_dialog_content = "내 노랫소리로 녀석을 이길 거야... 아니, 굴복시키겠어!",
  ui_story_5004_50042001_1_dialog_content = "무대가 정말 예뻐요. 플뢰르 씨가 디자인한 건가요?",
  ui_story_5004_50042001_2_dialog_content = "저기 레디젤 렌치 스타일의 장식이 있는 걸 보면 확실해~",
  ui_story_5004_50042001_3_dialog_content = "플뢰르는 정말 뭐든지 잘하는구나.",
  ui_story_5004_50042001_4_dialog_content = "너희 정말 같이 참가 안 할 거야?",
  ui_story_5004_50042001_5_dialog_content = "난 됐어! 노래 같은 건 소질이 없으니까...",
  ui_story_5004_50042001_6_dialog_content = "나...나도... 사람 많은 곳은 힘들어서...",
  ui_story_5004_50042001_7_dialog_content = "난 베릴이랑 같이 있어야 하니까 패스할래~",
  ui_story_5004_50042001_8_dialog_content = "응...! 난 라파엘이랑 같이... 열심히 응원할게...!",
  ui_story_5004_50042001_9_dialog_content = "응원은 우리한테 맡겨! 클라이맥스에서 미사일을 발사해서\n분위기를 펑 터트려줄게!",
  ui_story_5004_50042001_10_dialog_content = "절대 안 돼!",
  ui_story_5004_50042001_11_dialog_content = "알겠어! 그럼 부탁할게!",
  ui_story_5004_50042001_12_dialog_content = "그럼 우리 노래를 마음껏 즐겨줘. 응원도 열심히 하고!",
  ui_story_5004_50042001_13_dialog_content = "어느새 해신제의 마지막 코너가 찾아왔네요.\n지혜와 아름다움을 상징하는── 썸머 라이브 콘서트입니다!",
  ui_story_5004_50042001_14_dialog_content = "광고주가 많아진 덕분에 이번 경기에는 특별히 거물급 심사위원을\n모시게 되었답니다~",
  ui_story_5004_50042001_15_dialog_content = "백야성에서 오신 익명의 심사위원 S 씨!",
  ui_story_5004_50042001_16_dialog_content = "크흠.",
  ui_story_5004_50042001_17_dialog_content = "그리고 움브라톤에서 오신 익명의 심사위원 I 씨!",
  ui_story_5004_50042001_18_dialog_content = "반갑군.",
  ui_story_5004_50042001_19_dialog_content = "보나시외가 심사위원까지 불러왔단 말이야?\n어라? 둘 다 어디서 많이 본 듯한 느낌인데...",
  ui_story_5004_50042001_20_dialog_content = "이번 경기의 승자는 심사위원과 현장의 관객 여러분의 투표로 결정된답니다!",
  ui_story_5004_50042001_21_dialog_content = "그럼 첫 번째 참가자!",
  ui_story_5004_50042001_22_dialog_content = "「지옥에서 온 복면 록커」를 모시겠습니다──!",
  ui_story_5004_50042001_23_dialog_content = "내 이름은 셀룰라다. 움브라톤에서 왔다.\n본명은 밝히지 않는 수수께끼의 가수다!",
  ui_story_5004_50042001_24_dialog_content = "이거... 누가 봐도 세르고잖아... 이름이랑 투구부터가 뻔하잖아!",
  ui_story_5004_50042001_25_dialog_content = "내 영혼 속 가장 깊은 곳에 있는 절규를 모두에게 바치겠다!",
  ui_story_5004_50042001_26_dialog_content = "내 야성미 넘치는 보이스로 최강의 헤비메탈을 선사하겠다!",
  ui_story_5004_50042001_27_dialog_content = "내려와!",
  ui_story_5004_50042001_28_dialog_content = "내려오라고!",
  ui_story_5004_50042001_29_dialog_content = "수영복 라이브라고 했잖아!",
  ui_story_5004_50042001_30_dialog_content = "수영복도 안 입어놓고 분위기가 살겠냐!",
  ui_story_5004_50042001_31_dialog_content = "어이! 광고랑 전혀 다르잖아아아!",
  ui_story_5004_50042001_32_dialog_content = "난 수영복 입은 아가씨를 보러 왔다고! 환불해줘!",
  ui_story_5004_50042001_33_dialog_content = "으윽... 정말 굴욕적이군. 본명을 안 써서 망정이지.",
  ui_story_5004_50042001_34_dialog_content = "그럼 언젠가 또 만나자고!",
  ui_story_5004_50042001_35_dialog_content = "엥? 이걸로 첫 번째 공연 끝이야? 너무 빠르잖아~",
  ui_story_5004_50042001_36_dialog_content = "아깝네... 방금 고양이 가면 쓴 사람.. 노래 잘할 것 같았는데...",
  ui_story_5004_50042001_37_dialog_content = "외모에 속으면 안 돼, 베릴!",
  ui_story_5004_50042001_38_dialog_content = "뭐, 그래도 잘했어! 세르고!",
  ui_story_5004_50042001_39_dialog_content = "덕분에 모두의 기대치가 내려갔잖아?\n이러면 우리 팀이 높은 점수를 받을 수 있을 거야!",
  ui_story_5004_50042001_40_dialog_content = "다음은... 플뢰르랑 렉커인가?",
  ui_story_5004_50042001_41_dialog_content = "<color=#e8d9bb>렉커는 무대에 올라 관객을 향해 인사를 한 후, 뒤쪽으로 손을 뻗었다...</color>",
  ui_story_5004_50042001_42_dialog_content = "여러분, 안녕──!",
  ui_story_5004_50042001_43_dialog_content = "꺄아아아아──!",
  ui_story_5004_50042001_44_dialog_content = "방금 봤어? 플뢰르가 날 보고 웃어줬어!",
  ui_story_5004_50042001_45_dialog_content = "뢰르뢰르, 네 윙크가 내 대흉근을 뚫고 내 뜨거운 심장에 명중했어!",
  ui_story_5004_50042001_46_dialog_content = "끼룩── 끼룩──",
  ui_story_5004_50042001_47_dialog_content = "뭐야, 웬 갈매기까지 날아왔어! 너넨 물고기나 잡으러 가라고!",
  ui_story_5004_50042001_48_dialog_content = "정말 그걸 할 생각이야?",
  ui_story_5004_50042001_49_dialog_content = "당연하지, 친구!",
  ui_story_5004_50042001_50_dialog_content = "렉커가 철근을 꺼내는데?!",
  ui_story_5004_50042001_51_dialog_content = "잠깐만! 설마 그 마술을 하려는 건 아니겠지?!",
  ui_story_5004_50042001_52_dialog_content = "레디젤 렌치에서 가장 바보인 렉커가\n저런 복잡한 마술을 할 수 있단 말이야?!",
  ui_story_5004_50042001_53_dialog_content = "꺄아아아악──!",
  ui_story_5004_50042001_54_dialog_content = "<color=#e8d9bb>순식간에 철근들이 상자를 관통해 반대쪽에서 튀어나왔다.</color>",
  ui_story_5004_50042001_55_dialog_content = "플뢰르 씨──!",
  ui_story_5004_50042001_56_dialog_content = "상자가 계속 흔들리고 있어...",
  ui_story_5004_50042001_57_dialog_content = "플뢰르 씨... 괜찮은 걸까? 안 좋은 예감이 들어...",
  ui_story_5004_50042001_58_dialog_content = "걱정 마~ 구조할 준비는 돼 있으니까!",
  ui_story_5004_50042001_59_dialog_content = "설마 목숨이 위험한 건 아니겠지...?",
  ui_story_5004_50042001_60_dialog_content = "(렉커가 뭐라고 중얼거리고 있어. 설마 기도하는 건가...?)",
  ui_story_5004_50042001_61_dialog_content = "상자가 안 움직여... 라파엘!",
  ui_story_5004_50042001_62_dialog_content = "좋아! 발사 준비!",
  ui_story_5004_50042001_63_dialog_content = "잠깐만!",
  ui_story_5004_50042001_64_dialog_content = "열려라──!",
  ui_story_5004_50042001_65_dialog_content = "우와! 말도 안 돼! 진짜 신기하네!",
  ui_story_5004_50042001_66_dialog_content = "다행이야...",
  ui_story_5004_50042001_67_dialog_content = "에이~ 그럼 내 차례는 없는 거야? 너무 낭비잖아. 미사일, 록온 해제!",
  ui_story_5004_50042001_68_dialog_content = "미사일?! 언제 또 준비한 거야?! 그렇게 응급 처치가 하고 싶어?!",
  ui_story_5004_50042001_69_dialog_content = "그래도 박수랑 함성 소리를 보면 다들 지금 공연이\n무척 마음에 들었던 모양이야.",
  ui_story_5004_50042001_70_dialog_content = "난 플뢰르 씨가 무사히 돌아와서... 박수를 치는 거야...",
  ui_story_5004_50042001_71_dialog_content = "잠깐, 잠깐만요! 이번 경기는 노래 공연으로 승부를 겨루는 거라구요!",
  ui_story_5004_50042001_72_dialog_content = "플뢰르 씨, 렉커 씨, 두 사람이라면 경기 규칙을 잘 알고 계실 텐데요.\n일부러 그런 거라면 그냥 넘어갈 수 없어요.",
  ui_story_5004_50042001_73_dialog_content = "아하하, 미안해요. 전 그냥 모두가 즐거운 시간을 보낼 수 있게\n분위기를 좀 띄우려던 거예요.",
  ui_story_5004_50042001_74_dialog_content = "근데 전 노래는 못 하니까, 결국 이 방법밖에 생각이 안 났지 뭐예요.",
  ui_story_5004_50042001_75_dialog_content = "저 여자 누구야? 왜 우리 플뢰르한테 이래라저래라 하는 건데!",
  ui_story_5004_50042001_76_dialog_content = "플뢰르 씨, 그 즐거운 시간, 지금 저랑 보내요!",
  ui_story_5004_50042001_77_dialog_content = "(장기자랑으로 바꾸는 것도 나쁘진 않을 것 같은데?)",
  ui_story_5004_50042001_78_dialog_content = "(그럼 세르고가 퇴장한 것도 좀 아쉽게 됐네.)",
  ui_story_5004_50042001_79_dialog_content = "(아니지, 세르고는 수영복도 안 입고 가면만 썼잖아.\n그럼 차라리 복면 가창대회 같은 쪽에 참가하는 게 맞겠네.)",
  ui_story_5004_50042001_80_dialog_content = "그래도 규정은 규정이에요. 플뢰르 씨의 참가 자격을 취소하겠어요.",
  ui_story_5004_50042001_81_dialog_content = "왜 꼭 노래만 불러야 하는 건데!",
  ui_story_5004_50042001_82_dialog_content = "너무해! 플뢰르 씨, 호텔 방으로 돌아가서 마술을 더 보여주세요!",
  ui_story_5004_50042001_83_dialog_content = "멍멍! 왈왈왈!",
  ui_story_5004_50042001_84_dialog_content = "냐오옹──!",
  ui_story_5004_50042001_85_dialog_content = "이젠 동물까지 온 거냐... 플뢰르의 「특수 체질」... 정말 무섭네.",
  ui_story_5004_50042001_86_dialog_content = "그럼, 여덟 번째 참가자는──",
  ui_story_5004_50042001_87_dialog_content = "제네비브 브론스키!",
  ui_story_5004_50042001_88_dialog_content = "우후훗, 겨우 이런 상대들뿐이라니.",
  ui_story_5004_50042001_89_dialog_content = "이번 기회에 심사위원과 관객들의 마음을 사로잡아 최고점을 받고 말겠어!",
  ui_story_5004_50042001_90_dialog_content = "(또 이상한 녀석들이 왔다...)",
  ui_story_5004_50042001_91_dialog_content = "(바이스랑 다들 아직인가?)",
  ui_story_5004_50042001_92_dialog_content = "PlayerName, 제네비브 차례야.",
  ui_story_5004_50042001_93_dialog_content = "응, 역시 이번에도 제네비브가 가장 강력한 상대일 것 같아──",
  ui_story_5004_50042001_94_dialog_content = "뇌우를 틈타 쏟아져♪",
  ui_story_5004_50042001_95_dialog_content = "──!",
  ui_story_5004_50042001_96_dialog_content = "그건 무정한 신의 벌일까? 아니면 쇠사슬을 푸는 구원일까나♪",
  ui_story_5004_50042001_97_dialog_content = "아득한 지평선 위♪",
  ui_story_5004_50042001_98_dialog_content = "그곳엔 빠르게 변하는 네 그림자♪",
  ui_story_5004_50042001_99_dialog_content = "버릴 수 없는 마음이 폭풍을 불러♪",
  ui_story_5004_50042001_100_dialog_content = "뻔한 길을 가는 건 미안해♪",
  ui_story_5004_50042001_101_dialog_content = "열정과 충동으로 미래를 열어♪",
  ui_story_5004_50042001_102_dialog_content = "무의미한 다툼에는 차가운 시선을♪",
  ui_story_5004_50042001_103_dialog_content = "대...대단해.",
  ui_story_5004_50042001_104_dialog_content = "......",
  ui_story_5004_50042001_105_dialog_content = "우오오오오오오오오! 제네비브 씨!",
  ui_story_5004_50042001_106_dialog_content = "음, 감정이 잘 실린 노래였다. 관중들에게도 확실히 전해진 것 같군.",
  ui_story_5004_50042001_107_dialog_content = "제네비브 양의 노래는 가슴에 바로 와 닿는 감동이 있었다.\n기회가 된다면 움브라톤에서 단독 콘서트를 제안하고 싶군.",
  ui_story_5004_50042001_108_dialog_content = "집계 결과가 나왔습니다. 제네비브 씨의\n최종 투표 점수는── 10점 만점에 9.6점!",
  ui_story_5004_50042001_109_dialog_content = "축하합니다! 정말 높은 점수를 얻으셨네요.",
  ui_story_5004_50042001_110_dialog_content = "그럼 우선 백스테이지에서 휴식을 취해 주세요.",
  ui_story_5004_50042001_111_dialog_content = "어때? 스모키... 내 실력을 잘 봤겠지?",
  ui_story_5004_50042001_112_dialog_content = "대단해...",
  ui_story_5004_50042001_113_dialog_content = "그러게... 가슴이 두근거리게 만드는 노래였어...",
  ui_story_5004_50042001_114_dialog_content = "(제네비브의 노래는 생각했던 것보다 훨씬 대단했어.\n친위대가 아닌 일반 관객들 중에서도 마음을 빼앗긴 사람이 많은 것 같아.)",
  ui_story_5004_50042001_115_dialog_content = "(우리 팀이 좀 걱정되는걸...)",
  ui_story_5004_50042001_116_dialog_content = "다음 무대의 주인공은, 세 소녀들의 그룹── 만티코어 키스!",
  ui_story_5004_50042001_117_dialog_content = "우리 팀 차례야!",
  ui_story_5004_50042001_118_dialog_content = "드디어 온 건가... 아, 왠지 나까지 긴장되는 것 같잖아...",
  ui_story_5004_50042001_119_dialog_content = "나, 나도...!",
  ui_story_5004_50042001_120_dialog_content = "♪──",
  ui_story_5004_50042001_121_dialog_content = "♪ ♩ ♫ ♬",
  ui_story_5004_50042001_122_dialog_content = "떠도는 소녀들은 오늘도 어디로 향하는 걸까♪",
  ui_story_5004_50042001_123_dialog_content = "어두운 밤의 등대에 불을 밝히면, 해안선과 흔들흔들 이어져♪",
  ui_story_5004_50042001_124_dialog_content = "오오오오!",
  ui_story_5004_50042001_125_dialog_content = "우와아아아──!",
  ui_story_5004_50042001_126_dialog_content = "(대단해... 친위대들 사이에서도 박수와 함성이 터져 나오고 있어!)",
  ui_story_5004_50042001_127_dialog_content = "바다의 향기가 별빛 쏟아지는 바다에서 전해져 와♪",
  ui_story_5004_50042001_128_dialog_content = "말없이 의지를 관철하고, 용기와 결단력으로 선명한 꽃을 피워♪",
  ui_story_5004_50042001_129_dialog_content = "빠르게 승부를 내고 큰 파도를 헤쳐나가면, 그곳엔 미래가 기다리고 있어♪",
  ui_story_5004_50042001_130_dialog_content = "카렌 언니~! 바이스! 스모키~ 대단해~!",
  ui_story_5004_50042001_131_dialog_content = "자, 베릴도 내 손 잡아. 같이 응원해 주자!",
  ui_story_5004_50042001_132_dialog_content = "응...!",
  ui_story_5004_50042001_133_dialog_content = "결코 꺾이지 않는 프라이드를 가슴에 품고, 지금 당장 저 빛을 잡으러 가자♪",
  ui_story_5004_50042001_134_dialog_content = "마음의 울림을 느껴, 금방이라도 심장이 터질 것 같아♪",
  ui_story_5004_50042001_135_dialog_content = "힘차게 고동치고♪",
  ui_story_5004_50042001_136_dialog_content = "상상 이상의 충동에 이끌려 진짜 한계를 향해 나아가♪",
  ui_story_5004_50042001_137_dialog_content = "곧바로 나아가♪",
  ui_story_5004_50042001_138_dialog_content = "세계의 정점으로──♪",
  ui_story_5004_50042001_139_dialog_content = "<color=#e8d9bb>스모키는 마이크를 들고 다른 한 손으로 제네비브를 향해\n권총을 쏘는 포즈를 취하며 가볍게 윙크를 보냈다.</color>",
  ui_story_5004_50042001_140_dialog_content = "<color=#e8d9bb>만티코어 키스, 그녀들의 공연은 완벽하게 막을 내렸다.</color>",
  ui_story_5004_50042001_141_dialog_content = "......",
  ui_story_5004_50042001_142_dialog_content = "(음? 제네비브...? 언제 온 거지?)",
  ui_story_5004_50042001_143_dialog_content = "연출 괜찮네. 전에는 2인조 그룹이었지만 말이야.",
  ui_story_5004_50042001_144_dialog_content = "어라?",
  ui_story_5004_50042001_145_dialog_content = "(없어졌잖아? 방금 웃고 있었던 것 같은데... 그나저나 2인조라니 무슨 말이지? 수수께끼인가?)",
  ui_story_5004_50042001_146_dialog_content = "만티코어 키스! 만티코어 키스! 만티코어 키스!",
  ui_story_5004_50042001_147_dialog_content = "만티코어 키스! 최고야!",
  ui_story_5004_50042001_148_dialog_content = "정말 다행이야. 다들 공연에 무척 만족했나 봐. 베릴도 감동한 것 같네.",
  ui_story_5004_50042001_149_dialog_content = "녹음은 다 하였느냐.",
  ui_story_5004_50042001_150_dialog_content = "예! 성... 아니, 심사위원님!",
  ui_story_5004_50042001_151_dialog_content = "이 그룹... 꽤 재미있군.",
  ui_story_5004_50042001_154_dialog_content = "만티코어 키스──",
  ui_story_5004_50042001_155_dialog_content = "결과는 예상대로── 10점 만점입니다──!",
  ui_story_5004_50042201_1_dialog_content = "건배~",
  ui_story_5004_50042201_2_dialog_content = "짠~",
  ui_story_5004_50042201_3_dialog_content = "뭐야, 주스로 건배라니 어린애냐!",
  ui_story_5004_50042201_4_dialog_content = "렉커 네가 평소에 마시던 술도 알코올이 아니라 오일이잖아?",
  ui_story_5004_50042201_5_dialog_content = "그건 네가 잘못 넣은 거잖아!",
  ui_story_5004_50042201_6_dialog_content = "아하하하하──",
  ui_story_5004_50042201_7_dialog_content = "카렌 언니, 바이스, 스모키, 그 노래 정말 대단했어~!",
  ui_story_5004_50042201_8_dialog_content = "무대 위의 세 사람이 꼭 밤하늘의 별처럼 빛나는 것 같아서 완전 푹 빠져버렸다니까!",
  ui_story_5004_50042201_9_dialog_content = "베릴도 감동해서 울어버렸다구!",
  ui_story_5004_50042201_10_dialog_content = "아... 응... 맞아, 노래가 너무 감동적이라서...",
  ui_story_5004_50042201_11_dialog_content = "그리고 무대 위의 모습도 다들 정말 멋있었어...",
  ui_story_5004_50042201_12_dialog_content = "베릴까지 이렇게 말하는 걸 보면, 역시 흠잡을 데 없는 공연이었던 것 같아~",
  ui_story_5004_50042201_13_dialog_content = "그나저나 아직 발표가 안 된 상품은 뭘까?",
  ui_story_5004_50042201_14_dialog_content = "상품이라면 나도 궁금한걸.",
  ui_story_5004_50042201_15_dialog_content = "보나시외한테 물어봤는데, 수상하게 웃기만 하고 말을 안 해줬어.\n내일 받을 때까지 기다리라고 하더라고.",
  ui_story_5004_50042201_16_dialog_content = "대체 뭘까? 나까지 조금 기대가 되네.",
  ui_story_5004_50042201_17_dialog_content = "맛있는 시럽이면 어떨까? 빙수 가게 장사가 더 잘 되게 말이야.",
  ui_story_5004_50042201_18_dialog_content = "그러면 백야성에도 체인점을 낼 수 있을 거야!",
  ui_story_5004_50042201_19_dialog_content = "그럼... 라파엘한테 무허가 노점상으로 단속당하는 건 아니겠지...?",
  ui_story_5004_50042201_20_dialog_content = "으음~ 바이스라면 단속에 걸려도 1분 정도는 도망칠 시간을 줄게~",
  ui_story_5004_50042201_21_dialog_content = "어이, 너희들, 축하해.",
  ui_story_5004_50042201_22_dialog_content = "아, 고마워, 제네비브... 축하하러 와준 거야?",
  ui_story_5004_50042201_23_dialog_content = "흥. 당연하지. 난 귀족이라고.",
  ui_story_5004_50042201_24_dialog_content = "그럼 설마 내가 계집애처럼 숨어서 울기라도 할 줄 알았어?",
  ui_story_5004_50042201_25_dialog_content = "안 울었어? 제니도 많이 컸구나. 옛날에는 분명히 울보였는데~",
  ui_story_5004_50042201_26_dialog_content = "뭐, 뭐야?! 지금 당장 네 숨통을 끊어주겠어!",
  ui_story_5004_50042201_27_dialog_content = "자, 자, 됐으니까 일단 한잔 어때? 과거의 원한 같은 건 술로 씻어버리자고.",
  ui_story_5004_50042201_28_dialog_content = "스모키는 제네비브를 붙잡고는 자기 옆의 자리에 앉혔다.",
  ui_story_5004_50042201_29X1_dialog_content = "마셔봐!",
  ui_story_5004_50042201_29X2_dialog_content = "쳇... 넌 정말, 변한 게 없이 짜증 나는 녀석이라니까...",
  ui_story_5004_50042201_29X3_dialog_content = "......이 술...",
  ui_story_5004_50042201_29X4_dialog_content = "맞아, 페테르부르크의 그 가게에 있던 술이랑 비슷하지?\n우리가 옛날에 자주 마시러 갔던 가게 말이야.",
  ui_story_5004_50042201_29X5_dialog_content = "비, 비슷한 재료를 썼겠지. 게다가 그런 건 진작에 잊었다고!",
  ui_story_5004_50042201_29X6_dialog_content = "만티코어 키스... 넌 왜 그 이름을 쓴 거야?",
  ui_story_5004_50042201_29X7_dialog_content = "이 술이랑 똑같아. 너도 알 거야. 그때의 일들을 네가 잊었을 리가 없으니까.",
  ui_story_5004_50042201_29X8_dialog_content = "......",
  ui_story_5004_50042201_30_dialog_content = "(이 둘 사이는 뭔가 엄청 복잡한 것 같네...)",
  ui_story_5004_50042201_31_dialog_content = "플뢰르 씨의 마술... 기회가 되면 또 보고 싶어요.",
  ui_story_5004_50042201_32_dialog_content = "아직도 어떻게 한 건지 전혀 모르겠어요...",
  ui_story_5004_50042201_33_dialog_content = "물론 좋지! 얼마든지 보여줄 수 있어.",
  ui_story_5004_50042201_34_dialog_content = "그럼 사람이 좀 적은 곳부터 찾아봐!",
  ui_story_5004_50042201_35_dialog_content = "아까 공연장에서 널 막아주면서 도망치느라 사람들한테 짓눌리고...\n개랑 고양이한테까지 물렸다고...",
  ui_story_5004_50042201_36_dialog_content = "렉커 덕분에 살았어. 이따가 상처 소독해 줄게.",
  ui_story_5004_50042201_37_dialog_content = "그리고 로봇 제작도 이제 막바지 단계거든. 네 도움이 필요해.",
  ui_story_5004_50042201_38_dialog_content = "뭐, 도와주는 건 문제없지만 일단은 술부터 좀 마시자고.",
  ui_story_5004_50042201_39_dialog_content = "로봇이... 벌써 완성 단계인 거야?",
  ui_story_5004_50042201_40_dialog_content = "일루미나의 연구 부서에서도 한 대를 만드는 데 몇 달은 걸린다구.",
  ui_story_5004_50042201_41_dialog_content = "다 보나시외 씨 덕분이야. 부탁받은 일을 하는 동안\n도움이 되는 설비나 자료를 많이 얻었거든.",
  ui_story_5004_50042201_42_dialog_content = "그럼 그동안 계속 꿈꿔오던 완벽한 존재... 레디젤 렌치 1호 전술 로봇이!",
  ui_story_5004_50042201_43_dialog_content = "드디어 오늘 밤 탄생하는 거야!",
  ui_story_5004_50042201_44_dialog_content = "(이렇게 진지한 플뢰르의 모습은 또 처음이네...)",
  ui_story_5004_50042201_45_dialog_content = "(아무래도 플뢰르는 기계나 로봇을 진심으로 좋아하는 것 같아...)",
  ui_story_5004_50042201_46_dialog_content = "바, 방금 그건 뭐지...?",
  ui_story_5004_50042201_47_dialog_content = "으윽...",
  ui_story_5004_50042201_48_dialog_content = "베릴? 왜 땀이 났어?",
  ui_story_5004_50042201_49_dialog_content = "라파엘, 방까지 좀 데려다줄 수 있을까...?",
  ui_story_5004_50042201_50_dialog_content = "PlayerName, 베릴이 아픈 것 같아. 우리 먼저 갈게.",
  ui_story_5004_50042201_51_dialog_content = "아직도 상태가 안 좋은 거야? 지난번에 베릴이 힘을 많이 쓰긴 했지만...\n벌써 며칠이나 지났잖아.",
  ui_story_5004_50042201_52_dialog_content = "아무래도 전혀 좋아지지 않은 모양이네...",
  ui_story_5004_50042201_53_dialog_content = "아마 그리 간단한 일이 아닌 것 같아... 참, 피로스 가문에 대한 문서 말인데,\n라파엘한테 얘기 들었지?",
  ui_story_5004_50042201_54_dialog_content = "응, 베르타한테 모든 자료를 열람할 권한을 신청해 뒀어.",
  ui_story_5004_50042201_55_dialog_content = "뭔가 도움이 될 만한 정보를 찾을 수 있을지는\n일단 기다려 보는 수밖에 없겠어.",
  ui_story_5004_50042301_1_dialog_content = "의식이 곧 성공할 거야...",
  ui_story_5004_50042301_2_dialog_content = "「악장」에 걸린 아이테르의 봉인을 없애고... 그걸 연주해.",
  ui_story_5004_50042301_3_dialog_content = "이제 왕의 영광이 다시 이 해안을 비추고...\n저 오만한 오로리안들을 심판할 거야...",
  ui_story_5004_50042301_4_dialog_content = "알고 있습니다...! 부디 안심하십시오. 제가 최선을 다하겠습니다.",
  ui_story_5004_50042301_5_dialog_content = "저 왔어요.",
  ui_story_5004_50042301_6_dialog_content = "보나시외! 너희 오로리안들은 노크도 할 줄 모르는 거냐?!",
  ui_story_5004_50042301_7_dialog_content = "쓸데없는 말은 됐어요. 전 무슨 일로 불렀죠?",
  ui_story_5004_50042301_8_dialog_content = "악장이 곧 발굴된다. 그 봉인을...",
  ui_story_5004_50042301_9_dialog_content = "알고 있다니까요. 아이테르의 힘이 필요하잖아요.",
  ui_story_5004_50042301_10_dialog_content = "제가 PlayerName 그 사람을 이용할게요.",
  ui_story_5004_50042301_11_dialog_content = "...우리가 어떤 음모를 꾸미고 있는지 궁금하지 않은 거냐?",
  ui_story_5004_50042301_12_dialog_content = "네, 전혀요. 당신들이 무슨 짓을 하든,\n전 악장을 손에 넣는 게 더 중요하니까요.",
  ui_story_5004_50042301_13_dialog_content = "게다가 당신들만 가지고 되겠어요? ...그 오로리안들 중의 어느 한 사람이든지\n당신들을 전부 때려눕힐 힘은 충분한걸요.",
  ui_story_5004_50042301_14_dialog_content = "정말 무슨 일을 꾸미고 있는 거라면...\n부디 당신들의 시신이 온전하길 빌어줄게요.",
  ui_story_5004_50042301_15_dialog_content = "하지만 사기로 돈이나 뜯는 그 계획들은 정말 시시하다고 말하지 않을 수가 없네요.",
  ui_story_5004_50042301_16_dialog_content = "크윽...! 이 빌어먹을 오로리안이 정말 화가 치밀게 만드는군!",
  ui_story_5004_50042301_17_dialog_content = "이번 일이 끝나고도 그렇게 건방지게 굴 수 있을 것 같냐!",
  ui_story_5004_50042301_18_dialog_content = "펭그그 님! 화를 참으세요!",
  ui_story_5004_50042301_19_dialog_content = "어라? 당신도 있었어요? 요가 수업은 안 해도 되는 건가요?",
  ui_story_5004_50042301_20_dialog_content = "뭐, 됐어요. 전 PlayerName 씨한테 가볼 테니까, 여러분은 알아서 하세요.",
  ui_story_5004_50042301_21_dialog_content = "아, 잠깐만 기다리세요, 보나시외 양!",
  ui_story_5004_50042301_22_dialog_content = "제가 새로운 홍보문을 준비했습니다. 들어주시죠!",
  ui_story_5004_50042301_23_dialog_content = "......",
  ui_story_5004_50042301_24_dialog_content = "분명히 저 오로리안 녀석을 이용하는 건 나인데, 왜 내가 화를 내고 있는 거냐...",
  ui_story_5004_50042301_25_dialog_content = "게다가 이 쓸모없는 부하들... 지금 요가 홍보가 중요하냐?!",
  ui_story_5004_50042301_26_dialog_content = "어휴...",
  ui_story_5004_50042301_35_dialog_content = "휴우~ 베릴, 우선 침대에 누워있어~",
  ui_story_5004_50042301_36_dialog_content = "음... 이마랑 몸이 너무 뜨거워... 땀도 멈추질 않네... 많이 힘들지?",
  ui_story_5004_50042301_37_dialog_content = "난... 괜찮아...",
  ui_story_5004_50042301_38_dialog_content = "수건 가져와서 땀 닦아줄게!",
  ui_story_5004_50042301_39_dialog_content = "괜찮아... 그것보다...",
  ui_story_5004_50042301_40_dialog_content = "옆에 누워줄 수 있을까...?",
  ui_story_5004_50042301_41_dialog_content = "얼마든지~",
  ui_story_5004_50042301_42_dialog_content = "베릴, 이마가 엄청 뜨거워...\n찬물에 수건 적셔서 올려줄까 했는데 정말 괜찮아?",
  ui_story_5004_50042301_43_dialog_content = "응... 이대로면 돼...",
  ui_story_5004_50042301_44_dialog_content = "내일 시상식이 끝나면 PlayerName 한테 부탁해서\n스카이워커호를 타고 백야성으로 가자.",
  ui_story_5004_50042301_45_dialog_content = "그쪽에 있는 병원에선 널 간병하기 더 좋을 거야.",
  ui_story_5004_50042301_46_dialog_content = "그리고 백야성에도 재미있는 사람들이 많이 있거든.\n다른 천사들도 너한테 소개해 줄게.",
  ui_story_5004_50042301_47_dialog_content = "다들 분명히 베릴을 좋아할 거야.",
  ui_story_5004_50042301_48_dialog_content = "참, 우리엘이라는 천사도 있는데, 베릴처럼 항상 기운이 없는 애야~",
  ui_story_5004_50042301_49_dialog_content = "그래도 너처럼 아주 믿음직한 동료야~",
  ui_story_5004_50042301_50_dialog_content = "정말... 나도 믿음직한 동료야...?",
  ui_story_5004_50042301_51_dialog_content = "당연하지~ 그리고 거긴 예쁜 가게랑 레스토랑도 많아.",
  ui_story_5004_50042301_52_dialog_content = "내가 자주 다니던 가게도 구경 시켜 줄게~",
  ui_story_5004_50042301_53_dialog_content = "혹시 빵 좋아하면 단골 빵집도 있으니까 가자~",
  ui_story_5004_50042301_54_dialog_content = "거기 주인은 정말 좋은 사람이야. 전에 나한테도 빵이랑\n과자 만드는 법을 잔뜩 가르쳐 줬거든!",
  ui_story_5004_50042301_55_dialog_content = "참, 백야성의 콘서트홀도 가야지. 거긴 유명한 사람도 자주 공연을 하는데,\n대신 표를 구하기가 좀 어려워~",
  ui_story_5004_50042301_56_dialog_content = "응...",
  ui_story_5004_50042301_57_dialog_content = "베릴...?",
  ui_story_5004_50042301_58_dialog_content = "사실... 말할지 할지 계속 고민했던 게 하나 있어...",
  ui_story_5004_50042301_59_dialog_content = "뭔데? 얼른 말해봐~",
  ui_story_5004_50042301_60_dialog_content = "난... 너무 무서워...",
  ui_story_5004_50042301_61_dialog_content = "내가... 여길 벗어나지 못할 것 같아서... 무서워...",
  ui_story_5004_50042301_62_dialog_content = "에? 왜 그런 건데?",
  ui_story_5004_50042301_63_dialog_content = "요즘... 매일 똑같은 꿈을 꿔...",
  ui_story_5004_50042301_64_dialog_content = "같은 꿈을 반복하는데... 점점 더 무서운 꿈이 돼...",
  ui_story_5004_50042301_65_dialog_content = "처음엔 꿈속에서 희미한 목소리가 들렸어...",
  ui_story_5004_50042301_66_dialog_content = "계속 나한테 뭔가 애타게 말하는데...\n내가 잊고 있었던 옛날 일들이 생각나게 만들었어...",
  ui_story_5004_50042301_67_dialog_content = "(베릴의 옛날 일이라면... 고티에 가문이랑 피로스 가문의 일인가...?)",
  ui_story_5004_50042301_68_dialog_content = "그 여자가... 자꾸 내가 기억하지 못 하는 일이나...\n기억하고 싶지 않은 일들을 말해... 그래서 너무 무서워...",
  ui_story_5004_50042301_69_dialog_content = "그리고 그 목소리는 마지막에 나한테 이런 말을 해...",
  ui_story_5004_50042301_70_dialog_content = "「네 몸은 무너지고, 제어를 잃어 모두를 죽일 거야.\n그리고 네 정신은 끝없는 심연의 밑바닥으로 가라앉을 거야」",
  ui_story_5004_50042301_71_dialog_content = "!!",
  ui_story_5004_50042301_72_dialog_content = "그 꿈을 잊어버리고 싶은데... 계속 머릿속에서 떠나질 않아...",
  ui_story_5004_50042301_73_dialog_content = "그리고 확실히 느껴져... 내 몸 상태가 점점 나빠지고 있어...",
  ui_story_5004_50042301_74_dialog_content = "베릴...",
  ui_story_5004_50042301_75_dialog_content = "그런 꿈속의 이야기를 믿을 필요 없어!",
  ui_story_5004_50042301_76_dialog_content = "휴...",
  ui_story_5004_50042301_77_dialog_content = "베릴, 꿈은 그냥 꿈일 뿐이야. 아무 의미도 없는 거라구.",
  ui_story_5004_50042301_78_dialog_content = "네가 컨디션이 안 좋은 건 이틀 동안 사람들을 돕느라 힘들었으니까 그런 거야.\n그리고 많이 놀기도 했잖아!",
  ui_story_5004_50042301_79_dialog_content = "그 꿈이라면... PlayerName하고 얘기해 볼게.\n감응 능력으로 뭔가 도움을 받을 수 있을지도 몰라.",
  ui_story_5004_50042301_80_dialog_content = "일단 쉬고 있어. 내가 만나고 올 테니까!",
  ui_story_5004_50042301_81_dialog_content = "알았지? 그럼 푹 쉬고 있어야 해. 내일이면 백야성으로 돌아갈 수 있을 거야~",
  ui_story_5004_50042301_82_dialog_content = "...응.",
  ui_story_5004_50042301_83_dialog_content = "금방 돌아올게. 기다려!",
  ui_story_5004_50042301_84_dialog_content = "으악, 위험했어...",
  ui_story_5004_50042301_85_dialog_content = "큰일이다... 어서 돌아가야겠어.",
  ui_story_5004_50042301_86_dialog_content = "뭐라고! 그게 정말이냐?!",
  ui_story_5004_50042301_87_dialog_content = "네! 자칫하면 저랑 부딪칠 뻔했다니까요.",
  ui_story_5004_50042301_88_dialog_content = "그게 사실이라면 즉시 「왕비」님께 보고해야 한다.",
  ui_story_5004_50042301_89_dialog_content = "중요한 정보를 알려드렸으니까... 그럼 이번 달 업무 성과는...",
  ui_story_5004_50042301_90_dialog_content = "...일단 돌아가라.",
  ui_story_5004_50042301_91_dialog_content = "쓸모없는 녀석!",
  ui_story_5004_50042301_92_dialog_content = "부, 부디 용서해 주십시오...",
  ui_story_5004_50042301_93_dialog_content = "내가 무슨 고생을 해서 그 체스말들을 모두 모았는데,\n너희처럼 무능한 녀석들 때문에...",
  ui_story_5004_50042301_94_dialog_content = "놈들을 놓쳐버렸잖아!",
  ui_story_5004_50042301_95_dialog_content = "정말 죄송합니다!",
  ui_story_5004_50042301_96_dialog_content = "정말 도움이 하나도 안 되네. 역시 내가 직접 나서야 하는 건가...",
  ui_story_5004_50042301_97_dialog_content = "아깝네... 내가 가장 아끼는 체스말이었는데...",
  ui_story_5004_50042301_98_dialog_content = "크큭, 키히힛...",
  ui_story_5004_50042401_1_dialog_content = "PlayerName! 나랑 같이 좀 가자.",
  ui_story_5004_50042401_2_dialog_content = "잠깐만, 잡아당기지 마... 지금 바이스랑 빙수 가게의 사업 확장에 대해\n논의하는 중이란 말이야.",
  ui_story_5004_50042401_3_dialog_content = "내일이면 상금으로 가게를 업그레이드할 수 있어.\n그럼 이제부터 우리 세상이라고!",
  ui_story_5004_50042401_4_dialog_content = "지금 그게 중요한 게 아니야. 베릴이 상태가 이상해!",
  ui_story_5004_50042401_5_dialog_content = "베릴이 왜?",
  ui_story_5004_50042401_6_dialog_content = "내가 보기엔 지금 당장 백야성으로 돌아가서 치료가 필요할 것 같아.",
  ui_story_5004_50042401_7_dialog_content = "맞아, PlayerName. 그럼 이제 돌아갈 때가 됐어.",
  ui_story_5004_50042401_8_dialog_content = "우리가 여기 온 목적은 베릴의 마음을 달래주기 위해서였잖아?",
  ui_story_5004_50042401_9_dialog_content = "만약 여기 있으면서 베릴의 증상이 더 악화된다면,\n그건 본말이 전도된 일이야.",
  ui_story_5004_50042401_10_dialog_content = "그렇구나! 그럼 일단 베릴의 상태부터 보고 결정하자!",
  ui_story_5004_50042401_11_dialog_content = "으앗! 아파라... 눈앞이 캄캄해...",
  ui_story_5004_50042401_12_dialog_content = "앗, 미안해! 보나시외, 괜찮아?",
  ui_story_5004_50042401_13_dialog_content = "참, 우린 일이 생겨서 지금 바로 백야성으로 돌아가야 해. 상품은 필요 없어!",
  ui_story_5004_50042401_14_dialog_content = "네? 상품이 필요 없다니, 그게 무슨 말씀이세요? 잠깐만요!",
  ui_story_5004_50042401_15_dialog_content = "으으으... 정말 짜증 나네요! 어째서 하필 이럴 때 문제가 생기는 거죠?!",
  ui_story_5004_50042401_16_dialog_content = "베릴... 내가 다들 데리고...",
  ui_story_5004_50042401_17_dialog_content = "왔어... 어라? 베릴...?",
  ui_story_5004_50042401_18_dialog_content = "베릴? 어디 간 거야?!",
  ui_story_5004_50042401_19_dialog_content = "나, 날 붙잡고 흔든다고 내가 알아? 내가 유괴한 것도 아니잖아!",
  ui_story_5004_50042401_20_dialog_content = "내가 분명히 잘 쉬고 있으라고 했는데!",
  ui_story_5004_50042401_21_dialog_content = "얼른 방법을 생각해 봐! 베릴은 아직 아프단 말이야!\n이대로 돌아다니면 위험해!",
  ui_story_5004_50042401_22_dialog_content = "PlayerName! PlayerName!",
  ui_story_5004_50042401_23_dialog_content = "PlayerName, 감응 능력으로 라파엘을 도와줘 봐.",
  ui_story_5004_50042401_24_dialog_content = "아, 알겠다고! 계속 흔들어 대면 감응할 수가 없어!",
  ui_story_5004_50042401_25_dialog_content = "라파엘, 일단 진정하고 놔줘.",
  ui_story_5004_50042401_26_dialog_content = "휴...",
  ui_story_5004_50042401_27_dialog_content = "호텔엔 없어.",
  ui_story_5004_50042401_28_dialog_content = "대신 발자국을 찾을 순 있을 것 같아...",
  ui_story_5004_50042401_29_dialog_content = "왠지 그 조각상이 있던 절벽으로 간 것 같아.",
  ui_story_5004_50042401_30_dialog_content = "PlayerName, 얼른 다른 사람들도 불러서\n베릴을 찾는 걸 도와달라고 해줘!",
  ui_story_5004_50042401_31_dialog_content = "뭐? 다른 사람도 전부? 그거 너무 일이 커지는 거 아냐?",
  ui_story_5004_50042401_32_dialog_content = "PlayerName, 너무 잘 놀아서 긴장감을 완전히 잃어버린 모양이네.",
  ui_story_5004_50042401_33_dialog_content = "호텔 주변은 보안 시설이 있어서 비교적 안전한 거야.",
  ui_story_5004_50042401_34_dialog_content = "오는 길에 암귀 무리랑 마주쳤던 거 잊었어?",
  ui_story_5004_50042401_35_dialog_content = "만약 베릴이 실수로 암귀 소굴에 들어가면 어떡하려고 그래?",
  ui_story_5004_50042401_36_dialog_content = "생각해 보니 정말 그렇네...",
  ui_story_5004_50042401_37_dialog_content = "좋아! 그럼 지금 당장 사람들을 불러서 다 같이 찾자!",
  ui_story_5004_50042401_38_dialog_content = "다들 도와주러 와서 고마워. 제네비브까지 와줄 줄은 몰랐어.",
  ui_story_5004_50042401_39_dialog_content = "그런 소리 하지 마. 이젠 다들 친구잖아. 서로 돕는 건 당연하지!",
  ui_story_5004_50042401_40_dialog_content = "얘도 사실 속마음은 따뜻한 녀석이거든. 성격이 좀 나빠서 그렇지.",
  ui_story_5004_50042401_41_dialog_content = "뭐야? 난 그저 네가 실수하는 순간을 놓치고 싶지 않아서 온 거라고!",
  ui_story_5004_50042401_42_dialog_content = "아하하... 아무튼 너희 둘도 간만에 만났는데 우리가 방해한 건 아니지?\n그럼 일단 서둘러 베릴을 찾아보자!",
  ui_story_5004_50042401_43_dialog_content = "PlayerName, 이쪽 방향 맞아? 이 숲...\n뭔가 이상한 느낌이 들어...",
  ui_story_5004_50042401_44_dialog_content = "확실해. 베릴이 분명히 이 길을 지나갔어.",
  ui_story_5004_50042401_45_dialog_content = "근데... 우리 왠지 계속 이 근처를 맴도는 것 같은 느낌인데?\n게다가 낮이랑은 분위기가 전혀 다르잖아.",
  ui_story_5004_50042401_46_dialog_content = "(이 길, 어디까지 이어지는 건지 모르겠어. 주변에서 알 수 없는\n동물 울음소리도 들리고... 좀 무서운데...)",
  ui_story_5004_50042401_47_dialog_content = "잠깐만, 뭔가 들린 것 같아...",
  ui_story_5004_50042401_48_dialog_content = "꺄아아앗──",
  ui_story_5004_50042401_49_dialog_content = "우아악!",
  ui_story_5004_50042401_50_dialog_content = "보나시외? 네가 왜 여기 있어?",
  ui_story_5004_50042401_51_dialog_content = "이게 다 여러분이 갑자기 돌아간다니까 그런 거잖아요!\n그래서 얼른 <color=#FFB400>「궁극의 상품」</color>를 가져다드리려던 참이었어요!",
  ui_story_5004_50042401_52_dialog_content = "여러분이야말로 왜 여기 계신 거죠?",
  ui_story_5004_50042401_53_dialog_content = "설마... 돌아가기 전에 두근두근 담력 테스트라도 하시는 건가요~?",
  ui_story_5004_50042401_54_dialog_content = "그럼 저도 끼워주세요.",
  ui_story_5004_50042401_55_dialog_content = "담력 테스트 같은 거 아니거든!",
  ui_story_5004_50042401_56_dialog_content = "사실은... 베릴이 없어졌어... 우리가 돌아가려는 건\n베릴의 몸 상태가 나빠져서 그런 거야.",
  ui_story_5004_50042401_57_dialog_content = "베릴의 상태가 더 악화되거나, 암귀 같은 위험한 녀석과\n마주쳤을지도 모르니까 빨리 찾아야 해.",
  ui_story_5004_50042401_58_dialog_content = "어머... 베릴이 사라졌다구요? 같은 진리의 결사의 동료로서\n결코 그냥 지나칠 순 없겠네요.",
  ui_story_5004_50042401_59_dialog_content = "하지만 여긴 정말 위험해요. 암귀 말고도 더 무섭고...\n더 사악한 존재가 있어요!",
  ui_story_5004_50042401_60_dialog_content = "담력 테스트가 아니라고 했잖아! 언제까지 그런 장난 같은 말을 할 건데!",
  ui_story_5004_50042401_61_dialog_content = "감응으로 느껴져... 베릴은 절벽 위에 있어...\n지금은 움직이지 않는 것 같아.",
  ui_story_5004_50042401_62_dialog_content = "하지만 지금 한참 동안 돌아다녔는데 이 숲 밖으로 전혀 나갈 수가 없어...",
  ui_story_5004_50042401_63_dialog_content = "어쩔 수 없네요. 베릴을 위해서라고 하니까 그럼 길 안내를 해드리죠.\n모두 따라오세요.",
  ui_story_5004_50042401_64_dialog_content = "베릴!",
  ui_story_5004_50042401_65_dialog_content = "오지 마...!",
  ui_story_5004_50042401_66_dialog_content = "그쪽은 위험해! 가면 안 돼!",
  ui_story_5004_50042401_67_dialog_content = "위험한 거 알아... 그러니까 이쪽으로 오지 마...",
  ui_story_5004_50042401_68_dialog_content = "일단 진정해... 베릴, 왜 여기까지 온 거야?",
  ui_story_5004_50042401_69_dialog_content = "나도... 잘... 모르겠어...",
  ui_story_5004_50042401_70_dialog_content = "라파엘이 간 뒤에도... 난 계속 기운이 없어서 침대에 누워 있었어...",
  ui_story_5004_50042401_71_dialog_content = "하지만 갑자기 몸을 움직일 수가 없게 됐어...",
  ui_story_5004_50042401_72_dialog_content = "그러더니 검은 팔이 나타나서... 내 목을 조르고 눈을 가렸어.",
  ui_story_5004_50042401_73_dialog_content = "그리고... 무서운 웃음소리가 귓가에 들리고... 난 정신을 잃었어...",
  ui_story_5004_50042401_74_dialog_content = "그 웃음소리가 전에 네가 말했던 꿈속의 사람 목소리야?",
  ui_story_5004_50042401_75_dialog_content = "응...",
  ui_story_5004_50042401_76_dialog_content = "나도 내가 왜 여기 온 건지 모르겠어...",
  ui_story_5004_50042401_77_dialog_content = "그리고 앞으로 어떻게 될지도...",
  ui_story_5004_50042401_78_dialog_content = "만약 그 목소리가 나한테 했던 말대로라면...\n난 소중한 사람을 죽이고 말 거야...",
  ui_story_5004_50042401_79_dialog_content = "그건 그냥 악몽일 뿐이야!",
  ui_story_5004_50042401_80_dialog_content = "악몽이라고 해도! 난 지금 그 악몽에 조종돼서 여기까지 와버린 거잖아!",
  ui_story_5004_50042401_81_dialog_content = "이제 두 번 다시 눈앞에서 소중한 사람이 죽는 걸 보고 싶진 않아!",
  ui_story_5004_50042401_82_dialog_content = "바보 같은 소리 그만해!",
  ui_story_5004_50042401_83_dialog_content = "......",
  ui_story_5004_50042401_84_dialog_content = "넌 괜찮을 거야! 넌 우리랑 같이 해변의 용사가 됐잖아!",
  ui_story_5004_50042401_85_dialog_content = "(그, 그런 얘기로 효과가 있을까...)",
  ui_story_5004_50042401_86_dialog_content = "라파엘...",
  ui_story_5004_50042401_87_dialog_content = "우리 같이 백야성에 가기로 약속했잖아...",
  ui_story_5004_50042401_88_dialog_content = "잠깐만...",
  ui_story_5004_50042401_89_dialog_content = "돌아와. 그쪽은 위험해.",
  ui_story_5004_50042401_90_dialog_content = "어이, 저 수정... 계속 반짝거리는 게 뭔가 불안하다고.",
  ui_story_5004_50042401_91_dialog_content = "조심해! 수정이 폭발할 거야!",
  ui_story_5004_50042401_92_dialog_content = "PlayerName! 위험해!",
  ui_story_5004_50042401_93_dialog_content = "베릴!",
  ui_story_5004_50042401_95_dialog_content = "...!",
  ui_story_5004_50042401_96_dialog_content = "베릴!",
  ui_story_5004_50042401_97_dialog_content = "라파엘?!",
  ui_story_5004_50042401_98_dialog_content = "빨리 내 손을 잡아!",
  ui_story_5004_50042401_99_dialog_content = "응...!",
  ui_story_5004_50042401_100_dialog_content = "미안해... 나 때문에...",
  ui_story_5004_50042401_101_dialog_content = "아무리 라파엘이 호위대의 천사라고 해도...\n이런 높이에서 떨어지면 무사하기 힘들 거야...",
  ui_story_5004_50042401_102_dialog_content = "정말... 너랑 같이... 백야성에 가고 싶었는데...",
  ui_story_5004_50042401_103_dialog_content = "<size=45>지금── 뭐라고── 했어──?!</size>",
  ui_story_5004_50042401_104_dialog_content = "가...같이 백야성에 가고 싶다고...?",
  ui_story_5004_50042401_105_dialog_content = "<size=45>그 전에──!</size>",
  ui_story_5004_50042401_106_dialog_content = "아무리 라파엘이 천사라도...?",
  ui_story_5004_50042401_107_dialog_content = "전탄 발사! 하중 해제! 축복의 십자가... 최대 출력 준비──!",
  ui_story_5004_50042401_108_dialog_content = "<size=45>베릴! 천사란 건 말이야! 날 수 있는 거라구──!</size>",
  ui_story_5004_50042401_109_dialog_content = "베릴...! 꽉 잡아! 에너지가 곧 고갈될 거야!",
  ui_story_5004_50042401_110_dialog_content = "날 놔버려! 라파엘! 두 사람 무게를 못 견딜 거야!\n이러다간 우리 둘 다...",
  ui_story_5004_50042401_111_dialog_content = "바보같은 소리 그만해!",
  ui_story_5004_50042401_112_dialog_content = "난 절대... 절대 놓지 않을 거라구!",
  ui_story_5004_50042401_113_dialog_content = "<color=#e8d9bb>빠드득── 콰직──</color>",
  ui_story_5004_50042401_114_dialog_content = "(벌써 한계야?)",
  ui_story_5004_50042401_115_dialog_content = "<size=50><color=#e8d9bb>퍼어엉──</color></size>",
  ui_story_5004_50042401_116_dialog_content = "라파엘, 라파엘, 정신 차려...",
  ui_story_5004_50042401_117_dialog_content = "베릴...",
  ui_story_5004_50042401_118_dialog_content = "베릴! 다친 데는 없어?",
  ui_story_5004_50042401_119_dialog_content = "난... 괜찮아...",
  ui_story_5004_50042401_120_dialog_content = "고마워...",
  ui_story_5004_50042401_121_dialog_content = "무사해서 정말 다행이다... 너도 고생했어.",
  ui_story_5004_50042401_123_dialog_content = "이제 여기서 다들 올 때까지 기다리자.",
  ui_story_5004_50042401_124_dialog_content = "잠깐만... 라파엘... 저쪽에...?!",
  ui_story_5004_50042401_125_dialog_content = "크오오!",
  ui_story_5004_50042401_126_dialog_content = "캬아악... 크악!",
  ui_story_5004_50042401_127_dialog_content = "암귀가... 너무 많잖아...",
  ui_story_5004_50042401_128_dialog_content = "베릴! 아직 싸울 수 있겠어?",
  ui_story_5004_50042401_129_dialog_content = "응!",
  ui_story_5004_50042401_130_dialog_content = "(PlayerName... 조금만 더 서둘러 줘!)",
  ui_story_5004_50042501_1_dialog_content = "보나시외, 절벽 아래로 가는 지름길을 안내해줘!",
  ui_story_5004_50042501_2_dialog_content = "알겠어요. 이쪽이에요. 요괴에게 끌려가지 않도록 바짝 붙어서 따라와 주세요.",
  ui_story_5004_50042501_2X1_dialog_content = "서둘러 악장을 확보해라. 그리고 보나시외에게 주는 거다.",
  ui_story_5004_50042501_2X2_dialog_content = "그 여자가 아이테르에게 봉인을 풀게 만들어야만\n「적막의 군주」를 부활시킬 수 있다.",
  ui_story_5004_50042501_2X3_dialog_content = "펭그그 님, 우린 그동안 겨우 호텔에 잠입해 해신제를 개최하고,\n경기에서 오로리안들이 발산한 에너지를 수집했습니다.",
  ui_story_5004_50042501_2X4_dialog_content = "이번엔 또 갖은 고생을 해서 아이테르가 봉인을 풀게 만들고,\n보나시외한테 악장도 전부 넘겼습니다...",
  ui_story_5004_50042501_2X5_dialog_content = "정말 이렇게 해서 그 「군주」인지 뭔지가 부활한다는 겁니까?\n그가 부활하면 우리에게 무슨 이점이 있는 겁니까?",
  ui_story_5004_50042501_2X6_dialog_content = "이건 여덟 팬텀 중 그분께서 내리신 명령이다...\n「군주」는 매우 강한 힘을 가진 암귀라고 한다.",
  ui_story_5004_50042501_2X7_dialog_content = "그를 부활시킬 수만 있다면, 우린 그 어리석은\n오로리안들을 모조리 처치할 수 있을 거다.",
  ui_story_5004_50042501_2X8_dialog_content = "그럴 수 있다면 좋겠지만... 으윽! 왜 갑자기 멈추신 겁니까?",
  ui_story_5004_50042501_2X9_dialog_content = "밖에서 싸우는 소리가 나는군... 일단 숨어라!",
  ui_story_5004_50042501_3_dialog_content = "여기 숨어 있으면 못 찾겠지?",
  ui_story_5004_50042501_4_dialog_content = "이런 곳에 동굴이 있었구나... 근데 너무 깜깜해...",
  ui_story_5004_50042501_5_dialog_content = "크오오!",
  ui_story_5004_50042501_6_dialog_content = "윽! 이 역겨운 암귀들은 왜 끝이 없는 거야!",
  ui_story_5004_50042501_7_dialog_content = "베릴, 얼마나 더 버틸 수 있을 것 같아?",
  ui_story_5004_50042501_8_dialog_content = "하... 하아... 나, 난 괜찮아... 아직 싸울 수 있어...",
  ui_story_5004_50042501_10_dialog_content = "크아아악!",
  ui_story_5004_50042501_11_dialog_content = "크오오!",
  ui_story_5004_50042501_12_dialog_content = "이런! 들어온 길이 막혀버렸어!",
  ui_story_5004_50042501_13_dialog_content = "정말 짜증 나는 녀석들이네!",
  ui_story_5004_50042501_14_dialog_content = "라파엘 씨! 베릴!",
  ui_story_5004_50042501_15_dialog_content = "너희 괜찮아?!",
  ui_story_5004_50042501_16_dialog_content = "PlayerName! 너무 느리잖아!",
  ui_story_5004_50042501_17_dialog_content = "숙녀를 이렇게 기다리게 하면 어떡해!",
  ui_story_5004_50042501_18_dialog_content = "미안해! 이제 암귀들한테 본때를 보여주자!",
  ui_story_5004_50042601_1_dialog_content = "휴, 이제야 끝났네.",
  ui_story_5004_50042601_2_dialog_content = "라파엘, 베릴, 괜찮아? 어디 다친 데 없어?",
  ui_story_5004_50042601_3_dialog_content = "당연하지. 내가 있는 한 베릴을 다치게 두진 않을 거야!",
  ui_story_5004_50042601_4_dialog_content = "응... 라파엘이 지켜줬어...",
  ui_story_5004_50042601_5_dialog_content = "무사해서 다행이야. 일단 호텔로 돌아가자.",
  ui_story_5004_50042601_6_dialog_content = "베릴이 꾼 꿈은 나랑 라파엘, 그리고 콜로서스에 있는 다른 오로리안들이\n힘을 모아서 어떻게든 해결할 수 있을 거야.",
  ui_story_5004_50042601_7_dialog_content = "맞아. 우리 제네비브도 연줄이 많으니까 반드시 도와줄 거라고.",
  ui_story_5004_50042601_8_dialog_content = "하아? 갑자기 날 끼워 넣지 말아줄래? 이번엔 그냥 아는 사이도 됐겠다\n싸움만 도와줬을 뿐이니까.",
  ui_story_5004_50042601_9_dialog_content = "...쳇, 알겠어. 아는 사람 중에 광물 연구에 정통한 녀석이 하나 있어.\n돌아가면 한번 물어볼게.",
  ui_story_5004_50042601_10_dialog_content = "그럼 서둘러 호텔로 돌아가자. 그리고 바로 백야성으로 가는 거야.",
  ui_story_5004_50042601_11_dialog_content = "보나시외, 길 안내 좀 부탁할게.",
  ui_story_5004_50042601_12_dialog_content = "보나시외?",
  ui_story_5004_50042601_13_dialog_content = "잠시만요. 여기 버튼이 하나 있는데요?",
  ui_story_5004_50042601_14_dialog_content = "에잇.",
  ui_story_5004_50042601_15_dialog_content = "뭐야! 눈부셔... 여긴 어디지?",
  ui_story_5004_50042601_16_dialog_content = "(주변의 광경... 왠지 본 기억이 있는 것 같은데? 내 착각인가?)",
  ui_story_5004_50042601_17_dialog_content = "PlayerName, 큰일이야! 오던 길이 막혔어!",
  ui_story_5004_50042601_18_dialog_content = "뭐?",
  ui_story_5004_50042601_19_dialog_content = "안 돼, 열리질 않아.",
  ui_story_5004_50042601_20_dialog_content = "시설... 봉쇄... <size=35>시스템을...</size> <size=33>재가동하십시오...</size>",
  ui_story_5004_50042601_21_dialog_content = "...?",
  ui_story_5004_50042601_22_dialog_content = "다들 이 문 여는 거 좀 도와줘!",
  ui_story_5004_50042601_23_dialog_content = "역시 안 되네. 꿈쩍도 안 해. 공격도 안 통하고.",
  ui_story_5004_50042601_24_dialog_content = "PlayerName, 여기 왠지 콜로서스 안이랑 비슷하지 않아?",
  ui_story_5004_50042601_25_dialog_content = "확실히 좀 비슷해. 근데 말이 안 되잖아...\n맞다, 보나시외는? 어디 간 거지?",
  ui_story_5004_50042601_26_dialog_content = "어디로~ 어디로 갔을까~♪",
  ui_story_5004_50042601_27_dialog_content = "내 마음~ 내 사랑~ 내 모든 꿈~♪",
  ui_story_5004_50042601_28_dialog_content = "이 성가신 암귀들이 대체 어디에 숨긴 걸까~♬",
  ui_story_5004_50042601_29_dialog_content = "앗! <size=45>보물을 발견했네!</size>",
  ui_story_5004_50042601_29X1_dialog_content = "어라? 당신들이 왜 여기 있죠?",
  ui_story_5004_50042601_29X2_dialog_content = "쉿...! 밖에 있는 오로리안한테 들리겠어!",
  ui_story_5004_50042601_29X3_dialog_content = "지금 직접 악장을 구해서 보나시외 양에게 전하려던 참이었습니다.",
  ui_story_5004_50042601_29X4_dialog_content = "네? 그 말은 그럼 이 안에 악장이 있다는 건가요?",
  ui_story_5004_50042601_29X5_dialog_content = "그래. 반드시 그 아이테르한테...",
  ui_story_5004_50042601_29X6_dialog_content = "알고 있다니까요. 아이테르가 봉인을 풀게 만들라고 말이죠.\n잘 기억하고 있어요.",
  ui_story_5004_50042601_29X7_dialog_content = "이걸로 악장의 뒷부분도 손에 넣었네요...\n그럼 당신들은... 여기서 좀 쉬고 계시죠...",
  ui_story_5004_50042601_29X8_dialog_content = "조심하세요! 펭그그 님!",
  ui_story_5004_50042601_29X9_dialog_content = "<color=#e8d9bb>쾅── 콰광──</color>",
  ui_story_5004_50042601_29X10_dialog_content = "자, 이제 안 보이는 구석으로 옮겨두면... 으쌰...! 이걸로 완벽해요!",
  ui_story_5004_50042601_30_dialog_content = "<size=45>PlayerName 씨~ 아직 거기 계신가요?</size>",
  ui_story_5004_50042601_31_dialog_content = "문이 잠겨서 갇혀있어! 어디 갔었어?",
  ui_story_5004_50042601_32_dialog_content = "일단 이쪽으로 오세요. 여기 <color=#FFB400>재미있는 물건</color>이 있거든요~",
  ui_story_5004_50042601_33_dialog_content = "이게 뭐야?",
  ui_story_5004_50042601_34_dialog_content = "이거 왠지... <color=#FFB400>아이테르가 만든 것</color> 같은데?",
  ui_story_5004_50042601_35_dialog_content = "역시 그렇죠? 당신이라면 이게 뭔지 알 거라고 생각했어요.",
  ui_story_5004_50042601_36_dialog_content = "아이테르가 만든 물건이 있고, 건물도 콜로서스 내부와 비슷하다면...\n설마 우리 지금 콜로서스 안에 있는 거야?",
  ui_story_5004_50042601_37_dialog_content = "그런 건 몰라요~ 전 그저 지극히 평범한 음악가 겸,\n이번 행사의 주최자일 뿐이니까요.",
  ui_story_5004_50042601_38_dialog_content = "우리의... 후손...",
  ui_story_5004_50042601_39_dialog_content = "(또 시작이야...)",
  ui_story_5004_50042601_40_dialog_content = "PlayerName~ 한번 감응해 보시겠어요?",
  ui_story_5004_50042601_41_dialog_content = "PlayerName, 뭔가 느낌이 안 좋아.",
  ui_story_5004_50042601_42_dialog_content = "어차피 우린 이미 여기 갇혀 있잖아... 시도하는 수밖에 없지 않을까?",
  ui_story_5004_50042601_43_dialog_content = "응... 대신 꼭 조심해.",
  ui_story_5004_50042601_44_dialog_content = "우리의... 후손이여...",
  ui_story_5004_50042601_45_dialog_content = "<color=#FFB400>「악장」</color>을 가지고 가더라도... 절대로...",
  ui_story_5004_50042601_46_dialog_content = "그것을... 깨워서는... 안 된다...",
  ui_story_5004_50042601_47_dialog_content = "그것이... 또다시... 대지를 가라앉히게 만들 순... 없다...",
  ui_story_5004_50042601_48_dialog_content = "어이! 문이 열렸어!",
  ui_story_5004_50042701_49_dialog_content = "그래도 덕분에 열었잖아. 한참 걷어찼더니 다리가 저릴 지경이라고.",
  ui_story_5004_50042701_50_dialog_content = "보나시외, 상자에서 뭘 꺼낸 거야?",
  ui_story_5004_50042701_51_dialog_content = "무슨... 「악장」 같은 거야?",
  ui_story_5004_50042701_52_dialog_content = "네? PlayerName 씨도 이걸 알아보신 건가요?\n이건 제가 오랫동안 찾아 헤맸던 「신의 악장」 중 하나랍니다.",
  ui_story_5004_50042701_53_dialog_content = "(아까 들린 목소리가 말했던 게... 바로 이건가?)",
  ui_story_5004_50042701_54_dialog_content = "넌 「악장」이 여기 있는지 어떻게 알았던 거야?\n그리고 아까 그 암귀들은 어디서 온 건데?",
  ui_story_5004_50042701_55_dialog_content = "녀석들은 누가 봐도 그 「악장」을 지키고 있는 것처럼 보였어.",
  ui_story_5004_50042701_56_dialog_content = "휴, 역시 대단하시네요. 과연 아이테르답게 눈치가 빠른 건가요?",
  ui_story_5004_50042701_57_dialog_content = "맞아요. 전 암귀와 작은 거래를 하나 하고 있었어요.",
  ui_story_5004_50042701_58_dialog_content = "암귀와 거래를 했다고?!",
  ui_story_5004_50042701_59_dialog_content = "그게 어쨌다는 거죠? 진짜로 같이 일을 한 것도 아니고,\n저들을 대신해서 나쁜 짓을 한 것도 아닌걸요.",
  ui_story_5004_50042701_60_dialog_content = "전 그저 악보를 건네받는 대신, 해신제 경기의 진행을 도왔을 뿐이에요.",
  ui_story_5004_50042701_61_dialog_content = "해신제를...? 그럼 해신제 자체가 암귀의 음모였다는 거야?",
  ui_story_5004_50042701_62_dialog_content = "그건 저도 모르죠. 제게 가장 중요한 건 제 머릿속에서 들리는 목소리가\n인도하는 대로 이 악장을 구하는 것뿐이에요.",
  ui_story_5004_50042701_63_dialog_content = "...너 머리가 어떻게 된 거 아냐? 아니, 확실히 문제가 있어!",
  ui_story_5004_50042701_64_dialog_content = "그럼 당신이 원하는 걸 손에 넣었으니, 이제 뭘 할 생각인데?\n계속해서 암귀와 협력할 거야?",
  ui_story_5004_50042701_65_dialog_content = "협력이 아니라니까요! 그저 이용했을 뿐이라구요.\n그리고 이 악장은 PlayerName 씨한테 드릴 거예요.",
  ui_story_5004_50042701_66_dialog_content = "나한테 준다고? 그렇게 어렵게 구하려던 걸 왜 나한테 주는데?",
  ui_story_5004_50042701_67_dialog_content = "사실 이게 바로 이번 해신제에서 준비한 <color=#FFB400>「궁극의 상품」</color>이거든요.",
  ui_story_5004_50042701_68_dialog_content = "게다가 여러분에게 이 일을 숨긴 것도 사실이니까,\n그에 대한 사과의 뜻이라고 생각해 주세요. 대신 연주부터 한 뒤에 드릴게요.",
  ui_story_5004_50042701_69_dialog_content = "그거 왠지... 모두가 열심히 딴 과일을 네가 먼저 맛보고 주는 것 같잖아.",
  ui_story_5004_50042701_70_dialog_content = "후훗, 어차피 여러분은 모두 동료잖아요. 자, 보세요──",
  ui_story_5004_50042701_71_dialog_content = "어라? 똑같은 게 하나 더 있었잖아?!",
  ui_story_5004_50042701_72_dialog_content = "당연하죠. 이 둘을 합쳐야 완전한 악장이 완성되거든요.",
  ui_story_5004_50042701_73_dialog_content = "어라...?",
  ui_story_5004_50042701_74_dialog_content = "뭐야... 이게 끝인가요? 그냥 한번 반짝인 게 전부라구요?",
  ui_story_5004_50042701_75_dialog_content = "뭐가 어떻게 된 거야...?",
  ui_story_5004_50042701_76_dialog_content = "이 안에서... 어떤 에너지가 억눌려 있는 게 느껴져.",
  ui_story_5004_50042701_77_dialog_content = "(역시 안 되는 건가요... 그럼 그 <color=#FFB400>생쥐 녀석</color>이\n말한 대로 해보는 수밖에 없겠네요.)",
  ui_story_5004_50042701_78_dialog_content = "PlayerName 씨, 당신이 해보세요! 이 악장과 감응해보는 거예요!",
  ui_story_5004_50042701_79_option_content = "안 돼.",
  ui_story_5004_50042701_80_dialog_content = "암귀랑 거래해서 얻은 물건 같은 걸 만지고 싶진 않아!",
  ui_story_5004_50042701_81_dialog_content = "알겠어요! 이번뿐이라구요! 다시는 암귀와 거래하지 않겠다고 맹세할게요!",
  ui_story_5004_50042701_82_option_content = "뭐, 부탁한다면야...",
  ui_story_5004_50042701_83_dialog_content = "아니, 역시 안 되겠어!",
  ui_story_5004_50042701_84_dialog_content = "이건 위험한 물건이라고 내 직감이 말해주고 있어!",
  ui_story_5004_50042701_85_dialog_content = "여러분 모두 여기 같이 있는데 뭐가 위험하겠어요? 부탁드릴게요!",
  ui_story_5004_50042701_86_option_content = "휴, 알겠어.",
  ui_story_5004_50042701_87_dialog_content = "근데 방금 어떤 목소리가 들렸단 말이야. 왠지 이 봉인을 풀면\n안 된다고 했던 것 같아.",
  ui_story_5004_50042701_88_dialog_content = "잘못 들은 게 분명해요! 제발 부탁이에요!",
  ui_story_5004_50042701_89_dialog_content = "그럼 일단 맹세해. 다시는 암귀와 거래하지 않겠다고.",
  ui_story_5004_50042701_90_dialog_content = "네, 물론이죠. 맹세할게요. 다시는 안 그럴게요!",
  ui_story_5004_50042701_91_dialog_content = "......",
  ui_story_5004_50042701_92_option_content = "(감응을 시도한다)",
  ui_story_5004_50042701_93_dialog_content = "성공했나...?",
  ui_story_5004_50042701_94_dialog_content = "...대단해요.",
  ui_story_5004_50042701_95_dialog_content = "고마워요... PlayerName 씨...",
  ui_story_5004_50042701_96_dialog_content = "보나시외 씨...! 뭘 하려는 거야?!",
  ui_story_5004_50042701_97_dialog_content = "아아... 이 얼마나 아름다운가요... 그저 봉인이 풀린 것만으로도\n벌써 그 부름을 느낄 수 있어요...",
  ui_story_5004_50042701_98_dialog_content = "미안해요... PlayerName 씨...",
  ui_story_5004_50042701_99_dialog_content = "제가 이곳에 있는 것... 그리고 제 존재의 의미는...\n오직 지금 이 순간, 이 신의 악장을 연주하기 위해서거든요!",
  ui_story_5004_50042701_100_dialog_content = "뭐야... 이 불길한 힘은?!",
  ui_story_5004_50042701_101_dialog_content = "보나시외!",
  ui_story_5004_50042701_102_dialog_content = "아하하하하!",
  ui_story_5004_50042701_103_dialog_content = "아아! 얼마나 아름다운 선율인가요! 너무나도 아름다워요!",
  ui_story_5004_50042701_104_dialog_content = "안 돼... 힘을 전혀 쓸 수가 없어...",
  ui_story_5004_50042701_105_dialog_content = "다들 연주 소리를 듣지 마!",
  ui_story_5004_50042701_106_dialog_content = "어서 멈춰! 보나시외!",
  ui_story_5004_50042701_107_dialog_content = "공허의 악장을 모으는 건 머릿속의 목소리가 제게 준 가장 숭고한 사명이에요.",
  ui_story_5004_50042701_108_dialog_content = "이런 순간에 제게 멈추라 하시다니, 그건 무리인걸요~",
  ui_story_5004_50042701_112_dialog_content = "이게 보나시외의 힘인가...? 아니야, 저 악장에서\n계속해서 힘이 솟아나고 있어!",
  ui_story_5004_50042701_113_dialog_content = "너희들...! 저길 좀 봐!",
  ui_story_5004_50042701_114_dialog_content = "저게... 뭐야... 바닷속에서... 성이 솟아오른 거야?!",
  ui_story_5004_50042701_115_dialog_content = "말도 안 돼... 어째서... 저 성이...",
  ui_story_5004_50042701_116_dialog_content = "PlayerName 씨, 들리시나요? 무엇에도 얽매이지 않고.\n신마저 전율하는 이 멜로디...",
  ui_story_5004_50042701_117_dialog_content = "역시 아이테르답네요. 이처럼 아름답고 감동적인 소리를\n세상에 알리지 않고 독차지하려 하다니요.",
  ui_story_5004_50042701_118_dialog_content = "정말 대단해요! 아이테르에게 점점 더 관심이 생기는걸요!",
  ui_story_5004_50042701_119_dialog_content = "이것이 바로 진리의 소리... 신의 울림...",
  ui_story_5004_50042701_120_dialog_content = "지금 제 머릿속에서 끝없이 울려 퍼지고 있어요! PlayerName 씨!",
  ui_story_5004_50042701_121_dialog_content = "베릴, PlayerName, 정신 차려! 보나시외의 위쪽에서 뭔가가 빛나고 있어!",
  ui_story_5004_50042701_122_dialog_content = "운석이야! 엄청난 기세로 이쪽으로 날아오고 있어!",
  ui_story_5004_50042701_123_dialog_content = "운석이라니? 갑자기 무슨 말도 안 되는 소리야?!",
  ui_story_5004_50042701_124_dialog_content = "곧 우리한테 부딪히겠어! 다들 조심해!",
  ui_story_5004_50042701_125_dialog_content = "피의 수정!",
  ui_story_5004_50042701_126_dialog_content = "으윽!",
  ui_story_5004_50042701_127_dialog_content = "괜찮아?!",
  ui_story_5004_50042701_128_dialog_content = "괜찮아... 그냥 파도에 좀 맞았을 뿐이야. 베릴 덕분에 살았어...",
  ui_story_5004_50042701_129_dialog_content = "더 큰 녀석이 날아오고 있어!",
  ui_story_5004_50042701_130_dialog_content = "내가... 어떻게든 해볼게...",
  ui_story_5004_50042701_131_dialog_content = "(제길... 아무리 우리가 힘을 합쳐도 저런 커다란 운석을 막을 순 없다고...)",
  ui_story_5004_50042701_132_dialog_content = "설마 이대로...",
  ui_story_5004_50042701_133_dialog_content = "포기는 아직 일러. PlayerName──!",
  ui_story_5004_50042701_134_dialog_content = "뭐야?!",
  ui_story_5004_50042701_135_dialog_content = "자! 기계를 사랑하는 네 진실한 친구 플뢰르! 그리고 그의 친구 렉커 등장!",
  ui_story_5004_50042701_136_dialog_content = "PlayerName, 「레디젤 파워-게키간V 0호기」의 힘을 보여줄게!",
  ui_story_5004_50042701_137_dialog_content = "우오오오오오!",
  ui_story_5004_50042701_138_dialog_content = "시끄러워! 소리 지르지 마! 이 자식, 기계에 손만 대면\n평소보다 100배는 더 미쳐버린다니까!",
  ui_story_5004_50042701_139_dialog_content = "출력을 더 높여야겠어. 이 녀석이라면 할 수 있어!",
  ui_story_5004_50042701_140_dialog_content = "뭐? 그건 또 어느 레버인데? 에라, 모르겠다! 전부 올려버려!",
  ui_story_5004_50042701_141_dialog_content = "그래, 바로 이거야! 내 목숨을 불태우겠다아아──!",
  ui_story_5004_50042701_142_dialog_content = "어이, 이쪽에 계속 불이 들어오는데 무슨 뜻이야?",
  ui_story_5004_50042701_143_dialog_content = "그건 과부하 경고등이야!",
  ui_story_5004_50042701_144_dialog_content = "이게 켜지면 어떻게 되는데?",
  ui_story_5004_50042701_145_dialog_content = "30초 뒤면 폭발할 거야!",
  ui_story_5004_50042701_146_dialog_content = "레디젤 파워-게키간V, 나와 함께 끝까지 불태우는 거다아아아!",
  ui_story_5004_50042701_147_dialog_content = "운석의 궤도를 틀어버려!",
  ui_story_5004_50042701_148_dialog_content = "정면으로 받아치지 않아도 된다고!",
  ui_story_5004_50042701_149_dialog_content = "플뢰르!",
  ui_story_5004_50042701_150_dialog_content = "알겠어!",
  ui_story_5004_50042701_151_dialog_content = "운석 이 자시이익──!\n내 앞에서 <size=45>당장 꺼져버려어어어──!</size>",
  ui_story_5004_50042701_152_dialog_content = "(추, 추진기의 불꽃... 저거 장난 아니잖아!)",
  ui_story_5004_50042701_153_dialog_content = "PlayerName, 성공했어! 운석의 방향이 틀어졌어!",
  ui_story_5004_50042701_154_dialog_content = "이대로 괜찮은 거야?! 내 로봇 지식으로 봤을 때 저건 곧 과부하로 해체될 거라구!",
  ui_story_5004_50042701_157_dialog_content = "PlayerName, 멍하니 있지 말고 해변을 벗어나!",
  ui_story_5004_50042701_158_dialog_content = "파도가 밀려오고 있어!",
  ui_story_5004_50042701_159_dialog_content = "제길! 보나시외 때문에 다리 힘이 풀려버렸어!",
  ui_story_5004_50042701_160_dialog_content = "PlayerName, 내 손 잡아!",
  ui_story_5004_50042701_161_dialog_content = "안 되겠어! 늦었어──!",
  ui_story_5004_50042701_162_dialog_content = "PlayerName! 다들 괜찮아?",
  ui_story_5004_50042701_163_dialog_content = "이...이게 바로... 아이테르의 기술을 결합했다는 그거야...?",
  ui_story_5004_50042701_164_dialog_content = "그래! 아이테르의 기술을 내 로봇공학에 접목시켜 만든 최강의 로봇이야!",
  ui_story_5004_50042701_165_dialog_content = "근데 아이테르의 기술을 활용한 부분은 아까 운석을 밀어낼 때 손상돼 버렸어.",
  ui_story_5004_50042701_166_dialog_content = "그 파격적인 추진기 말이지...",
  ui_story_5004_50042701_167_dialog_content = "자! 오늘 일로 일루미나도 백야성도\n전부 이 렉커 님한테 큰 빚을 진 셈이잖아?",
  ui_story_5004_50042701_168_dialog_content = "그럼 다음번 레디젤 렌치의 대장을 뽑을 때 나한테\n한 표 주는 거 잊지 말라고! 으하하하하!",
  ui_story_5004_50042701_169_dialog_content = "렉커, 이 녀석... 뭐, 됐어... 그것보다 보나시외는?",
  ui_story_5004_50042701_170_dialog_content = "하아~ 정말 상쾌하네요! 끝내주는 기분이에요!",
  ui_story_5004_50042701_171_dialog_content = "으앗! 또 어디서 튀어나온 거냐고!",
  ui_story_5004_50042701_172_dialog_content = "계속 옆에 있었는걸요. 아까 파도가 밀려올 때 여러분과 함께 필사적으로 도망쳤어요.\n그저 다들 저한테 신경을 못 썼을 뿐이죠.",
  ui_story_5004_50042701_173_dialog_content = "자, 이 악장, 받으세요.",
  ui_story_5004_50042701_174_dialog_content = "뭐야? 이렇게 쉽게 그냥 주겠다고? 또 무슨 꿍꿍이라도 있는 건 아니겠지...",
  ui_story_5004_50042701_175_dialog_content = "그런 건 없어요. 제 목적은 악장을 연주하는 것, 그게 다였으니까요.",
  ui_story_5004_50042701_176_dialog_content = "게다가 한 번의 연주로 이미 제 영혼에 새겨졌거든요.\n이 악장은 이제 그냥 껍데기일 뿐, 제겐 쓸모가 없어요.",
  ui_story_5004_50042701_177_dialog_content = "원래 아이테르의 물건이었으니까, 당신이 가지는 게 합당하기도 하고 말이죠.",
  ui_story_5004_50042701_178_dialog_content = "걱정하지 마세요~ 이제 다시는 연주하지 않을 테니까요.\n그러니까 용서해 주시면 안 될까요? 후훗~",
  ui_story_5004_50042701_179_dialog_content = "(이 녀석... 이렇게 얼렁뚱땅 넘어갈 생각인가...?)",
  ui_story_5004_50042701_180_dialog_content = "이런 위험한 물건은 반드시 우리가 관리해야 돼.",
  ui_story_5004_50042701_181_dialog_content = "이대로 내버려 둔다면 나쁜 녀석에게 또 이용당할지도 몰라.",
  ui_story_5004_50042701_182_dialog_content = "그것도 그렇네... 그럼 받아둘게. 대신 우릴 속인 걸 용서한 건 아냐!",
  ui_story_5004_50042701_183_dialog_content = "일단 암귀와 무슨 거래를 했던 건지부터 하나도 빼놓지 말고 똑똑히 말해!",
  ui_story_5004_50042801_E1_dialog_content = "정말 이게 전부라니까요. 제가 아는 건 이미 다 얘기했어요! 맹세할게요!",
  ui_story_5004_50042801_E2_dialog_content = "음... 그럼 넌 진짜로 그저 악장을 손에 넣으려고\n녀석들이 해신제를 개최하는 걸 도왔다는 거지?",
  ui_story_5004_50042801_E3_dialog_content = "그래요! 진짜라구요!",
  ui_story_5004_50042801_E4_dialog_content = "알겠어...",
  ui_story_5004_50042801_E5_dialog_content = "왕이시여... 마침내... 깨어나시는군요...",
  ui_story_5004_50042801_E6_dialog_content = "...네? 당신을 깨운 「용사」를 직접 보고 싶으시단 말씀이신가요?",
  ui_story_5004_50042801_E7_dialog_content = "잠깐만, 너희 무슨 소리 안 들려...?\n뭔가 희미하게 무슨 소리가 들리는데...",
  ui_story_5004_50042801_E8_dialog_content = "알겠습니다... 얼마든지요... 후후훗...\n저들도 분명히 당신을 뵙기를 바라고 있을 거랍니다...",
  ui_story_5004_50042801_E9_dialog_content = "하지만 당신의 힘은 아직 완전하지 않아요...\n그러니 제가 도와드리겠습니다...",
  ui_story_5004_50042801_E10_dialog_content = "소리? 뭔가 머릿속에 연주 소리가 아직도 남아 있는 느낌이긴 한데...\n그리고 다크매터가 갑자기 강해진 것 같아.",
  ui_story_5004_50042801_E11_dialog_content = "이렇게 짙은 다크매터가... 갑자기 어디서 생겨난 거지?\n방금 전까지 전혀 못 느꼈는데?!",
  ui_story_5004_50042801_E12_dialog_content = "<color=#e8d9bb>「악장이 울려 퍼지고, 추구의 여정은 마침내 끝이 난다.\n무수한 별들을 불태우고, 모든 이에게 재앙과 분노를 선사하기 위해,\n이제 왕이 부활한다.」</color>",
  ui_story_5004_50042801_E13_dialog_content = "......",
  ui_story_5004_50042801_184_dialog_content = "크오오──!",
  ui_story_5004_50042801_185_dialog_content = "아까 싸우다가 도망쳤던 암귀인가?!",
  ui_story_5004_50042801_186_dialog_content = "아, 아니야... 이 녀석들...!",
  ui_story_5004_50042802_1_dialog_content = "아주 강해... 보통 암귀와는 달라.",
  ui_story_5004_50042802_2_dialog_content = "어디서 나타난 거지? 저런 모습의 암귀는 지금까지 본 적 없었어.",
  ui_story_5004_50042802_3_dialog_content = "그래도 쓰러트릴 수 있어서 다행이야. 이제 더는 나쁜 짓을 할 수 없을 거야.",
  ui_story_5004_50042802_4_dialog_content = "...아니, 이 녀석들은 분신일 뿐이야.",
  ui_story_5004_50042802_5_dialog_content = "아까 싸움 중에 느꼈어. 뭔가 거대한 힘이 저들을 조종하고 있어.",
  ui_story_5004_50042802_6_dialog_content = "그 힘의 근원이... 바로 저 「성」 안에 있어.",
  ui_story_5004_50042802_7_dialog_content = "(아까까지 이런저런 일에 정신이 팔려서 저 이상한 성을 잊어버릴 뻔했어.)",
  ui_story_5004_50042802_8_dialog_content = "(하지만 지금은 확실히 느껴져... 갈수록 더 강한 다크매터가 뿜어져 나오고 있어.)",
  ui_story_5004_50042802_9_dialog_content = "쳇... 역시 그 암귀들 짓이겠죠. 보기 좋게 한 방 먹은 모양이네요...",
  ui_story_5004_50042802_10_dialog_content = "어쩐지 순순히 저한테 악장을 준다 싶었어요...\n저와 PlayerName 씨의 힘을 이용해서 저걸 소환하려는 계획이었겠죠.",
  ui_story_5004_50042802_11_dialog_content = "해신제로 돈벌이를 하려던 것 말고도 이런 목적이 있었다니... 흥!",
  ui_story_5004_50042802_12_dialog_content = "역시 녀석들을 혼내주고 악장만 빼앗는 게 나을 뻔했어요.",
  ui_story_5004_50042802_13_dialog_content = "돈벌이?! 암귀한테 돈이 왜 필요한 건데?",
  ui_story_5004_50042802_14_dialog_content = "뭐라더라, 오로리안들이 돈을 쓰도록 만들어서, 다들 가난해지면\n돈을 번다고 일을 하느라 싸울 수 없게 될 거라나 뭐라나...",
  ui_story_5004_50042802_15_dialog_content = "전 악장에만 정신이 팔려서 다른 일은 그다지 신경 쓰질 않았어요.",
  ui_story_5004_50042802_16_dialog_content = "PlayerName, 저 성에 가서 적의 상황을 확인하는 게 좋겠어.",
  ui_story_5004_50042802_17_dialog_content = "카렌 말이 맞아. 내버려 두면 이 해변에 있는 모두가 위험해질 거야.\n어쩌면 그것보다 더 심각한 상황이 벌어질지도 몰라.",
  ui_story_5004_50042802_18_dialog_content = "기왕 여기까지 왔는데, 저런 암귀 따위한테 쫄아서 도망칠 순 없잖아?",
  ui_story_5004_50042802_19_dialog_content = "그래봤자 암귀일 뿐이야. 전부 잡아다 현상금이나 받으면 그만이라고.",
  ui_story_5004_50042802_20_dialog_content = "응... 나도 같이 가고 싶어... 저 성, 무척 신경 쓰여...",
  ui_story_5004_50042802_21_dialog_content = "베릴이 그렇다면 나도 갈래~",
  ui_story_5004_50042802_22_dialog_content = "뭘 쳐다봐? 해변의 안전을 지키는 게 보안 요원의 임무 아니겠어?",
  ui_story_5004_50042802_23_dialog_content = "그럼 「레디젤 파워-게키간V 0호기」로 성까지 데려다줄게!",
  ui_story_5004_50042802_24_dialog_content = "어쩔 수 없네요. 그럼 저도 제가 벌인 일에 책임을 져야겠죠.\n제가 가진 비장의 부품과 에너지원을 로봇 보급으로 제공할게요.",
  ui_story_5004_50042802_25_dialog_content = "그리고 감히 뻔뻔하게 절 이용한 암귀 녀석들을 제대로 혼내주자구요!",
  ui_story_5004_50042802_26_dialog_content = "좋아, 그럼 준비해 보자!",
  ui_story_5004_50042901_1_dialog_content = "플뢰르, 이 게키간V, 아직 버틸 수 있겠어?",
  ui_story_5004_50042901_2_dialog_content = "「레디젤 파워-게키간V 0호기」라고 불러줘!",
  ui_story_5004_50042901_3_dialog_content = "여기엔 콜로서스의 제트 엔진 기술을 도입했는데,\n아까 보나시외 양이 준 에너지원까지 보충했어!",
  ui_story_5004_50042901_4_dialog_content = "아무래도 이용당한 걸 복수하려고 단단히 벼른 모양이네...",
  ui_story_5004_50042901_5_dialog_content = "음...? 잠깐만! 콜로서스의 기술이라면...\n설마 스카이워커처럼 갑자기 동력이 꺼지거나 하진 않는 거지?!",
  ui_story_5004_50042901_6_dialog_content = "플뢰르! 조심해, 너무 높이 날면 안 돼!",
  ui_story_5004_50042901_7_dialog_content = "응? 왜?",
  ui_story_5004_50042901_8_dialog_content = "뭐야?!",
  ui_story_5004_50042901_9_dialog_content = "어이! 이거 왜 이러는 거야? 계기판 수치가 끝에서 끝까지 왔다 갔다 하잖아?!",
  ui_story_5004_50042901_10_dialog_content = "플뢰르! 왜 그래?",
  ui_story_5004_50042901_11_dialog_content = "괘, 괜찮아. 아하하하... 그냥 계기판의 수치에 조금 문제가 있는 것뿐이잖아?",
  ui_story_5004_50042901_12_dialog_content = "계기판만 문제인 게 맞아?!",
  ui_story_5004_50042901_13_dialog_content = "추락하는 것 같아! 역시 이 고철 덩어리를 믿는 게 아니었어!",
  ui_story_5004_50042901_14_dialog_content = "내 「레디젤 파워-게키간V 0호기」는 절대 추락하지 않는다고!",
  ui_story_5004_50042901_15_dialog_content = "진짜라고! 진짜로 추락하고 있잖아! 빨리 어떻게 좀 해 봐!",
  ui_story_5004_50042901_16_dialog_content = "수직 활공으로 성까지 날아가자! 다들 꽉 잡아!",
  ui_story_5004_50042901_17_dialog_content = "수직 활공 같은 소리하네... 수직 추락이겠지...",
  ui_story_5004_50042901_18_dialog_content = "당황하지 마! 괜찮을 거야! 우리 레디젤 렌치의 과학 기술을 믿어!",
  ui_story_5004_50042901_19_dialog_content = "<color=#e8d9bb>......</color>",
  ui_story_5004_50042901_20_dialog_content = "PlayerName.",
  ui_story_5004_50042901_21_dialog_content = "얼른 일어나, PlayerName.",
  ui_story_5004_50042901_22_dialog_content = "으, 머리야...",
  ui_story_5004_50042901_23_dialog_content = "바이스?",
  ui_story_5004_50042901_24_dialog_content = "정신이 들어? 한참 동안 기절해 있었어.",
  ui_story_5004_50042901_25_dialog_content = "여, 여긴 대체 어디야...? 우리 성으로 추락한 거 아니었어?",
  ui_story_5004_50042901_26_dialog_content = "모르겠어. 근데 여기... 정말 이상해.\n다크매터로 가득 차 있어서 숨도 쉬기 힘들 정도야.",
  ui_story_5004_50042901_27_dialog_content = "게다가 저기 공중에 떠 있는 그림들...\n마치 살아있는 것처럼 저마다 다르게 움직이고 있어...",
  ui_story_5004_50042901_28_dialog_content = "저 눈 그림 좀 보세요.",
  ui_story_5004_50042901_29_dialog_content = "빙글빙글 돌더니 저희를 계속 노려보고 있어요...\n정말 기분이 불편해지네요...",
  ui_story_5004_50042901_30_dialog_content = "베릴, 저기 저 그림 좀 봐. 레몬으로 저글링을 하고 있는 것 같은데?",
  ui_story_5004_50042901_31_dialog_content = "정말 그런 것 같네...",
  ui_story_5004_50042901_32_dialog_content = "PlayerName! 저기 저쪽 좀 봐!",
  ui_story_5004_50042901_33_dialog_content = "스카이워커잖아?! 어째서 여기 스카이워커가 있는 거지?",
  ui_story_5004_50042901_34_dialog_content = "보러 가봐야겠어.",
  ui_story_5004_50042901_35_dialog_content = "뭐야? 돌판이 알아서 발밑에 생기는데?",
  ui_story_5004_50042901_36_dialog_content = "스카이워커, 너야?",
  ui_story_5004_50042901_37_dialog_content = "이런, 아무리 가도 다가갈 수가 없잖아.",
  ui_story_5004_50042901_38_dialog_content = "PlayerName, 침착해.",
  ui_story_5004_50042901_39_dialog_content = "지금 여기서 무턱대고 움직이면 위험해.",
  ui_story_5004_50042901_40_dialog_content = "알겠어... 다들 뭔가 찾아낸 게 있어?",
  ui_story_5004_50042901_41_dialog_content = "우린 「성」으로 추락해 정신을 잃었어.",
  ui_story_5004_50042901_42_dialog_content = "그리고 눈을 떠보니 여기였어. 이건 분명히 성의 내부는 아냐...\n뭔가 특수한 공간이겠지...",
  ui_story_5004_50042901_43_dialog_content = "쳇, 귀찮게 됐네. 싸워서 해치우면 바로 돌아갈 수 있을 줄 알았는데.",
  ui_story_5004_50042901_44_dialog_content = "이런 곳에 갇혀서는 나갈 방법도 못 찾고 있잖아.",
  ui_story_5004_50042901_45_dialog_content = "다른 악장이 있는 것 같진 않네요.",
  ui_story_5004_50042901_46_dialog_content = "......",
  ui_story_5004_50042901_47_dialog_content = "베릴... 아직 버틸 수 있겠어? 내 어깨에 기대.",
  ui_story_5004_50042901_48_dialog_content = "음... 난 괜찮아... 고마워...",
  ui_story_5004_50042901_49_dialog_content = "사실 얘기해야 할 게 하나 있어...",
  ui_story_5004_50042901_50_dialog_content = "전에 내가 만든 모래성... 기억하지?",
  ui_story_5004_50042901_51_dialog_content = "맞다! 그 성... 그러고 보니 여기랑 엄청 비슷하잖아!",
  ui_story_5004_50042901_52_dialog_content = "설마 베릴은 여기가 어딘지 알고 있는 거야?",
  ui_story_5004_50042901_53_dialog_content = "모르겠어... 하지만 이 성은 계속 내 기억 속에 있었던 것 같아.",
  ui_story_5004_50042901_54_dialog_content = "어쩌면 내 머릿속에서 울리는 목소리도... 이곳과 관계가 있을 것 같아.",
  ui_story_5004_50042901_55_dialog_content = "다들 조심해... 여기는 다크매터뿐만 아니라...\n내겐 무척 익숙한 어떤 힘이 존재하는 것 같아...",
  ui_story_5004_50042901_56_dialog_content = "걱정할 거 없어, 꼬마 아가씨. 우리가 있으니까.",
  ui_story_5004_50042901_57_dialog_content = "경호 비용은 후불로 정산해도 좋아. 할인도 해줄 수 있다고~",
  ui_story_5004_50042901_58_dialog_content = "뭐야, 입만 열면 장사 얘기라니. 제니, 그래서는 전혀 귀족답지 않잖아.",
  ui_story_5004_50042901_59_dialog_content = "조용히 해. 분위기 좀 밝게 만들려고 이러는 거라고.",
  ui_story_5004_50042901_60_dialog_content = "암귀를 물리치려면 모두가 힘을 합쳐야 해.\n하긴, 너처럼 삐딱한 애가 뭘 알겠어?",
  ui_story_5004_50042901_61_dialog_content = "맞아요. 우리가 여기 온 건 암귀들을 쓰러트리기 위해서예요.",
  ui_story_5004_50042901_62_dialog_content = "지금은 비록 이런 이상한 공간에 갇혀 있지만, 머뭇거릴 시간은 없어요!",
  ui_story_5004_50042901_63_dialog_content = "응...!",
  ui_story_5004_50042901_64_dialog_content = "아무튼 주변을 좀 더 탐색해 보자... 제대로 보이는 게 없긴 하지만.",
  ui_story_5004_50042901_65_dialog_content = "일단 어느 한쪽으로만 쭉 가보자.",
  ui_story_5004_50042901_66_dialog_content = "응, 조심해.",
  ui_story_5004_50042901_67_dialog_content = "주변이 뭔가 달라지는 것 같지는 않아...",
  ui_story_5004_50042901_68_dialog_content = "게다가 스카이워커 말고도 이곳의 다른 그림들... 뭔가 익숙해 보여.",
  ui_story_5004_50042901_69_dialog_content = "저건 왠지 백야성의 첨탑 같은데...",
  ui_story_5004_50042901_70_dialog_content = "잠깐만... 저 그림... 설마!",
  ui_story_5004_50042901_71_dialog_content = "...이 가증스러운 놈들! 감히 어머님의 모습으로 날 자극하려 하다니!",
  ui_story_5004_50042901_72_dialog_content = "진정해, 카렌, 놈들 뜻대로 흔들려선 안 돼.",
  ui_story_5004_50042901_73_dialog_content = "설마 이 공간은... 우리 마음속을 비추는 건가?",
  ui_story_5004_50042901_74_dialog_content = "그럼 이 여자애 그림은...",
  ui_story_5004_50042901_75_dialog_content = "(갑자기 그림에 손을 대고 싶은 충동을... 참을 수가 없어...)",
  ui_story_5004_50042901_76_option_content = "(그림에 손을 댄다)",
  ui_story_5004_50042901_77_dialog_content = "...!",
  ui_story_5004_50042901_78_dialog_content = "(짙은 연기, 익숙한 비명소리... 전에 베릴과 감응했을 때 본 장면인가?!)",
  ui_story_5004_50042901_79_dialog_content = "미안해...",
  ui_story_5004_50042901_80_dialog_content = "아빠, 엄마... 미안해...",
  ui_story_5004_50042901_81_dialog_content = "PlayerName, PlayerName?",
  ui_story_5004_50042901_82_dialog_content = "바이스...",
  ui_story_5004_50042901_83_dialog_content = "갑자기 왜 울어? ...또 뭔가 감응했어?",
  ui_story_5004_50042901_84_dialog_content = "(방금 그건 베릴의 기억인가? 왜 갑자기 베릴의 기억이 보인 거지?)",
  ui_story_5004_50042901_85_dialog_content = "(그럼 저 여자애의 그림이 베릴이랑 관계가 있는 건가? 베릴의 부모님은...)",
  ui_story_5004_50042901_86_dialog_content = "(아니... 어쩌면 암귀가 일부러 날 혼란스럽게 만들려고 보여준 걸지도 몰라...\n확실해질 때까지는 말하지 않는 게 좋겠어.)",
  ui_story_5004_50042901_87_dialog_content = "아무것도 아냐... 또 뭔가 환각을 본 것 같아...\n아마 암귀 녀석들 짓이겠지.",
  ui_story_5004_50042901_88_dialog_content = "다들 저 그림들을 조심해. 우리 의식에 영향을 줄지도 모르니까.",
  ui_story_5004_50042901_89_dialog_content = "이게 다 뭐야... 뭐, 뭐야! 어째서?!",
  ui_story_5004_50042901_90_dialog_content = "응? 거기서 혼자 뭘 수군거리고 있어?",
  ui_story_5004_50042901_91_dialog_content = "헤에, 거기 두 그림 왠지 우리 어릴 적 모습이랑 비슷하네.\n근데 뭘 하고 있는 거지?",
  ui_story_5004_50042901_92_dialog_content = "오지 마!",
  ui_story_5004_50042901_93_dialog_content = "야! 갑자기 왜 태워버리는데? 아직 못 봤단 말이야.",
  ui_story_5004_50042901_94_dialog_content = "보긴 뭘 봐! 안 돼!",
  ui_story_5004_50042901_95_dialog_content = "크오오!",
  ui_story_5004_50042901_96_dialog_content = "어이, 암귀가 나타났어! 조심해!",
  ui_story_5004_50042901_97_dialog_content = "크르르! 크아아!",
  ui_story_5004_50042901_98_dialog_content = "이 녀석들 왠지 그림 속에서 나올 수 있는 모양이야! 다들 준비해!",
  ui_story_5004_50043001_1_dialog_content = "해치웠네... 이 녀석들, 해변에서 본 암귀보다 더 강한 것 같아.",
  ui_story_5004_50043001_2_dialog_content = "맞아. 확실히 그때보다 더 힘들었어.",
  ui_story_5004_50043001_3_dialog_content = "게다가 녀석들은 기껏해야 분신일 거야...\n여길 뒤덮은 다크매터가 조금도 약해지지 않았어.",
  ui_story_5004_50043001_4_dialog_content = "적의 본체도 찾을 수 없는 상황이라니, 이래 가지곤 곤란한데...",
  ui_story_5004_50043001_5_dialog_content = "여긴 정말 괴상해. 이런 상황은 나도 처음이야.",
  ui_story_5004_50043001_6_dialog_content = "제네비브, 모자에 달린 장식 좀 빌려줘.",
  ui_story_5004_50043001_7_dialog_content = "장식은 뭐에 쓰려고? 망가트리면 가만 안 둘 거야.",
  ui_story_5004_50043001_8_dialog_content = "에잇!",
  ui_story_5004_50043001_9_dialog_content = "야! 그걸 왜 던져?!",
  ui_story_5004_50043001_10_dialog_content = "윽! 아파! 이게 왜 위에서 나한테 떨어지는 건데?!",
  ui_story_5004_50043001_11_dialog_content = "...그럼 이 공간, 방향도 왜곡돼 있는 건가?",
  ui_story_5004_50043001_12_dialog_content = "카렌, 달의 고치를 던져서 시험해 볼래?",
  ui_story_5004_50043001_13_dialog_content = "달의 고치를 던지는 것보다 네가 활을 쏘는 게 좋지 않겠어?",
  ui_story_5004_50043001_14_dialog_content = "아, 그렇네...",
  ui_story_5004_50043001_15_dialog_content = "잠깐만! 그러다 화살이 나한테 날아오면 어떡해!",
  ui_story_5004_50043001_16_dialog_content = "괜찮아~ 라파엘이 있잖아! 화살이랑 미사일도 같이 쏘면 돼~",
  ui_story_5004_50043001_17_dialog_content = "그러지 좀 마! 다른 방법을 생각해보자!",
  ui_story_5004_50043001_18_dialog_content = "저기 입이 있는 그림이랑 이야기를 해볼까?",
  ui_story_5004_50043001_19_dialog_content = "됐어... 너무 징그럽잖아.",
  ui_story_5004_50043001_20_dialog_content = "왠지 다른 세계의 물건인 것 같아.",
  ui_story_5004_50043001_21_dialog_content = "저기...",
  ui_story_5004_50043001_22_dialog_content = "저건... 어떨까?",
  ui_story_5004_50043001_23_dialog_content = "또 아까 그 여자애 그림이잖아? 뒤에 있는 문을 가리키는 것 같은데?",
  ui_story_5004_50043001_24_dialog_content = "우리보고 들어가라는 건가?",
  ui_story_5004_50043001_25_dialog_content = "해볼 수밖에 없네. 뭔가 적의가 느껴지진 않아.",
  ui_story_5004_50043001_26_dialog_content = "근데... 이렇게 작은데 어떻게 들어가지?",
  ui_story_5004_50043001_27_option_content = "(손가락을 넣어본다)",
  ui_story_5004_50043001_28_dialog_content = "<color=#e8d9bb>딸깍.</color>",
  ui_story_5004_50043001_29_dialog_content = "어? 안에서 뭔가 스위치 같은 게 눌린 것 같은데?\n잠깐만, 뭐가 어떻게 된 거야?",
  ui_story_5004_50043001_30_dialog_content = "바닥이 작아지고 있어! 이러다 떨어지겠어!",
  ui_story_5004_50043001_31_dialog_content = "────!!",
  ui_story_5004_50043001_32_dialog_content = "기절해버렸어. 어떻게 처리하지?\n그 가루로 이렇게 무서운 「괴물」을 탄생시킬 줄이야...",
  ui_story_5004_50043001_33_dialog_content = "실험 데이터는 충분히 얻었어. 여기 놔두고 가자.",
  ui_story_5004_50043001_34_dialog_content = "일어나서 이 시체들을 보면 어떤 표정을 할지 궁금하네.",
  ui_story_5004_50043001_35_dialog_content = "이건 배신의 대가야.",
  ui_story_5004_50043001_36_dialog_content = "...가끔 넌 암귀 못지않게 잔인한 면이 있다니까.",
  ui_story_5004_50043001_37_dialog_content = "으윽!",
  ui_story_5004_50043001_38_dialog_content = "아파...",
  ui_story_5004_50043001_39_dialog_content = "다...다들 얼른 비켜...줘...!",
  ui_story_5004_50043001_40_dialog_content = "숨을 못... 쉬겠어...",
  ui_story_5004_50043001_41_dialog_content = "푸하아! 숨 막혀 죽는 줄 알았네...\n제일 먼저 건드렸다고 맨 밑에 깔리다니 너무 비참하잖아!",
  ui_story_5004_50043001_42_dialog_content = "헤헷, 덕분에 다들 살았어, PlayerName.",
  ui_story_5004_50043001_43_dialog_content = "그나저나, 그로누 선배가 하는 게임으로 치면 이제부터 스테이지2 시작이려나?",
  ui_story_5004_50043001_44_dialog_content = "무슨 뜻이야? 설마 새로운 적이 나타나는 건가...?",
  ui_story_5004_50043001_45_dialog_content = "어서 와. 멀리서 온 손님들!",
  ui_story_5004_50043001_46_dialog_content = "나타났어!",
  ui_story_5004_50043001_47_dialog_content = "내 성과 정원, 「꿈의 허상」에 온 걸 환영해.",
  ui_story_5004_50043001_48_dialog_content = "「꿈의 허상」? 네가 이곳 주인이야?",
  ui_story_5004_50043001_49_dialog_content = "응, 날 이곳의 여주인이라고 생각하면 돼.\n난 여기서 저 장난감들과 10년 넘게 살고 있었거든.",
  ui_story_5004_50043001_50_dialog_content = "너희들을 반겨주려고 준비한 「체스말」은 어땠어?",
  ui_story_5004_50043001_51_dialog_content = "이 목소리...!",
  ui_story_5004_50043001_52_dialog_content = "꿈에서 들었던 그 목소리야...",
  ui_story_5004_50043001_53_dialog_content = "그러니까 저 체스말 모양의 암귀들을 네가 만든 거라고?\n넌 왜 그런 모습이지?",
  ui_story_5004_50043001_54_dialog_content = "서두를 거 없어. 아이테르란 건 역시 소문대로 호기심이 무척 많구나.",
  ui_story_5004_50043001_55_dialog_content = "뭐, 오로리안들이 이곳에 안 오게 된지도 너무 오래됐거든.\n나랑 최대한 많이 말동무가 돼줬으면 해. 너무 빨리 죽어버리지 말라고.",
  ui_story_5004_50043001_56_dialog_content = "어디 보자, 이곳에서 살게 된 첫해에 남긴 일기를 다시 읽어보면\n질문에 답해줄 수 있을 것 같아...",
  ui_story_5004_50043001_57_dialog_content = "에? 어라? 왜 없지? 첫 번째 일기가 없잖아. 너네가 훔친 거 아냐?",
  ui_story_5004_50043001_58_dialog_content = "이런, 어떡하지? 일기가 없으면 손님한테\n내 특제 차랑 디저트를 줄 수도 없잖아!",
  ui_story_5004_50043001_59_dialog_content = "아니면... 너희들의 머리를 쪼개서 내 일기를 숨겼나 한번 찾아볼까?",
  ui_story_5004_50043001_60_dialog_content = "PlayerName, 이 녀석, 제정신이 아냐.",
  ui_story_5004_50043001_61_dialog_content = "이봐요! 쓸데없는 소리는 됐어요. 당신이 그 생쥐들을 시켜서 절 속인 거죠?!",
  ui_story_5004_50043001_62_dialog_content = "잠깐만, 섣불리 나서지 않는 게 좋겠어. 우린 이 장소에 대해 아무것도 모르잖아.\n일단 얘기부터 해보자.",
  ui_story_5004_50043001_63_option_content = "넌 누구야?",
  ui_story_5004_50043001_64_dialog_content = "나? ...나는... 어디 보자... 두 번째 일기의 표지에 뭐라고 쓰여 있었더라...",
  ui_story_5004_50043001_65_dialog_content = "나는 「위대한 학자! 잔혹한 처형자!」",
  ui_story_5004_50043001_66_dialog_content = "어머, 내가 이렇게 대단한 사람이었던 거구나!",
  ui_story_5004_50043001_67_dialog_content = "(계속 미친 척하는 건가...)",
  ui_story_5004_50043001_68_option_content = "「꿈의 허상」이 뭐야?",
  ui_story_5004_50043001_69_dialog_content = "바로 여기야! 어디 보자...\n「들어오는 자의 마음속 고통과 광기로 점철된 체스판」...",
  ui_story_5004_50043001_70_dialog_content = "내 여섯 번째 일기에 그렇게 적혀 있어.",
  ui_story_5004_50043001_71_dialog_content = "게다가 이곳은 「적막의 군주」가 잠든 곳이고,\n내가 그분께 「적막의 군주」를 부활시키겠다고 약속했던 곳이기도 해.",
  ui_story_5004_50043001_72_dialog_content = "(이곳의 다크매터를 생각하면 분명히 아주 강력한 암귀가 있는 게 분명해.\n설마 지금 말하는 「적막의 군주」가 그 암귀인가?)",
  ui_story_5004_50043001_73_option_content = "왜 이 성이 바다에서 떠오른 거지?",
  ui_story_5004_50043001_74_dialog_content = "좋은 질문이야.",
  ui_story_5004_50043001_75_dialog_content = "「이곳은 한때 위대한 도시였으나, 사악한 아이테르에 의해 봉인되었다.」",
  ui_story_5004_50043001_76_dialog_content = "「사악한 아이테르들은 그 대가를 치러 대부분이 살육당했다.」",
  ui_story_5004_50043001_77_dialog_content = "어머~ 이 「아이테르 쿠킹 레시피」엔 꽤 많은 정보가 적혀 있잖아?",
  ui_story_5004_50043001_78_dialog_content = "아이테르, 넌 어떤 간식을 좋아하니? 내가 널 원하는 모양으로 만들어 줄게.",
  ui_story_5004_50043001_79_dialog_content = "(아이테르한테 봉인됐다고?! 그럼 이 녀석이 악장에 대한\n보나시외의 집착을 이용해서 이번 음모를 꾸민 건가?)",
  ui_story_5004_50043001_80_dialog_content = "PlayerName, 저 녀석 헛소리를 굳이 들어줄 거 없어.",
  ui_story_5004_50043001_81_option_content = "(조금 더 지켜본다)",
  ui_story_5004_50043001_82_dialog_content = "방금 책이랑 일기를 몇 권 더 가져왔어. 그럼 같이 얘기를 더 해보자.",
  ui_story_5004_50043001_83_option_content = "이 녀석... 완전히 미친 것 같아...",
  ui_story_5004_50043001_84_dialog_content = "PlayerName, 공격하자. 저런 제정신도 아닌 녀석을 상대해봤자\n머리만 아플 뿐이야.",
  ui_story_5004_50043001_85_dialog_content = "에?! 안 돼. 공격하지 말아줘!",
  ui_story_5004_50043001_86_dialog_content = "그랬다간... 내가... 못 참고 너흴 죽여버릴지도 몰라!",
  ui_story_5004_50043001_87_dialog_content = "그렇게 쉽게 죽어버리면 안 되잖아. 겨우 여기까지 왔는데,\n더 많은 진실을 알고 싶지 않아?",
  ui_story_5004_50043001_88_dialog_content = "나랑 이야기하고 싶지 않은 거야? 폭력은 안 돼. 내가 디저트를 준비할게!",
  ui_story_5004_50043001_89_dialog_content = "...셋, 넷, 다섯, 여섯... 일곱 명 맞지? 지금 바로 준비할게!",
  ui_story_5004_50043001_90_dialog_content = "뭐야, 갑자기 가버렸잖아... 잠깐만, 우리 여덟 명 아니었어?",
  ui_story_5004_50043001_91_dialog_content = "보나시외 씨가 없어!",
  ui_story_5004_50043001_92_dialog_content = "거기 서! 보나시외를 어디로 데려간 거야!",
  ui_story_5004_50043001_93_dialog_content = "정말 우락부락한 사람이네... 그 애라면 다과회에 어울리는 장소로 보냈을 뿐이야.",
  ui_story_5004_50043001_94_dialog_content = "당장 놓아줘.",
  ui_story_5004_50043001_95_dialog_content = "너... 지금 나한테 명령하는 거야? 아하하하!\n우리 귀여운 손님이 지금 나한테 명령을 했어!",
  ui_story_5004_50043001_96_dialog_content = "다과회를 방해하는 무례한 녀석들...\n아, 안 돼. 죽이면 안 돼... 참자, 참아야 해!",
  ui_story_5004_50043001_97_dialog_content = "아, 맞다... 넌 백야성 사람이지? 너한테선 그 냄새가 나.",
  ui_story_5004_50043001_98_dialog_content = "오만하고 제멋대로인 데다가, 자신밖에 모르는 녀석들.",
  ui_story_5004_50043001_99_dialog_content = "지금 한 말들은 고스란히 돌려줄게. 백야성의 호위대장으로서──",
  ui_story_5004_50043001_100_dialog_content = "오로리안을 위협하는 암귀, 내가 심판하겠어!",
  ui_story_5004_50043001_101_dialog_content = "후훗...",
  ui_story_5004_50043001_102_dialog_content = "우후후훗...",
  ui_story_5004_50043001_103_dialog_content = "아하하하하하하──!",
  ui_story_5004_50043001_104_dialog_content = "멋진 대사야! 아주 멋져!",
  ui_story_5004_50043001_105_dialog_content = "귀여운 호위대장님, 더는 못 참겠어... 참을 수가 없다구!",
  ui_story_5004_50043001_106_dialog_content = "그렇게 놀고 싶다면... 내 장난감이 계속 놀아줄게!",
  ui_story_5004_50043001_107_dialog_content = "크오오──!",
  ui_story_5004_50043001_108_dialog_content = "적이다! 다들 조심해!",
  ui_story_5004_50043101_1_dialog_content = "멋진 실력이야, 호위대장 아가씨.",
  ui_story_5004_50043101_2_dialog_content = "너희가 싸우는 걸 보면서 차를 좀 마셨더니 기분이 한결 나아졌어.",
  ui_story_5004_50043101_3_dialog_content = "근데 너희 벌써 상처도 많아졌고, 무기를 다루는 움직임도 둔해졌네.",
  ui_story_5004_50043101_4_dialog_content = "키히힉... 오로리안의 힘은 겨우 그 정도인 거구나.\n내가 만든 장난감에 이렇게까지 애를 먹고 있다니 말이야.",
  ui_story_5004_50043101_5_dialog_content = "충고 하나 할게. 날 화나게 만들지 마. 멋대로 달려들어 죽어버리지도 말고.\n그러지 말고 나랑 조금 더 이야기를 하자. 아니면 좀 더 발버둥 쳐보든지.",
  ui_story_5004_50043101_6_dialog_content = "난 10여 년 동안 일기를 써왔어...\n하지만 이렇게 좋은 소재를 만난 건 처음이야...",
  ui_story_5004_50043101_7_dialog_content = "그러니까 좀 더... 좀 더 나랑 이야기를 나눠줘!",
  ui_story_5004_50043101_8_dialog_content = "이 자식... 대체 목적이 뭐야?",
  ui_story_5004_50043101_9_dialog_content = "목적? 글쎄... 연구는 이미 질렸거든.\n그럼 이번엔 미식가가 돼볼까?",
  ui_story_5004_50043101_10_dialog_content = "그래! 내가 가장 좋아하는 「아이테르 쿠킹 레시피」처럼,\n이번엔 「오로리안 쿠킹 레시피」를 써보는 거야!",
  ui_story_5004_50043101_11_dialog_content = "하아... 스으읍... 아, 안 돼... 생각만 해도... 너무 흥분돼서...\n또 못 참고 너흴 죽여버릴 것 같잖아!",
  ui_story_5004_50043101_12_dialog_content = "그럼 안 되지... 한번에 다 죽여버리면 재미가 없잖아.\n내가 오랫동안 준비해 온 다과회에 그분이 빠지시면 안 되지.",
  ui_story_5004_50043101_13_dialog_content = "「적막의 군주」, 내게 힘을 주시는 새로운 주인께서도\n너희들로 만든 디저트를 좋아하실 거야.",
  ui_story_5004_50043101_14_dialog_content = "그래! 너희한테 내 힘을 보여줄게. 공포와... 절망이...\n뭔지 느끼게 해줄게...",
  ui_story_5004_50043101_15_dialog_content = "그러면 너흰 더 맛있어질 테니까!",
  ui_story_5004_50043101_16_dialog_content = "뭐가 힘이라는 거야... 그냥 잔재주잖아!",
  ui_story_5004_50043101_17_dialog_content = "헛소리는 그만 집어치워, 암귀.",
  ui_story_5004_50043101_18_dialog_content = "네가 만든 이것들로는 그래봤자 잠깐 우리 발을 묶는 것밖에 못 해.",
  ui_story_5004_50043101_19_dialog_content = "의식이 없는 꼭두각시를 만들어 내고 제어하느라 너도 힘을 소모하고 있겠지.",
  ui_story_5004_50043101_20_dialog_content = "네 본체만 붙잡는다면 쓰러트릴 수 있어!",
  ui_story_5004_50043101_21_dialog_content = "그래. 확실히 나한테 그런 대단한 힘은 없어.\n하지만 그분에겐 있지.",
  ui_story_5004_50043101_22_dialog_content = "「백야성에는 분수도 모르고 암귀의 막강한 힘을 탐하는 자들이 많다.」",
  ui_story_5004_50043101_23_dialog_content = "「그들 중에는 암귀와 거래를 하거나, 심지어 자신의 신체나 목숨을 바쳐\n힘을 얻으려는 자도 있다.」",
  ui_story_5004_50043101_24_dialog_content = "어디 보자~ 이 책은 10여 년 전에 쓰인 거야.\n백야성은 지금도 이런 식이니?",
  ui_story_5004_50043101_25_dialog_content = "그런 반역자들을 지켜줘야 하는 건 어떤 기분이야? 거기 호위대장 아가씨,\n나한테 좀 들려주지 않을래?",
  ui_story_5004_50043101_26_dialog_content = "악마 같은 자식, 그런 말로 날 흔들 수 있다고 생각했다면 오산이야.",
  ui_story_5004_50043101_27_dialog_content = "헤에, 그래도 바보는 아닌 모양이네.\n역시 호위대장 정도면 실력만 가지고 된 건 아니겠지.",
  ui_story_5004_50043101_28_dialog_content = "사실 넌 진작부터 알고 있었던 거지? 백야성이 얼마나 썩어빠진 곳인지 말이야.",
  ui_story_5004_50043101_29_dialog_content = "아아, 영원히 함락되지 않는 도시... 우뚝 솟은 하얀 탑... 아하하하하!",
  ui_story_5004_50043101_30_dialog_content = "사람들에겐 희망의 영웅으로 보이지만~ 사실은 거짓으로 얼룩진 귀족들~",
  ui_story_5004_50043101_31_dialog_content = "남들 앞에선 구원자 행세지만, 뒤에선 서로 속고 속이는 위선자들이잖아.",
  ui_story_5004_50043101_32_dialog_content = "거짓투성이인 인간들 주제에~ 잘도 귀족이 돼서 우쭐대고 있네. 아하하하하!",
  ui_story_5004_50043101_33_dialog_content = "안 그래? 그렇지? 내 말이 틀렸어?!",
  ui_story_5004_50043101_34_dialog_content = "<color=#FFB400>베릴 고티에</color>!",
  ui_story_5004_50043101_35_dialog_content = "역시 날 알고 있었어... 대체 넌 누구야! 어떻게 날 아는 거야?",
  ui_story_5004_50043101_36_dialog_content = "고티에... 고티에! 고티에!",
  ui_story_5004_50043101_37_dialog_content = "물론 알다마다. 그리고 네 우스꽝스러운 가문도 알고 있다고!",
  ui_story_5004_50043101_38_dialog_content = "내 일기장엔 온통 네 가문의 이름이 쓰여 있어!",
  ui_story_5004_50043101_39_dialog_content = "네가 여기 온 건 그 몸에 흐르는 피와 죄를 씻기 위해서 아니었어?",
  ui_story_5004_50043101_40_dialog_content = "수정에 강력한 힘이 있다는 걸 알고 있었으면서...",
  ui_story_5004_50043101_41_dialog_content = "겁도 없이 사신을 길들이려 하다니, 얼마나 우습냐고!",
  ui_story_5004_50043101_42_dialog_content = "그건 순수하고 강력한 힘이야... 오직 파괴와 정복을 위해 존재하는 힘이라고!",
  ui_story_5004_50043101_43_dialog_content = "그 보잘것없는 백야성 녀석들의 즐거움을 위해 쓰일 힘이 아니란 말이야!",
  ui_story_5004_50043101_44_dialog_content = "어떻게... 우리 가문의 일까지 아는 건데...?",
  ui_story_5004_50043101_45_dialog_content = "내가 왜 알고 있냐고...? 어머! 기억 안 나? 그거 잘됐네!\n아, 아니지. 정말 불쌍하잖아?!",
  ui_story_5004_50043101_46_dialog_content = "불쌍해... 너무 불쌍하다고... 그러게 나처럼 일기라도 많이 써두지 그랬니.",
  ui_story_5004_50043101_47_dialog_content = "너한테는 특별히 디저트를 하나 더 준비해 줄게.\n네 옆에 있는 그 계집애로 만든 디저트를 말이야!",
  ui_story_5004_50043101_48_dialog_content = "라파엘한테 손대지 마!",
  ui_story_5004_50043101_49_dialog_content = "베릴...",
  ui_story_5004_50043101_50_dialog_content = "응? 그래! 알겠어! 그럼 안 건드릴게, 히힛...",
  ui_story_5004_50043101_51_dialog_content = "근데 내가 아무것도 안 하더라도, 고작 「체스말」 같은 네가 그 애를 지킬 수 있겠어?",
  ui_story_5004_50043101_52_dialog_content = "너희들의 진실한 감정을... 내가 빠짐없이 책으로 써줄게!",
  ui_story_5004_50043101_53_dialog_content = "너흰 여기서 죽은 뒤에도 내 글 속에서 영원히 살게 될 거야!",
  ui_story_5004_50043101_54_dialog_content = "제목은 뭐라고 지을까? 「어리석고 순진한 사랑」? 「체스말의 애가」?",
  ui_story_5004_50043101_55_dialog_content = "너희 오로리안은 정말 우스울 정도로 모두 어리석구나.\n하나씩 붙잡아 고문해서 책을 써주고 싶다니까!",
  ui_story_5004_50043101_56_dialog_content = "아! 맞아! 너흴 디저트로 만들어서 홍차와 함께 즐길 거야!",
  ui_story_5004_50043101_57_dialog_content = "그럼 너희들의 생애를 읽으면서, 너희들의 피와 살을 맛볼 수 있겠지...",
  ui_story_5004_50043101_58_dialog_content = "참, 「바보 같은 음악가」라는 제목을 생각해 둔 그 웃기는 오로리안 말인데.",
  ui_story_5004_50043101_59_dialog_content = "그 녀석, 그저 연주 한 번을 하겠다고...\n아무것도 모르는 상황에서 봉인을 풀었잖아?",
  ui_story_5004_50043101_60_dialog_content = "그리고 난 암귀를 호텔에 잠입시켜 <color=#FFB400>장치를 설치</color>했고...\n해신제를 개최해서 호텔 주변에 있는 모든 오로리안의 루미나를 흡수했어.",
  ui_story_5004_50043101_61_dialog_content = "그러니까 「적막의 군주」의 부활엔 너희도 큰 도움이 됐다는 얘기야!",
  ui_story_5004_50043101_62_dialog_content = "역시 난 완벽한 전략가... 전술가... 음모자... 그랜드마스터...\n아, 참, 그리고 문학가야!",
  ui_story_5004_50043101_63_dialog_content = "역시 미친 게 확실해... 넌 여기 너무 오랫동안 틀어박혀 있어서\n정신이 이상해진 거라고!",
  ui_story_5004_50043101_64_dialog_content = "어머... 잘도 그렇게... 기록할 만한 가치가 있는 말을 했네!",
  ui_story_5004_50043101_65_dialog_content = "내 손으로 직접 널 디저트로 만들어버리기 전에,\n내 새로운 장난감들한테 죽지 말아줘. 알겠지?",
  ui_story_5004_50043101_66_dialog_content = "그러니까 꼭 힘을 내줘~",
  ui_story_5004_50043201_1_dialog_content = "하아... 하아...",
  ui_story_5004_50043201_2_dialog_content = "PlayerName... 또 코피가 나고 있어... 너무 무리하지 마.",
  ui_story_5004_50043201_3_dialog_content = "난 괜찮아... 그냥 조금 지쳤을 뿐이야...",
  ui_story_5004_50043201_4_dialog_content = "(이렇게 계속 싸우니까... 정신에 부담이 너무 커...)",
  ui_story_5004_50043201_5_dialog_content = "다 끝났어? 마침 다음 디저트를 즐기려던 참이었는데.",
  ui_story_5004_50043201_6_dialog_content = "이번 전투에 대한 평가는...",
  ui_story_5004_50043201_7_dialog_content = "「애들 싸움 같은 지휘와 할머니가 지팡이를 휘두르는 듯한 움직임」이랄까.",
  ui_story_5004_50043201_8_dialog_content = "그거 알아? 너흰 점점 더 느려지고 있어.\n이번에 난 벌써 차를 네 잔이나 마시고 디저트도 하나 먹었다니까.",
  ui_story_5004_50043201_9_dialog_content = "제길... 이 자식! 지금 장난해?!",
  ui_story_5004_50043201_10_dialog_content = "이딴 분신만 가지고 우리랑 싸우는 게 무슨 의미가 있어?!",
  ui_story_5004_50043201_11_dialog_content = "정정당당하게 나와서 싸우란 말이야!",
  ui_story_5004_50043201_12_dialog_content = "아하하하! 나보고 너흴 상대하라고?\n이런 불쌍한 장난감들 상대로도 힘들어하는 너희를?",
  ui_story_5004_50043201_13_dialog_content = "난 아직 너희에 대해 조금 더 알고 싶어.\n정성껏 만든 음식이야말로... 가장 맛있으니까.",
  ui_story_5004_50043201_14_dialog_content = "게다가 그분의 힘은 아직 완벽하게 부활하지 않았어.\n그러니까 너희랑 좀 더 얘기할 시간은 있을 거야.",
  ui_story_5004_50043201_15_dialog_content = "어라? 첫 번째 일기가 여기 있었네. 어디 뭐가 쓰여 있는지 볼까...",
  ui_story_5004_50043201_16_dialog_content = "풉...푸하하하하! 이거 정말 보물이네! 다들 이리와. 얼른! 내가 읽어줄 테니까!",
  ui_story_5004_50043201_17_dialog_content = "크흠, 흠흠! 일단 목부터 좀 풀고.",
  ui_story_5004_50043201_18_dialog_content = "고티에 가문의 아가씨, 네 불쌍한 머리로는 아직도 답을 못 찾은 모양이지?",
  ui_story_5004_50043201_19_dialog_content = "누가 이렇게 수정에 대해 잘 알고...\n누가 널 꿈속에서 부를 수 있는 걸까?",
  ui_story_5004_50043201_20_dialog_content = "...역시... 그랬어... 너, 피로스 가문의 유일한 생존자...\n암귀와 결탁한 캐롤라인 피로스! 맞지?!",
  ui_story_5004_50043201_21_dialog_content = "아하하하하! 정답이야!",
  ui_story_5004_50043201_22_dialog_content = "아, 이런, 안 되겠어. 오로리안 시절의 이름을 들으니까 너무 부끄럽잖아!",
  ui_story_5004_50043201_23_dialog_content = "역시 일기 같은 건 남한테 읽어줄 만한 게 못 된다니까.",
  ui_story_5004_50043201_24_dialog_content = "아니지, 그래도 너희한테 들려주고 싶어! 다들 진지하게 잘 들어!",
  ui_story_5004_50043201_25_dialog_content = "너도 오로리안이었다고?",
  ui_story_5004_50043201_26_dialog_content = "암귀에 굴복해 영혼을 판 녀석이 여기도 있었네.",
  ui_story_5004_50043201_27_dialog_content = "히히힛... 그래, 내가 오로리안이었다는 것도 잊어버릴 뻔했지 뭐야...",
  ui_story_5004_50043201_28_dialog_content = "대신 일기엔 암귀가 된 뒤로 얼마나 자유롭고 즐거웠는지 감상이 잔뜩 적혀 있어.",
  ui_story_5004_50043201_29_dialog_content = "백야성에 있을 때보다 몇 배는 더 재밌다니까!",
  ui_story_5004_50043201_30_dialog_content = "자, 그럼 다시 본론으로 돌아가 볼까? 아까 말했다시피,\n우리 가문은 너희 가문과는 달리 수정을 이용하려 했어...",
  ui_story_5004_50043201_31_dialog_content = "이토록 잔혹하고 끔찍한 힘을 무기로 안 쓴다면 말이 안 되잖아!",
  ui_story_5004_50043201_34_dialog_content = "원래 이건 백야성이 암귀를 물리칠 수 있는 강력한 무기가 될 수도 있었어.\n모든 암귀를 끝없는 어둠 속으로 돌려보낼 수도 있었다고!",
  ui_story_5004_50043201_35_dialog_content = "근데 나약한 너희 가문이 그걸 백야성의 성주한테 일러바친 거야.\n아아아! 여기까지 읽고 나니 또 화가 나잖아!",
  ui_story_5004_50043201_36_dialog_content = "너희 피로스 가문은 그때도 이미 몰락한 오로리안을 잡아서\n수정으로 인체 실험을 하고 있었어.",
  ui_story_5004_50043201_37_dialog_content = "동족의 몸을 실험에 사용하다니, 제정신이 아니라고!",
  ui_story_5004_50043201_38_dialog_content = "휴, 내가 젊을 땐 확실히 수정 실험에 푹 빠져 있긴 했었지... 후후훗...",
  ui_story_5004_50043201_39_dialog_content = "근데 말이야. 내가 없었다면... 지금의 베릴도 없었을 거야...\n넌 내 자랑스러운 실험체라고...",
  ui_story_5004_50043201_40_dialog_content = "설마... 베릴이...",
  ui_story_5004_50043201_41_dialog_content = "......",
  ui_story_5004_50043201_42_dialog_content = "이 일기엔 너에 대한 내용이 아주 자세히 적혀 있어.\n좋아하는 음식이나 운동 같은 것도 말이야.",
  ui_story_5004_50043201_43_dialog_content = "그리고 잘 때는 뭘 끌어안고 자는지까지 하나도 빼놓지 않고 적혀 있다고.",
  ui_story_5004_50043201_44_dialog_content = "이 글을 쓴 사람이 널 얼마나 사랑하는지 느껴질 정도라니까.",
  ui_story_5004_50043201_45_dialog_content = "아! 맞다, 글쓴이는 나였지. 그럼 이건 미쳐버린 변태가\n순결한 소녀를 사랑하는 장면이라고 해야겠네.",
  ui_story_5004_50043201_46_dialog_content = "비록 불완전한 작품이지만, 그래도 내 실험에서 중요한 이정표가 됐었어.",
  ui_story_5004_50043201_47_dialog_content = "난 너한테 정말 아낌없이 사랑을 줬었거든~",
  ui_story_5004_50043201_48_dialog_content = "다크매터를 이용해서 만든 특수한 수정 가루...\n그게 지금도 네 몸속에서 성장하고 있겠지...",
  ui_story_5004_50043201_49_dialog_content = "그건 네 몸에 둥지를 틀고... 네 감정과 의지를 양분으로 삼고 무럭무럭 자라왔을 거야...",
  ui_story_5004_50043201_50_dialog_content = "그만해...",
  ui_story_5004_50043201_51_dialog_content = "하지만 그건 너무 불안정해... 푸히히힛! 드디어 여기까지 읽었네...\n이제부턴 제일 마음에 드는 부분이야!",
  ui_story_5004_50043201_52_dialog_content = "아아~ 네가 일으킨 아름다운 불길...\n네가 죽여버린 수많은 오로리안들의 비명 소리...",
  ui_story_5004_50043201_53_dialog_content = "그만하란 말이야──!",
  ui_story_5004_50043201_54_dialog_content = "이 자식! 까불지 마!",
  ui_story_5004_50043201_55_dialog_content = "키히힛... 그분이 날 부르고 계셔...",
  ui_story_5004_50043201_56_dialog_content = "잠깐만 기다려. 금방 다시 올 테니까.\n그 불타 죽은 오로리안들처럼 맛있는 음식으로 만들어 줄게.",
  ui_story_5004_50043201_57_dialog_content = "그만... 그만해. 그만, 그만, 그만! 그만──!",
  ui_story_5004_50043201_58_dialog_content = "베릴! 진정해!",
  ui_story_5004_50043201_59_dialog_content = "라파엘, 내가 감응해서 베릴의 감정을 진정시켜볼게!",
  ui_story_5004_50043201_60_dialog_content = "알겠어... 서둘러 줘... 너무 괴로워 보여...",
  ui_story_5004_50043201_61_dialog_content = "(광폭한 힘이 베릴의 몸속에서 꿈틀대는 게 느껴져.)",
  ui_story_5004_50043201_62_dialog_content = "(이건 절대 오로리안의 힘이 아니야. 하지만 다크매터와도 달라.)",
  ui_story_5004_50043201_63_dialog_content = "(어쩌면 정말 캐롤라인의 말처럼... 파멸을 상징하는 잔혹한 힘일지도 몰라.)",
  ui_story_5004_50043201_64_dialog_content = "(베릴은 계속 최선을 다해서 이 힘을 억눌러 왔어. 하지만 지금 캐롤라인의 자극 때문에...)",
  ui_story_5004_50043201_65_dialog_content = "(억제가 점점 더 약해지고 있어.)",
  ui_story_5004_50043201_66_dialog_content = "베릴...",
  ui_story_5004_50043201_67_dialog_content = "라파엘... 난 괜찮아... PlayerName, 고마워.",
  ui_story_5004_50043201_68_dialog_content = "미안해... 내 과거를 숨길 생각은 없었어...",
  ui_story_5004_50043201_69_dialog_content = "근데 캐롤라인한테 당한 실험 때문인지... 아니면 너무 고통스러워서\n본능적으로 기억을 떠올리지 않은 건지...",
  ui_story_5004_50043201_70_dialog_content = "전에 있었던 일의 기억들이 전부 흐릿했을 뿐이야...",
  ui_story_5004_50043201_71_dialog_content = "어렸을 때... 피로스 가문 사람한테 붙잡혀 갔던 건 생각이 나...",
  ui_story_5004_50043201_72_dialog_content = "아무것도 보이지 않는 방에 갇혀서... 나한테 억지로 그 수정 가루를 먹였어.",
  ui_story_5004_50043201_73_dialog_content = "그리고 내 몸은 마치 저주를 받은 것처럼... 항상 날 고통스럽게 만드는\n이 수정에서 하루도 벗어날 수 없게 됐어.",
  ui_story_5004_50043201_74_dialog_content = "그러다 나중에 알게 됐어... 피로스 가문은 이 수정을 가지고...\n오로리안을 무기로 개조하는 실험을 하고 있었던 거야...",
  ui_story_5004_50043201_75_dialog_content = "괜찮아... 베릴, 누구나 자신만의 과거가 있는 거니까.",
  ui_story_5004_50043201_76_dialog_content = "즐거운 기억은 함께 나누고, 나쁜 기억은 잊어버리면 돼.\n네가 새로운 삶을 시작하는 걸 탓할 사람은 아무도 없어.",
  ui_story_5004_50043201_77_dialog_content = "응? 난 전혀 상관없는데? 어차피 내 과거도 만만치 않게 끔찍하니까.",
  ui_story_5004_50043201_78_dialog_content = "괜히 창피하게 얘기 꺼내지나 마. 과거라면 나도 신경 안 써.",
  ui_story_5004_50043201_79_dialog_content = "우린 동료잖아. 전에 무슨 일이 있었든, 우린 지금의 널 믿어!",
  ui_story_5004_50043201_80_dialog_content = "지금 시급한 건 이런 끔찍한 죄를 지은 캐롤라인에게 심판을 내려서,\n다는 이런 참극이 되풀이되지 않게 하는 거야.",
  ui_story_5004_50043201_81_dialog_content = "나도 너희와 같은 생각이야.",
  ui_story_5004_50043201_82_dialog_content = "다들... 정말 고마워...",
  ui_story_5004_50043201_83_dialog_content = "캐롤라인 피로스... 한때는 백야성의 귀족이었으면서 일말의 명예조차 남아 있지 않아.",
  ui_story_5004_50043201_84_dialog_content = "암귀와 손잡는 것도 모자라서... 동족에게 그런 잔인한 짓을 하다니...",
  ui_story_5004_50043201_85_dialog_content = "그리고 계속 말하는 그 「적막의 군주」란 녀석...\n만약 그게 녀석이 말한 것처럼 그렇게 막강한 힘을 가지고 있다면...",
  ui_story_5004_50043201_86_dialog_content = "반드시 녀석이 깨어나는 걸 막아야 해.",
  ui_story_5004_50043201_87_dialog_content = "하지만 이 공간에서 어떻게 녀석의 본체를 찾아내지?",
  ui_story_5004_50043201_88_dialog_content = "저기... 아까 네가 나한테 감응했을 때...",
  ui_story_5004_50043201_89_dialog_content = "나도 어떤 곳에서 수정의 힘이 강하게 전해지는 걸 느꼈어...",
  ui_story_5004_50043201_90_dialog_content = "녀석들은 거기 있을지도 몰라...",
  ui_story_5004_50043201_91_dialog_content = "좋았어! 그럼 어서 가자!",
  ui_story_5004_50043201_92_dialog_content = "응, 아마 힘든 싸움이 될 거야.",
  ui_story_5004_50043201_93_dialog_content = "걱정하지 마... 베릴. 내가 그 녀석을 반드시 심판할 테니까!",
  ui_story_5004_50043201_94_dialog_content = "음... 끝나면 약속대로 백야성에 같이 가자.",
  ui_story_5004_50043201_95_dialog_content = "이 앞에 어떤 적이 기다리고 있든지... 절대 도망치지 않을 거야!",
  ui_story_5004_50043301_1_dialog_content = "어라? 여길 찾아낼 줄은 정말 몰랐는데?",
  ui_story_5004_50043301_2_dialog_content = "흠흠~ 「<color=#FFB400>알현실</color>에 온 걸 진심으로 환영해.\n이제 너희들의 새로운 왕 앞에 엎드릴 차례야.」",
  ui_story_5004_50043301_3_dialog_content = "「이게 바로 내가 수정의 힘으로 얻은 새로운 모습이야...\n베릴, 너와 같은 힘이라고.」",
  ui_story_5004_50043301_4_dialog_content = "「하지만 다른 점은... 넌 고작 실험체일 뿐이고,\n난 수정의 힘을 원하는 대로 다룰 수 있는 완전체라는 거지.」",
  ui_story_5004_50043301_5_dialog_content = "「그리고 이제 <color=#FFB400>적막의 군주</color>가 수정의 힘으로 되살아나고...\n다시 우리 앞에 군림할 거야.」",
  ui_story_5004_50043301_6_dialog_content = "흠흠~ 지금 대사는 너희들의 비참한 죽음을 기록할 추도문의 첫머리야.\n마음에 들어?",
  ui_story_5004_50043301_7_dialog_content = "<color=#e8d9bb>캐롤라인이 뒤로 손을 흔들자, 수정이 폭발해 분말로 변했고,\n이윽고 짙은 안개가 되어 적막의 군주에게 빨려 들어갔다.</color>",
  ui_story_5004_50043301_8_dialog_content = "......",
  ui_story_5004_50043301_9_dialog_content = "봤지? ...수정의 힘과 암귀는 이렇게 궁합이 잘 맞는다니까.",
  ui_story_5004_50043301_10_dialog_content = "예전의 난 이게 신께서 오로리안에게 내려주신 무기라고 착각했었어.\n지금 생각하면 정말 창피해서 어쩔 줄을 모르겠다니까!",
  ui_story_5004_50043301_11_dialog_content = "이것은 누가 뭐래도 「신」께서 암귀를 위해 주신 선물인데 말이야!",
  ui_story_5004_50043301_12_dialog_content = "네 헛소리는 이제 지겨워졌어.",
  ui_story_5004_50043301_13_dialog_content = "정정당당하게 싸워!",
  ui_story_5004_50043301_14_dialog_content = "드디어... 드디어... 히히힛... 키히히히히!\n이제 더는 너흴 죽이는 걸 참을 수 없게 됐어!",
  ui_story_5004_50043301_15_dialog_content = "빨리, 빨리빨리, 더 빨리! 더 고통스러워하고,\n더 절망해! 더 맛있어지는 거야!",
  ui_story_5004_50043302_1_dialog_content = "이런! 죽여도 끝이 없잖아!",
  ui_story_5004_50043302_2_dialog_content = "조무래기들이랑 시간 낭비하지 말라고... 하아아! 다 불타버려!",
  ui_story_5004_50043302_3_dialog_content = "끅... 크윽... 말도 안 돼... 내가...",
  ui_story_5004_50043302_4_dialog_content = "대단해... 머리에 바로 명중했잖아?! 얼굴의 빛이 사라지고 있어!",
  ui_story_5004_50043302_5_dialog_content = "해...해치웠나...?",
  ui_story_5004_50043302_6_dialog_content = "......",
  ui_story_5004_50043302_7_dialog_content = "잇히히히히히! 속았지?!",
  ui_story_5004_50043302_8_dialog_content = "!!",
  ui_story_5004_50043302_9_dialog_content = "스모키!",
  ui_story_5004_50043302_10_dialog_content = "아, 아프잖아... 무거우니까 얼른 비켜!",
  ui_story_5004_50043302_11_dialog_content = "하... 뒤통수를 맞을 줄은 몰랐네. 덕분에 살았어, 제네비브.",
  ui_story_5004_50043302_12_dialog_content = "잠깐만! 상처가 너무 심하잖아! 얼른 라파엘한테 치료부터 받아!",
  ui_story_5004_50043302_13_dialog_content = "(제길, 아무리 공격해도 쓰러트릴 수가 없잖아...\n게다가 저 체스말 암귀들도 끝이 없어...)",
  ui_story_5004_50043302_14_dialog_content = "(말도 안 돼! 지금까지 암귀로 변한 녀석들 중에... 이런 힘은 없었다고!)",
  ui_story_5004_50043302_15_dialog_content = "(설마 저 군주란 녀석...)",
  ui_story_5004_50043302_16_dialog_content = "PlayerName! 집중해! 전세는 언제든지 뒤집을 수 있어. 금방 기회가 올지도 몰라!",
  ui_story_5004_50043302_17_dialog_content = "빈틈이 보이지 않게 조심해.",
  ui_story_5004_50043302_18_dialog_content = "너희들... 거기서 뭘 속닥거리고 있어? 큰 소리로 말해야지...\n너희 유언을 일기에 적을 수가 없잖아!",
  ui_story_5004_50043302_19_dialog_content = "피어나라!",
  ui_story_5004_50043302_20_dialog_content = "콜록! 연기가 짙어서 아무것도 안 보여...\n막아내면서 수정을 폭발시켜 반격한 거야?",
  ui_story_5004_50043302_21_dialog_content = "......",
  ui_story_5004_50043302_22_dialog_content = "좋아. 나쁘지 않아.",
  ui_story_5004_50043302_23_dialog_content = "효과가... 없었어...",
  ui_story_5004_50043302_24_dialog_content = "이런... 어떻게 멀쩡할 수가 있는 거지?",
  ui_story_5004_50043302_25_dialog_content = "아냐... 뭔가 이상해...",
  ui_story_5004_50043302_26_dialog_content = "하찮은 잔재주일 뿐이지만, 실험체치고는 아주 잘했어.",
  ui_story_5004_50043302_27_dialog_content = "하지만... 불쌍한 베릴, 넌 그저 처량한 실패작일 뿐이야.",
  ui_story_5004_50043302_28_dialog_content = "넌 지금도... 그때랑 똑같이 쓸모없어.",
  ui_story_5004_50043302_29_dialog_content = "그렇게 많은 사람을 죽이고... 네 부모까지 죽인 네가...\n지금 남을 구하겠다는 거야?",
  ui_story_5004_50043302_30_dialog_content = "내가 경고했잖아... 넌 네가 사랑하는 사람들을 모두 죽게 만들고,\n끝없는 심연의 밑바닥으로 가라앉을 거라고.",
  ui_story_5004_50043302_31_dialog_content = "아... 아냐...",
  ui_story_5004_50043302_32_dialog_content = "부모님을...?",
  ui_story_5004_50043302_33_dialog_content = "크오오오오!",
  ui_story_5004_50043302_34_dialog_content = "저리 비켜! 방해하지 마!",
  ui_story_5004_50043302_35_dialog_content = "카렌, 바이스! 라파엘을 엄호해 줘!",
  ui_story_5004_50043302_36_dialog_content = "무방비 상태인 네 부모를 네가 얼마나 처참하게 죽였는지...\n넌 분명히 기억하고 있을 거야...",
  ui_story_5004_50043302_37_dialog_content = "죽음을 받아들여... 그러면 네 죗값을 치르고 해방될 수 있어.",
  ui_story_5004_50043302_38_dialog_content = "모두... 미안해... 아빠... 엄마... 미안해...",
  ui_story_5004_50043302_39_dialog_content = "베릴!",
  ui_story_5004_50043302_40_dialog_content = "베릴... 그런 녀석 말을 믿지 마! 부모님을 죽인 건 저 녀석이라고!",
  ui_story_5004_50043302_41_dialog_content = "그때 네가 힘을 제어하지 못해서 불이 난 건 맞아...\n하지만 그 뒤에 넌 곧바로 의식을 잃었어!",
  ui_story_5004_50043302_42_dialog_content = "저 녀석이 널 인질로 삼고 네 부모님과 가문 사람들을 죽인 거야!",
  ui_story_5004_50043302_43_dialog_content = "......",
  ui_story_5004_50043302_44_dialog_content = "이건 체포된 피로스 가문 사람이 털어놓은 사실이야! 이게 진짜 진실이라고!",
  ui_story_5004_50043302_45_dialog_content = "쓸데없는 짓을!",
  ui_story_5004_50043302_46_dialog_content = "으윽!",
  ui_story_5004_50043302_47_dialog_content = "히히힛... 아직도 방해하는 녀석이 있을 줄이야.",
  ui_story_5004_50043302_48_dialog_content = "뭐, 근데 말이지... 아하하하하하!",
  ui_story_5004_50043302_49_dialog_content = "넌 정말 믿고 있었던 거였어?!",
  ui_story_5004_50043302_50_dialog_content = "!!",
  ui_story_5004_50043302_51_dialog_content = "어때? 정신을 차렸을 때 부모님이 어떤 모습이었는지 기억해?",
  ui_story_5004_50043302_52_dialog_content = "내가 일부러 네 앞에 늘어놓은 거라고.\n네가 직접 죽인 것처럼 생각하게 말이야!",
  ui_story_5004_50043302_53_dialog_content = "멍청해. 정말, 정말 너무 멍청하다고. 그걸 진짜로 믿었다니,\n그것도 이렇게 오랫동안 말이야.",
  ui_story_5004_50043302_54_dialog_content = "...그런... 짓을...",
  ui_story_5004_50043302_55_dialog_content = "일기를 다시 읽을 때마다, 이 순간만 떠올리면 온몸이 떨릴 정도로 흥분된다니까!",
  ui_story_5004_50043302_56_dialog_content = "10여 년 동안 부모님을 죽인 게 자기인 줄 알았다니!",
  ui_story_5004_50043302_57_dialog_content = "역시 이 일기는 가장 소중한 내 보물이야!\n내가 얼마나 너희랑 함께 이 즐거움을 나누고 싶었는지 알아?!",
  ui_story_5004_50043302_58_dialog_content = "너희랑 계속 놀아준 것도 내 손으로 직접 네 그 예쁜 표정을\n기록하기 위해서였다고! 으히히히힛!",
  ui_story_5004_50043302_59_dialog_content = "어때? 기분 좋아? 친부모를 죽인 고통을 마음에 안고,\n그렇게 잔뜩 움츠리고 무서워하며 지금까지 살아왔잖아.",
  ui_story_5004_50043302_60_dialog_content = "그리고 진실을 알게 된 바로 이 순간! 네 그 표정! 정말 황홀해!",
  ui_story_5004_50043302_61_dialog_content = "그 얼굴을 통째로 벗겨서 내 일기장의 표지로 만들어야겠어!",
  ui_story_5004_50043302_62_dialog_content = "고티에! 고티에! 배신자 고티에 가문의 녀석에겐 그게 가장 걸맞은 최후니까!",
  ui_story_5004_50043302_63_dialog_content = "어떻게 그런 짓을 할 수가 있어──!",
  ui_story_5004_50043302_64_dialog_content = "너 같은 실패작이 이 완벽한 나랑 곧 부활하실 그분께 맞설 수 있을 것 같아?!",
  ui_story_5004_50043302_65_dialog_content = "내게 죄를 뒤집어씌운 거짓말도... 내 친구들을 해치려고 한 것도...",
  ui_story_5004_50043302_66_dialog_content = "절대 용서 못 해. 절대로 용서할 수 없다고──!",
  ui_story_5004_50043302_67_dialog_content = "이, 이게... 베릴이 지금까지 억누르고 있던 힘인 거야...?!",
  ui_story_5004_50043302_68_dialog_content = "안 돼... 이 정도의 힘을 그냥 방출한다면...\n너도 캐롤라인 같은 괴물이 될지도 모른다고!",
  ui_story_5004_50043302_69_dialog_content = "그때 난 약했고... 그래서 내 가족을 잃었어...\n나도 혼자 괴로워하면서 지금까지 자책감에 시달려 왔어...",
  ui_story_5004_50043302_70_dialog_content = "그리고 그 모든 원흉이 지금 내 눈앞에 있어.\n게다가 소중한 사람을 해치려 하고 있다고!",
  ui_story_5004_50043302_71_dialog_content = "캐롤라인 피로스!",
  ui_story_5004_50043302_72_dialog_content = "더는 힘을 제어할 수 없게 된대도... 괴물이 되어버린대도 상관없어.\n반드시 널 지옥까지 함께 데려갈 테니까!",
  ui_story_5004_50043302_73_dialog_content = "엄청난 공격이야...",
  ui_story_5004_50043302_74_dialog_content = "캐롤라인을 붙잡았어! 안 돼... 수정으로 붙잡을 순 있어도... 제대로 쓰러트릴 순 없어!",
  ui_story_5004_50043302_75_dialog_content = "하찮은 공격이네──! 왕이시여! 제게 더 큰 힘을 주세요!\n저 분수도 모르는 반역자들을 심판할 힘을!",
  ui_story_5004_50043302_76_dialog_content = "......",
  ui_story_5004_50043302_77_dialog_content = "아! 이제야 알겠어! 내 추측이긴 하지만...",
  ui_story_5004_50043302_78_dialog_content = "캐롤라인의 힘은 저 적막의 군주와 관계가 있는 것 같아!",
  ui_story_5004_50043302_79_dialog_content = "다들 녀석을 집중 공격해! 캐롤라인이 붙잡혀 있는 동안!",
  ui_story_5004_50043402_1_dialog_content = "...!",
  ui_story_5004_50043402_2_dialog_content = "이런...! 이 열등한 벌레들이 감히!",
  ui_story_5004_50043402_3_dialog_content = "내 오랜 염원을 망치다니!",
  ui_story_5004_50043402_4_dialog_content = "이제부턴 우리가 반격할 차례라고!",
  ui_story_5004_50043402_5_dialog_content = "날 다치게 한 죄는 그 목숨으로 받아내야겠어!",
  ui_story_5004_50043402_6_dialog_content = "말도 안 돼... 말도 안 돼! 절대 너희 같은 벌레들한테 질 리가 없다고!",
  ui_story_5004_50043402_7_dialog_content = "너희들은 기껏해야 체스말일 뿐이야... 이건 말도 안 돼...\n난 백야성의 수정학자... 그리고 이곳의... 왕비라고!",
  ui_story_5004_50043402_8_dialog_content = "왕이시여! 제게 힘을 주세요! 어째서... 당신 목소리가 들리지 않는 거죠?!",
  ui_story_5004_50043402_9_dialog_content = "아직... 안 끝났어... 아직 끝이 아니라고! 내 다과회... 난...!",
  ui_story_5004_50043402_10_dialog_content = "너흴 저주하겠어! 우리... 아직 디저트가 많아...\n맛있는 오로리안! 비열한 놈들! 배신자들!",
  ui_story_5004_50043402_11_dialog_content = "너흴 영원히 가둬두겠어──!",
  ui_story_5004_50043402_12_dialog_content = "네 헛소리는 이제 듣고 싶지 않아...! 사라져버려...!",
  ui_story_5004_50043402_13_dialog_content = "다과회를... 망치게 둘 수... 으아아아악──!",
  ui_story_5004_50043402_14_dialog_content = "후... 후우...",
  ui_story_5004_50043402_15_dialog_content = "이, 이번엔... 정말 이긴 건가...?",
  ui_story_5004_50043402_16_dialog_content = "베릴! 수정이 왜 이렇게 많아진 거야?!",
  ui_story_5004_50043402_17_dialog_content = "괜찮아... 라파엘, 너랑 모두가 무사하면 그걸로 됐어...",
  ui_story_5004_50043402_18_dialog_content = "드디어... 가족의 원수를 갚고... 널 지켜냈어... 다행이야...",
  ui_story_5004_50043402_19_dialog_content = "베릴? 베릴! 정신 차려! 잠들면 안 돼!",
  ui_story_5004_50043402_20_dialog_content = "안 되겠어, PlayerName! 지금 바로 베릴을 백야성으로 데려가야 해!",
  ui_story_5004_50043402_21_dialog_content = "근데 아직 보나시외를 못 찾았어... 그리고 여기서 어떻게 나가는지도...",
  ui_story_5004_50043402_22_dialog_content = "잠깐만! 땅이 갈라지고 있어!",
  ui_story_5004_50043402_23_dialog_content = "다들 조심해!",
  ui_story_5004_50043402_24_dialog_content = "!!!",
  ui_story_5004_50043402_25_dialog_content = "이번엔 또 어디로 떨어지는 거야아아아──!",
  ui_story_5004_50043402_26_dialog_content = "너흴 영원히 가둬두겠어──!",
  ui_story_5004_50043402_27_dialog_content = "연회의... 의식... 다과회는... 영원히 끝나지 않아...",
  ui_story_5004_50043402_28_dialog_content = "키힉... 키히히히힉..."
}
